CREATE POLICY approved_labels_admin_select ON public.proc_approved_company_labels_20261015 AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM proc_profiles p
  WHERE ((p.id = auth.uid()) AND (p.active = true) AND (p.role = 'admin'::text)))));

CREATE POLICY company_contacts_manage ON public.proc_company_contacts AS PERMISSIVE FOR ALL TO authenticated USING ((private.proc_access_allowed() AND private.proc_is_role(ARRAY['admin'::text]) AND private.proc_has_permission('company_lists.manage'::text))) WITH CHECK ((private.proc_access_allowed() AND private.proc_is_role(ARRAY['admin'::text]) AND private.proc_has_permission('company_lists.manage'::text) AND (EXISTS ( SELECT 1
   FROM proc_suppliers
  WHERE ((proc_suppliers.id = proc_company_contacts.supplier_id) AND proc_suppliers.active AND (proc_suppliers.supplier_kind = 'company'::text))))));

CREATE POLICY proc_price_documents_insert ON public.proc_company_price_documents AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((private.proc_is_role(ARRAY['admin'::text]) OR (private.proc_is_role(ARRAY['document_assistant'::text]) AND (document_kind = ANY (ARRAY['mrp_original'::text, 'mrp_staff'::text])) AND (EXISTS ( SELECT 1
   FROM proc_company_price_lists pl
  WHERE ((pl.id = proc_company_price_documents.price_list_id) AND (pl.list_type = 'mrp'::text)))))));

CREATE POLICY proc_price_documents_read ON public.proc_company_price_documents AS PERMISSIVE FOR SELECT TO authenticated USING ((private.proc_is_role(ARRAY['admin'::text]) OR (EXISTS ( SELECT 1
   FROM proc_company_price_lists pl
  WHERE ((pl.id = proc_company_price_documents.price_list_id) AND ((private.proc_is_role(ARRAY['document_assistant'::text]) AND (pl.list_type = 'mrp'::text) AND (proc_company_price_documents.document_kind = ANY (ARRAY['mrp_original'::text, 'mrp_staff'::text]))) OR ((proc_company_price_documents.visible_to_staff = true) AND (pl.list_type = 'mrp'::text) AND (pl.status = 'approved'::text) AND (pl.is_current = true) AND (proc_company_price_documents.document_kind = 'mrp_staff'::text))))))));

CREATE POLICY proc_price_lines_insert ON public.proc_company_price_list_lines AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((private.proc_is_role(ARRAY['admin'::text]) OR (private.proc_is_role(ARRAY['document_assistant'::text]) AND (EXISTS ( SELECT 1
   FROM proc_company_price_lists pl
  WHERE ((pl.id = proc_company_price_list_lines.price_list_id) AND (pl.list_type = 'mrp'::text) AND (pl.status = ANY (ARRAY['draft'::text, 'pending_approval'::text]))))))));

CREATE POLICY proc_price_lines_read ON public.proc_company_price_list_lines AS PERMISSIVE FOR SELECT TO authenticated USING ((private.proc_is_role(ARRAY['admin'::text]) OR (EXISTS ( SELECT 1
   FROM proc_company_price_lists pl
  WHERE ((pl.id = proc_company_price_list_lines.price_list_id) AND ((private.proc_is_role(ARRAY['document_assistant'::text]) AND (pl.list_type = 'mrp'::text)) OR ((pl.list_type = 'mrp'::text) AND (pl.status = 'approved'::text) AND (pl.is_current = true) AND (private.proc_current_role() IS NOT NULL))))))));

CREATE POLICY proc_count_lines_insert ON public.proc_stock_count_lines AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM proc_stock_counts c
  WHERE ((c.id = proc_stock_count_lines.count_id) AND (c.status = 'draft'::text) AND ((c.counted_by = ( SELECT auth.uid() AS uid)) OR private.proc_is_role(ARRAY['admin'::text, 'procurement'::text]))))));

