CREATE OR REPLACE FUNCTION private.proc_access_reason()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.proc_access_rules;
begin
 if not exists(select 1 from public.proc_profiles p join public.proc_roles pr on pr.role_key=p.role_key
  where p.id=auth.uid() and p.active and p.deleted_at is null and pr.enabled and p.role=pr.base_role) then return 'disabled';end if;
 if private.proc_access_super_admin() then return 'allowed';end if;
 r:=private.proc_access_rule();
 if r.scope_id is null then return 'disabled';end if;
 if r.time_enabled and not private.proc_access_in_window(r.days,r.start_time,r.end_time) then return 'outside_hours';end if;
 if r.location_enabled and not exists(select 1 from private.proc_access_leases l
  where l.user_id=auth.uid() and l.session_id=nullif(auth.jwt()->>'session_id','')::uuid
    and l.revision=r.revision and l.expires_at>now()) then return 'location_required';end if;
 return 'allowed';
end $function$

CREATE OR REPLACE FUNCTION private.proc_add_requirement_impl(p_item_id uuid, p_required_qty numeric, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller uuid:=auth.uid();
  caller_role text;
  loc uuid;
  r public.proc_requirements;
  req_no text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler') then raise exception 'Not authorized'; end if;
  if p_required_qty is null or p_required_qty<=0 then raise exception 'Required quantity must be greater than zero'; end if;
  if not exists(select 1 from public.proc_items where id=p_item_id and active=true) then raise exception 'Invalid item'; end if;

  loc:=private.proc_default_location_id();
  if loc is null then raise exception 'Default stock location is not configured'; end if;

  select * into r
  from public.proc_requirements
  where item_id=p_item_id
    and location_id=loc
    and status not in ('closed','cancelled','received')
    and (
      source_type='manual'
      or (source_type='normal' and source_count_line_id is null)
    )
  order by created_at desc
  limit 1
  for update;

  if r.id is not null then
    if r.ordered_qty>0 or r.received_qty>0 then
      raise exception 'This item already has a committed procurement requirement';
    end if;
    update public.proc_requirements
    set required_qty=p_required_qty,
        adjusted_qty=p_required_qty,
        notes=p_notes,
        source_type='manual',
        approval_status='pending_review',
        selected_for_order=false,
        approved_by=null,
        approved_at=null,
        hold_reason=null,
        status='open',
        updated_at=now()
    where id=r.id;
    return r.id;
  end if;

  req_no:='REQ-M-'||to_char(clock_timestamp(),'YYMMDDHH24MISSMS');
  insert into public.proc_requirements(
    requirement_no,item_id,location_id,required_qty,adjusted_qty,status,
    notes,approval_status,selected_for_order,created_by,source_type
  )
  values(
    req_no,p_item_id,loc,p_required_qty,p_required_qty,'open',
    p_notes,'pending_review',false,caller,'manual'
  )
  returning id into r.id;

  return r.id;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_admin_delete_user_impl(p_user_id uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.proc_profiles; caller uuid:=auth.uid();
begin
 if caller is null or not private.proc_is_role(array['admin']) or not private.proc_has_permission('admin.users.manage') then
  raise exception 'Only an active procurement administrator can delete users' using errcode='42501';
 end if;
 if p_user_id=caller then raise exception 'You cannot delete your own account';end if;
 -- Serialize with role changes and deactivation as well as other deletions.
 lock table public.proc_profiles in share row exclusive mode;
 select * into target from public.proc_profiles where id=p_user_id for update;
 if target.id is null then raise exception 'User not found';end if;
 if p_confirmation is distinct from 'DELETE '||target.display_name then raise exception 'Type the exact confirmation phrase';end if;
 if target.deleted_at is not null then return jsonb_build_object('ok',true,'user_id',target.id);end if;
 if target.role_key='admin' and target.active and not exists(
  select 1 from public.proc_profiles where id<>target.id and role_key='admin' and active and deleted_at is null
 ) then raise exception 'The last active Super Admin cannot be deleted';end if;
 update public.proc_profiles set active=false,deleted_at=now(),deleted_by=caller,updated_at=now() where id=target.id;
 update public.app_users set custom_data=coalesce(custom_data,'{}'::jsonb)||jsonb_build_object('gh_procurement_access',false),updated_at=now() where id=target.id;
 update public.proc_user_invites set status='revoked',updated_at=now() where invited_user_id=target.id and status='pending';
 delete from public.proc_user_directory where user_id=target.id;
 insert into public.proc_audit_logs(table_name,record_id,action,old_data,new_data,user_id)
 values('proc_profiles',target.id,'DELETE',to_jsonb(target),jsonb_build_object('deleted_at',now(),'active',false,'scope','gh_procurement'),caller);
 return jsonb_build_object('ok',true,'user_id',target.id);
end $function$

CREATE OR REPLACE FUNCTION private.proc_can_read_procurement_storage(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r text;
begin
  if auth.uid() is null then return false; end if;
  select role into r from public.proc_profiles where id=auth.uid() and active=true;
  if r is null then return false; end if;

  if p_name not like 'company-price-lists/%' then
    return true;
  end if;

  if r='admin' then return true; end if;

  return exists(
    select 1
    from public.proc_company_price_documents d
    join public.proc_company_price_lists pl on pl.id=d.price_list_id
    where d.storage_path=p_name
      and (
        (r='document_assistant' and pl.list_type='mrp' and d.document_kind in ('mrp_original','mrp_staff'))
        or (
          d.visible_to_staff=true
          and d.document_kind='mrp_staff'
          and pl.list_type='mrp'
          and pl.status='approved'
          and pl.is_current=true
        )
      )
  );
end $function$

CREATE OR REPLACE FUNCTION private.proc_company_attachment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.storage_path not like 'company-attachments/'||new.company_id::text||'/%' or new.mime_type not in ('application/pdf','image/png','image/jpeg','image/webp') then raise exception 'Invalid company attachment path or type';end if;
 if new.po_id is not null and not exists(select 1 from public.proc_purchase_orders where id=new.po_id and company_id=new.company_id) then raise exception 'Order does not belong to this company';end if;
 if new.item_id is not null and not exists(select 1 from public.proc_company_list_items where item_id=new.item_id and company_id=new.company_id and active) then raise exception 'Item does not belong to this company';end if;
 if new.quote_id is not null and not exists(select 1 from public.proc_quotes where id=new.quote_id and supplier_id=new.supplier_id) then raise exception 'Quotation does not belong to the selected supplier';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_company_auto_from_count(p_company_id uuid, p_count_id uuid, p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform private.proc_assert_access();
 if not private.proc_has_permission('stock.count.enter') or not exists(select 1 from public.proc_stock_counts where id=p_count_id and counted_by=auth.uid() and status='submitted')
 or exists(select 1 from unnest(p_ids) x where not exists(select 1 from public.proc_requirements r join public.proc_stock_count_lines l on l.id=r.source_count_line_id where r.id=x and r.company_id=p_company_id and l.count_id=p_count_id)) then raise exception 'Invalid company auto-approval scope';end if;
 return private.proc_company_direct_orders(p_company_id,p_ids,true);
end $function$

CREATE OR REPLACE FUNCTION private.proc_company_claim_send(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q public.proc_company_dispatch_queue;c public.proc_companies;po public.proc_purchase_orders;s public.proc_suppliers;lines jsonb;attachments jsonb;
begin
 perform private.proc_assert_access();
 if not private.proc_has_permission('company_lists.view') then raise exception 'Company list access required';end if;
 select * into q from public.proc_company_dispatch_queue where id=p_id and status in ('pending','failed') for update;
 if q.id is null then return null;end if;
 select * into c from public.proc_companies where id=q.company_id and active;
 select * into po from public.proc_purchase_orders where id=q.po_id and company_id=c.id and quantity_only and status='approved';
 if po.id is null then raise exception 'Company order is not eligible for automatic sending';end if;
 -- A queued image is an approved document, not permission to send stale quantities.
 if exists(select 1 from public.proc_po_lines l join public.proc_requirements r on r.id=l.requirement_id
   where l.po_id=po.id and (l.cancelled_qty>0 or r.required_qty<>r.ordered_qty or r.received_qty>=r.ordered_qty or exists(
    select 1 from public.proc_rfq_items ri join public.proc_rfqs rf on rf.id=ri.rfq_id
    join public.proc_requirements other on other.id=ri.requirement_id
    where other.item_id=r.item_id and other.location_id=r.location_id
    and rf.status in ('draft','prepared','sent','partially_quoted','quoted'))))
 then raise exception 'Stock need or order balance changed. Review this queued PO before sending; no image was sent';end if;
 if exists(select 1 from public.proc_po_lines l cross join lateral private.proc_company_effective_route(c.id,l.item_id) route_info(route) where l.po_id=po.id and (route_info.route->>'mode'<>'direct' or coalesce((route_info.route->>'auto_send')::boolean,false)=false or (route_info.route->'supplier_ids'->>0)::uuid is distinct from po.supplier_id)) then raise exception 'Company order route or recipient has changed; review queued order before sending';end if;
 -- Stock staff can process orders only when admin configured automatic approval.
 if not private.proc_has_permission('company_lists.manage') and not((c.auto_approve or c.group_auto_approve) and private.proc_has_permission('stock.count.enter')) then raise exception 'Admin-approved sending required';end if;
 select * into s from public.proc_suppliers where id=po.supplier_id and active and supplier_kind='company';
 if s.id is null then raise exception 'Company supplier unavailable';end if;
 select jsonb_agg(jsonb_build_object('description',i.description,'brand',i.brand,'size',i.size,'colour',i.colour,'variation',i.variation,'uom',i.uom,'qty',l.qty,'remarks',i.remarks) order by i.description,l.id) into lines from public.proc_po_lines l join public.proc_items i on i.id=l.item_id where l.po_id=po.id;
 select coalesce(jsonb_agg(jsonb_build_object('name',name,'storage_path',storage_path,'mime_type',mime_type,'remarks',remarks,'discount_percent',discount_percent,'discount_amount',discount_amount)),'[]') into attachments from public.proc_company_attachments where company_id=c.id and send_with_order and kind in ('price_list','order') and (po_id is null or po_id=po.id) and (supplier_id is null or supplier_id=s.id) and (item_id is null or exists(select 1 from public.proc_po_lines where po_id=po.id and proc_po_lines.item_id=proc_company_attachments.item_id));
 update public.proc_company_dispatch_queue set status='sending',claimed_by=auth.uid(),last_error=null,updated_at=now() where id=q.id;
 return jsonb_build_object('id',q.id,'po_id',po.id,'po_no',po.po_no,'phone',coalesce(s.whatsapp,s.phone),'supplier',s.name,'company',c.name,'template',po.company_document_template,'lines',lines,'attachments',attachments);
end $function$

CREATE OR REPLACE FUNCTION private.proc_company_config_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform private.proc_assert_access();
 if tg_op='INSERT' or new.auto_approve is distinct from old.auto_approve or new.auto_send is distinct from old.auto_send or new.order_route is distinct from old.order_route or new.default_supplier_id is distinct from old.default_supplier_id or new.visible_fields is distinct from old.visible_fields then
  if not private.proc_has_permission('company_lists.manage') or not private.proc_is_role(array['admin']) then raise exception 'Only an administrator may configure company orders';end if;
  new.automation_admin_id:=auth.uid();
 end if;
 if new.default_supplier_id is not null and not exists(select 1 from public.proc_suppliers where id=new.default_supplier_id and active and supplier_kind='company') then raise exception 'Select an active company supplier contact';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_company_direct_orders(p_company_id uuid, p_requirement_ids uuid[], p_auto boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.proc_companies;r record;po_v jsonb;po_id_v uuid;po_no_v text;qty_v numeric;claims_v text;sub_v text;actor uuid;result jsonb:='[]';route_v jsonb;supplier_v uuid;send_v boolean;
begin
 perform private.proc_assert_access();
 select * into c from public.proc_companies where id=p_company_id and active for update;
 if c.id is null then return result;end if;
 if p_auto then
  if not private.proc_has_permission('stock.count.enter') or (not (c.auto_approve or c.group_auto_approve) and not exists (
   select 1 from public.proc_requirements req
   cross join lateral private.proc_company_effective_route(c.id,req.item_id) rt(route)
   where req.id=any(p_requirement_ids) and req.company_id=c.id
   and rt.route->>'mode'='direct' and coalesce((rt.route->>'explicit')::boolean,false)
   and coalesce((rt.route->>'auto_send')::boolean,false)
  )) then raise exception 'Automatic company approval is not enabled';end if;
  actor:=c.automation_admin_id;
 else
  if not private.proc_is_role(array['admin']) or not private.proc_has_permission('procurement.orders.approve') then raise exception 'Administrator approval required';end if;actor:=auth.uid();
 end if;
 if not exists(select 1 from public.proc_profiles where id=actor and active and role='admin') then raise exception 'Company automation approving admin is inactive';end if;
 claims_v:=current_setting('request.jwt.claims',true);sub_v:=current_setting('request.jwt.claim.sub',true);
 begin
  perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',actor::text,true);
  for r in select rr.* from public.proc_requirements rr where rr.id=any(p_requirement_ids) and rr.company_id=c.id and rr.status not in ('closed','cancelled','received') and rr.adjusted_qty>rr.ordered_qty order by rr.id for update of rr loop
   route_v:=private.proc_company_effective_route(c.id,r.item_id);
   if route_v->>'mode'<>'direct' then continue;end if;
   if jsonb_array_length(route_v->'supplier_ids')<>1 then raise exception 'Direct orders require exactly one active supplier for every item';end if;
   supplier_v:=(route_v->'supplier_ids'->>0)::uuid;
   send_v:=coalesce((route_v->>'auto_send')::boolean,false);
   -- Automatic submission only includes explicit opted-in routes or pre-existing company-level approval.
   if p_auto and ((route_v->>'explicit')::boolean and not send_v or not (route_v->>'explicit')::boolean and not c.auto_approve) then continue;end if;
   -- Existing orders include other requirements and suppliers for the same item/location.
   -- Explicit manual approval can order a reviewed delta; recount automation cannot.
   if p_auto and (exists(select 1 from private.proc_company_open_orders(r.item_id,r.location_id)) or exists(
    select 1 from public.proc_rfq_items ri join public.proc_rfqs q on q.id=ri.rfq_id
    join public.proc_requirements other on other.id=ri.requirement_id
    where other.item_id=r.item_id and other.location_id=r.location_id and q.status in ('draft','prepared','sent','partially_quoted','quoted')
   )) then continue;end if;
   qty_v:=r.adjusted_qty-r.ordered_qty;
   if supplier_v is null or not exists(select 1 from public.proc_suppliers where id=supplier_v and active and supplier_kind='company') then raise exception 'Set an active company supplier contact for every ordered brand';end if;
   select (value->>'id')::uuid into po_id_v from jsonb_array_elements(result) where value->>'supplier_id'=supplier_v::text and (value->>'auto_send')::boolean=send_v and value->>'route_id' IS NOT DISTINCT FROM route_v->>'route_id';
   if po_id_v is null then
    insert into public.proc_purchase_orders(po_no,supplier_id,status,created_by,company_id,quantity_only,notes,terms,company_document_template)
    values('COMPANY-'||gen_random_uuid(),supplier_v,'pending_approval',actor,c.id,true,'Company quantity-only order. Price not requested.','Quantity only; supplier to confirm availability and delivery.',coalesce(route_v->'template','{}')) returning id,po_no into po_id_v,po_no_v;
    result:=result||jsonb_build_array(jsonb_build_object('id',po_id_v,'po_no',po_no_v,'supplier_id',supplier_v,'auto_send',send_v,'route_id',route_v->>'route_id'));
   end if;
   insert into public.proc_po_lines(po_id,requirement_id,item_id,qty,unit_price,discount_percent,tax_percent) values(po_id_v,r.id,r.item_id,qty_v,0,0,0);
   update public.proc_requirements set ordered_qty=ordered_qty+qty_v,status='ordered',approval_status='approved',selected_for_order=true,approved_by=actor,approved_at=now() where id=r.id;
  end loop;
  for po_v in select value from jsonb_array_elements(result) loop
   po_id_v:=(po_v->>'id')::uuid;
   perform public.proc_approve_po_v2(po_id_v);
   update public.proc_purchase_orders set auto_approved=p_auto,auto_approval_reason=case when p_auto then 'Company auto-approve configured by administrator' end where id=po_id_v;
   if coalesce((po_v->>'auto_send')::boolean,false) then insert into public.proc_company_dispatch_queue(po_id,company_id) values(po_id_v,c.id) on conflict(po_id) do nothing;end if;
  end loop;
  perform set_config('request.jwt.claims',coalesce(claims_v,''),true);perform set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);
 exception when others then perform set_config('request.jwt.claims',coalesce(claims_v,''),true);perform set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);raise;end;
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.proc_company_effective_route(p_company_id uuid, p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.proc_companies;section_v uuid;route_id_v uuid;route_section_v uuid;
 mode_v text;send_v boolean;suppliers_v uuid[];legacy_supplier uuid;template_v jsonb;
BEGIN
 SELECT * INTO c FROM public.proc_companies WHERE id=p_company_id AND active;
 IF c.id IS NULL THEN RAISE EXCEPTION 'Company unavailable';END IF;
 SELECT section_id INTO section_v FROM public.proc_company_list_items
 WHERE company_id=p_company_id AND item_id=p_item_id AND active LIMIT 1;
 WITH RECURSIVE trail(id,parent_id,depth) AS(
  SELECT id,parent_id,0 FROM public.proc_company_sections WHERE id=section_v AND company_id=p_company_id AND active
  UNION ALL
  SELECT parent.id,parent.parent_id,trail.depth+1
   FROM public.proc_company_sections parent JOIN trail ON parent.id=trail.parent_id
   WHERE parent.company_id=p_company_id AND parent.active
 )
 SELECT cfg.id,cfg.section_id,cfg.route_mode,cfg.auto_send INTO route_id_v,route_section_v,mode_v,send_v
 FROM trail JOIN public.proc_company_section_routes cfg ON cfg.section_id=trail.id AND cfg.company_id=p_company_id
 ORDER BY trail.depth ASC LIMIT 1;
 IF route_id_v IS NULL THEN SELECT id,section_id,route_mode,auto_send INTO route_id_v,route_section_v,mode_v,send_v FROM public.proc_company_section_routes WHERE company_id=p_company_id AND section_id IS NULL;END IF;
 IF route_id_v IS NOT NULL THEN
  SELECT document_template INTO template_v FROM public.proc_company_section_routes WHERE id=route_id_v;
  SELECT array_agg(rs.supplier_id ORDER BY rs.sort_order,rs.supplier_id) INTO suppliers_v
  FROM public.proc_company_section_route_suppliers rs JOIN public.proc_suppliers s ON s.id=rs.supplier_id
  WHERE rs.route_id=route_id_v AND s.active AND s.supplier_kind='company';
  RETURN jsonb_build_object('mode',mode_v,'auto_send',send_v,'supplier_ids',coalesce(to_jsonb(suppliers_v),'[]'::jsonb),
   'route_id',route_id_v,'template',template_v,'route_section_id',route_section_v,'explicit',true);
 END IF;
 SELECT coalesce((SELECT cc.supplier_id FROM public.proc_company_contacts cc JOIN public.proc_items i ON i.id=p_item_id
  WHERE cc.company_id=p_company_id AND cc.brand=coalesce(i.brand,'') LIMIT 1),c.default_supplier_id) INTO legacy_supplier;
 IF legacy_supplier IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.proc_suppliers
  WHERE id=legacy_supplier AND active AND supplier_kind='company') THEN legacy_supplier:=NULL;END IF;
 RETURN jsonb_build_object('mode',c.order_route,'auto_send',c.auto_send,
  'supplier_ids',CASE WHEN legacy_supplier IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(legacy_supplier) END,
  'route_section_id',NULL,'explicit',false);
END $function$

CREATE OR REPLACE FUNCTION private.proc_company_ensure_section_path(p_company uuid, p_path text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE parent uuid; part text; new_id uuid; seen text[]:=ARRAY[]::text[];
BEGIN
 FOREACH part IN ARRAY p_path LOOP
  part=nullif(btrim(part),''); IF part IS NULL THEN CONTINUE; END IF;
  -- Existing supplier sheets commonly repeat the company name in Category and
  -- Main Group; avoid duplicate headers such as Orange / Orange / Switches.
  IF lower(part)=ANY(seen) THEN CONTINUE; END IF;
  seen=array_append(seen,lower(part));
  SELECT id INTO new_id FROM public.proc_company_sections
   WHERE company_id=p_company AND parent_id IS NOT DISTINCT FROM parent AND lower(name)=lower(part) AND active
   ORDER BY id LIMIT 1;
  IF new_id IS NULL THEN
   INSERT INTO public.proc_company_sections(company_id,parent_id,name,sort_order)
    VALUES(p_company,parent,part,0) ON CONFLICT DO NOTHING RETURNING id INTO new_id;
   IF new_id IS NULL THEN
    SELECT id INTO new_id FROM public.proc_company_sections
     WHERE company_id=p_company AND parent_id IS NOT DISTINCT FROM parent AND lower(name)=lower(part) AND active LIMIT 1;
   END IF;
  END IF;
  parent=new_id;new_id=NULL;
 END LOOP;
 RETURN parent;
END $function$

CREATE OR REPLACE FUNCTION private.proc_company_finish_send(p_id uuid, p_status text, p_message_id text, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q public.proc_company_dispatch_queue;c public.proc_companies;claims_v text;sub_v text;
begin
 perform private.proc_assert_access();
 if p_status not in ('accepted','failed','unknown') then raise exception 'Invalid dispatch outcome';end if;
 select * into q from public.proc_company_dispatch_queue where id=p_id and status='sending' and claimed_by=auth.uid() for update;
 if q.id is null then raise exception 'Dispatch is not owned by this caller';end if;
 update public.proc_company_dispatch_queue set status=p_status,message_id=left(p_message_id,500),last_error=left(p_error,1000),updated_at=now() where id=p_id;
 if p_status='accepted' then
  select * into c from public.proc_companies where id=q.company_id;
  if not exists(select 1 from public.proc_profiles where id=c.automation_admin_id and active and role='admin') then raise exception 'Automation admin no longer active; verify accepted send before updating order';end if;
  claims_v:=current_setting('request.jwt.claims',true);sub_v:=current_setting('request.jwt.claim.sub',true);
  begin
   perform set_config('request.jwt.claims',jsonb_build_object('sub',c.automation_admin_id,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',c.automation_admin_id::text,true);
   update public.proc_purchase_orders set status='sent',sent_at=now() where id=q.po_id and status='approved';
   perform set_config('request.jwt.claims',coalesce(claims_v,''),true);perform set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);
  exception when others then perform set_config('request.jwt.claims',coalesce(claims_v,''),true);perform set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);raise;end;
 end if;
 -- Sent records gateway acceptance; recipient delivery is not claimed.

end $function$

CREATE OR REPLACE FUNCTION private.proc_company_link_count(p_company_id uuid, p_count_id uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ids uuid[];
begin
 perform private.proc_assert_access();
 if not private.proc_has_permission('stock.count.enter') or not exists(select 1 from public.proc_stock_counts where id=p_count_id and counted_by=auth.uid() and status='submitted') or exists(select 1 from public.proc_stock_count_lines l where l.count_id=p_count_id and not exists(select 1 from public.proc_company_list_items where company_id=p_company_id and item_id=l.item_id and active)) then raise exception 'Invalid company count scope';end if;
 update public.proc_requirements set company_id=p_company_id where source_count_line_id in(select id from public.proc_stock_count_lines where count_id=p_count_id);
 select array_agg(id) into ids from public.proc_requirements where company_id=p_company_id and source_count_line_id in(select id from public.proc_stock_count_lines where count_id=p_count_id) and adjusted_qty>ordered_qty;
 return ids;
end $function$

CREATE OR REPLACE FUNCTION private.proc_company_validate_section()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE parent_company uuid;
BEGIN
 IF NEW.parent_id IS NOT NULL THEN
  SELECT company_id INTO parent_company FROM public.proc_company_sections WHERE id=NEW.parent_id AND active;
  IF parent_company IS DISTINCT FROM NEW.company_id THEN RAISE EXCEPTION 'Parent section must belong to the same company'; END IF;
  IF NEW.id IS NOT NULL AND EXISTS (
   WITH RECURSIVE ancestors AS (
    SELECT id,parent_id FROM public.proc_company_sections WHERE id=NEW.parent_id
    UNION ALL SELECT p.id,p.parent_id FROM public.proc_company_sections p JOIN ancestors a ON p.id=a.parent_id
   ) SELECT 1 FROM ancestors WHERE id=NEW.id
  ) THEN RAISE EXCEPTION 'A section cannot be moved into one of its descendants'; END IF;
 END IF;
 NEW.name=btrim(NEW.name);
 NEW.updated_at=now();
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.proc_create_best_price_pos_impl(p_rfq_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$
declare
  caller uuid := auth.uid();
  caller_role text;
  rfq_rec public.proc_rfqs;
  item_rec record;
  quote_rec record;
  map_rec record;
  po_map jsonb := '{}'::jsonb;
  v_po_id uuid;
  po_number text;
  supplier_key text;
  allocation numeric(14,3);
  remaining numeric(14,3);
  available numeric(14,3);
  created_any boolean := false;
  result jsonb := '[]'::jsonb;
  v_subtotal numeric(16,2);
  v_tax numeric(16,2);
  v_total numeric(16,2);
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;

  select * into rfq_rec
  from public.proc_rfqs
  where id=p_rfq_id
  for update;

  if rfq_rec.id is null then raise exception 'RFQ not found'; end if;
  if rfq_rec.status in ('awarded','closed','cancelled') then
    raise exception 'RFQ has already been awarded or closed';
  end if;

  for item_rec in
    select
      ri.id as rfq_item_id,
      ri.requirement_id,
      ri.requested_qty,
      r.item_id,
      r.adjusted_qty,
      r.ordered_qty
    from public.proc_rfq_items ri
    join public.proc_requirements r on r.id=ri.requirement_id
    where ri.rfq_id=p_rfq_id
      and ri.selected_for_po=true
      and r.status not in ('received','closed','cancelled')
      and greatest(r.adjusted_qty-r.ordered_qty,0)>0
    order by ri.id
  loop
    remaining := least(
      item_rec.requested_qty,
      greatest(item_rec.adjusted_qty-item_rec.ordered_qty,0)
    );

    for quote_rec in
      select
        q.id as quote_id,
        q.supplier_id,
        sp.supplier_code,
        ql.id as quote_line_id,
        ql.unit_price,
        ql.available_qty,
        ql.discount_percent,
        ql.tax_percent,
        round(
          ql.unit_price
          * (1-ql.discount_percent/100.0)
          * (1+ql.tax_percent/100.0),
          4
        ) as effective_unit_price
      from public.proc_quotes q
      join public.proc_quote_lines ql
        on ql.quote_id=q.id
       and ql.rfq_item_id=item_rec.rfq_item_id
      join public.proc_suppliers sp
        on sp.id=q.supplier_id
       and sp.active=true
      where q.rfq_id=p_rfq_id
        and q.status in ('received','reviewed','selected')
        and ql.unit_price>=0
      order by
        round(ql.unit_price*(1-ql.discount_percent/100.0)*(1+ql.tax_percent/100.0),4) asc,
        sp.supplier_code asc
    loop
      exit when remaining<=0;

      available := case
        when quote_rec.available_qty is null then remaining
        else greatest(quote_rec.available_qty,0)
      end;

      allocation := least(remaining,available);
      if allocation<=0 then continue; end if;

      supplier_key := quote_rec.supplier_id::text;
      if po_map ? supplier_key then
        v_po_id := (po_map->>supplier_key)::uuid;
      else
        v_po_id := gen_random_uuid();
        po_number := 'PO-' || to_char(clock_timestamp(),'YYMMDD-HH24MISSMS') || '-' || substr(replace(quote_rec.supplier_id::text,'-',''),1,4);

        insert into public.proc_purchase_orders(
          id,po_no,supplier_id,status,po_date,created_by
        ) values(
          v_po_id,po_number,quote_rec.supplier_id,'pending_approval',current_date,caller
        );

        po_map := po_map || jsonb_build_object(supplier_key,v_po_id::text);
      end if;

      insert into public.proc_po_lines(
        po_id,requirement_id,item_id,qty,unit_price,discount_percent,tax_percent
      ) values(
        v_po_id,item_rec.requirement_id,item_rec.item_id,allocation,
        quote_rec.unit_price,quote_rec.discount_percent,quote_rec.tax_percent
      );

      insert into public.proc_awards(
        rfq_item_id,supplier_id,quote_line_id,awarded_qty,unit_price,
        discount_percent,tax_percent,effective_unit_cost,awarded_by
      ) values(
        item_rec.rfq_item_id,quote_rec.supplier_id,quote_rec.quote_line_id,
        allocation,quote_rec.unit_price,quote_rec.discount_percent,
        quote_rec.tax_percent,quote_rec.effective_unit_price,caller
      );

      update public.proc_quotes
      set status='selected'
      where id=quote_rec.quote_id;

      update public.proc_requirements
      set ordered_qty=ordered_qty+allocation,
          status=case
            when ordered_qty+allocation>=adjusted_qty then 'ordered'
            else 'partially_ordered'
          end,
          updated_at=now()
      where id=item_rec.requirement_id;

      remaining := remaining-allocation;
      created_any := true;
    end loop;
  end loop;

  if not created_any then
    raise exception 'No quotable outstanding items were found';
  end if;

  for map_rec in
    select key as supplier_id_text,value #>> '{}' as po_id_text
    from jsonb_each(po_map)
  loop
    v_po_id := map_rec.po_id_text::uuid;

    select
      coalesce(sum(round(pl.qty*pl.unit_price*(1-pl.discount_percent/100.0),2)),0),
      coalesce(sum(round((pl.qty*pl.unit_price*(1-pl.discount_percent/100.0))*(pl.tax_percent/100.0),2)),0),
      coalesce(sum(pl.line_total),0)
    into v_subtotal,v_tax,v_total
    from public.proc_po_lines pl
    where pl.po_id=v_po_id;

    update public.proc_purchase_orders
    set subtotal=v_subtotal,tax_total=v_tax,total=v_total,updated_at=now()
    where id=v_po_id
    returning po_no into po_number;

    result := result || jsonb_build_array(jsonb_build_object(
      'po_id',v_po_id,
      'po_no',po_number,
      'supplier_id',map_rec.supplier_id_text::uuid,
      'subtotal',v_subtotal,
      'tax_total',v_tax,
      'total',v_total
    ));
  end loop;

  update public.proc_rfqs
  set status='awarded',updated_at=now()
  where id=p_rfq_id;

  return result;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_create_po_from_quote_impl(p_quote_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$
declare
  q public.proc_quotes;
  caller uuid := auth.uid();
  caller_role text;
  po_id uuid := gen_random_uuid();
  po_number text;
  line record;
  sub numeric(16,2) := 0;
  taxes numeric(16,2) := 0;
  line_net numeric(16,2);
  line_tax numeric(16,2);
  q_order numeric(14,3);
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;

  select * into q from public.proc_quotes where id=p_quote_id;
  if q.id is null then raise exception 'Quote not found'; end if;

  po_number := 'PO-' || to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');

  insert into public.proc_purchase_orders(id,po_no,supplier_id,status,po_date,created_by)
  values(po_id,po_number,q.supplier_id,'pending_approval',current_date,caller);

  for line in
    select ql.*, ri.requirement_id, ri.requested_qty, r.item_id, r.adjusted_qty, r.ordered_qty
    from public.proc_quote_lines ql
    join public.proc_rfq_items ri on ri.id=ql.rfq_item_id
    join public.proc_requirements r on r.id=ri.requirement_id
    where ql.quote_id=q.id
  loop
    q_order := least(
      greatest(line.adjusted_qty-line.ordered_qty,0),
      line.requested_qty,
      coalesce(line.available_qty,line.requested_qty)
    );
    if q_order <= 0 then continue; end if;

    insert into public.proc_po_lines(po_id,requirement_id,item_id,qty,unit_price,discount_percent,tax_percent)
    values(po_id,line.requirement_id,line.item_id,q_order,line.unit_price,line.discount_percent,line.tax_percent);

    line_net := round(q_order*line.unit_price*(1-line.discount_percent/100.0),2);
    line_tax := round(line_net*(line.tax_percent/100.0),2);
    sub := sub + line_net;
    taxes := taxes + line_tax;

    update public.proc_requirements
    set ordered_qty=ordered_qty+q_order,
        status=case when ordered_qty+q_order >= adjusted_qty then 'ordered' else 'partially_ordered' end,
        updated_at=now()
    where id=line.requirement_id;

    insert into public.proc_awards(rfq_item_id,supplier_id,quote_line_id,awarded_qty,unit_price,awarded_by)
    values(line.rfq_item_id,q.supplier_id,line.id,q_order,line.unit_price,caller);
  end loop;

  update public.proc_purchase_orders set subtotal=sub,tax_total=taxes,total=sub+taxes where id=po_id;
  update public.proc_quotes set status='selected' where id=q.id;
  update public.proc_rfqs set status='awarded',updated_at=now() where id=q.rfq_id;
  return po_id;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_create_rejection_case()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  g public.proc_grns;
begin
  if new.rejected_qty<=0 then return new; end if;
  select * into g from public.proc_grns where id=new.grn_id;

  insert into public.proc_rejection_cases(
    grn_line_id,grn_id,po_id,supplier_id,item_id,rejected_qty,rejection_reason,created_by
  )
  values(
    new.id,new.grn_id,g.po_id,g.supplier_id,new.item_id,new.rejected_qty,new.rejection_reason,g.received_by
  )
  on conflict(grn_line_id) do update
    set rejected_qty=excluded.rejected_qty,
        rejection_reason=excluded.rejection_reason,
        updated_at=now();

  return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_delete_record(p_table text, p_id uuid, p_token text, p_confirmation text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare preview jsonb; tab text; req uuid; reqs uuid[];
begin
 perform private.proc_assert_data_admin();
 if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Enter a reason of at least five characters';end if;
 perform pg_advisory_xact_lock(704411);
 -- Same lock order for every deletion/reset. Protect preview against concurrent edits.
 foreach tab in array private.proc_record_delete_tables() loop execute format('lock table public.%I in share row exclusive mode',tab);end loop;
 preview:=private.proc_record_delete_plan(p_table,p_id);
 if p_token is distinct from preview->>'token' then raise exception 'Linked records changed. Review deletion again.';end if;
 if p_confirmation is distinct from 'DELETE '||(preview->>'label') then raise exception 'Type the exact deletion phrase';end if;
 select array_agg(distinct requirement_id) into reqs from (select requirement_id from public.proc_po_lines where po_id in(select value::uuid from jsonb_array_elements_text(coalesce(preview->'plan'->'proc_purchase_orders','[]'))) union select requirement_id from public.proc_rfq_items where id in(select value::uuid from jsonb_array_elements_text(coalesce(preview->'plan'->'proc_rfq_items','[]')))) affected;
 if preview->'plan' ? 'proc_suppliers' then update public.proc_companies set default_supplier_id=null where default_supplier_id in(select value::uuid from jsonb_array_elements_text(preview->'plan'->'proc_suppliers'));end if;
 foreach tab in array private.proc_record_delete_tables() loop
  if preview->'plan' ? tab then execute format('delete from public.%I where id in(select value::uuid from jsonb_array_elements_text($1))',tab) using preview->'plan'->tab;end if;
 end loop;
 foreach req in array coalesce(reqs,array[]::uuid[]) loop
  update public.proc_requirements r set ordered_qty=coalesce((select sum(l.qty-l.cancelled_qty) from public.proc_po_lines l join public.proc_purchase_orders p on p.id=l.po_id where l.requirement_id=req and p.status<>'cancelled'),0),received_qty=coalesce((select sum(gl.accepted_qty) from public.proc_grn_lines gl join public.proc_po_lines l on l.id=gl.po_line_id join public.proc_grns g on g.id=gl.grn_id where l.requirement_id=req and g.status='posted'),0) where r.id=req;
  if exists(select 1 from public.proc_requirements where id=req) then perform public.proc_refresh_requirement_status(req);end if;
 end loop;
 insert into public.proc_audit_logs(table_name,record_id,action,new_data,user_id) values(p_table,p_id,'ADMIN_DELETE',jsonb_build_object('reason',trim(p_reason),'preview',preview-'plan','stock_retained',true),auth.uid());
end $function$

CREATE OR REPLACE FUNCTION private.proc_ensure_profile_impl()
 RETURNS proc_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.proc_profiles;
  au public.app_users;
  caller uuid:=auth.uid();
  requested_role text;
  requested_role_key text;
  rr public.proc_roles;
begin
  if caller is null then raise exception 'Not authenticated'; end if;

  select * into p from public.proc_profiles where id=caller;
  if p.id is not null then
    if not p.active then raise exception 'Procurement access is disabled'; end if;
    return p;
  end if;

  select * into au from public.app_users where id=caller and active=true;
  if au.id is null then raise exception 'Your GH account is not active'; end if;
  if coalesce((au.custom_data->>'gh_procurement_access')::boolean,false) is not true then
    raise exception 'GH Procurement access has not been granted to this account';
  end if;

  requested_role:=coalesce(nullif(au.custom_data->>'gh_procurement_role',''),'viewer');
  if requested_role not in ('admin','procurement','stock_handler','stock_checker','document_assistant','receiver','viewer') then
    requested_role:='viewer';
  end if;
  requested_role_key:=coalesce(nullif(au.custom_data->>'gh_procurement_role_key',''),requested_role);

  select * into rr from public.proc_roles where role_key=requested_role_key and enabled=true;
  if rr.role_key is null then
    select * into rr from public.proc_roles where role_key=requested_role and enabled=true;
  end if;
  if rr.role_key is null then raise exception 'Assigned procurement role is not available'; end if;

  insert into public.proc_profiles(id,display_name,role,role_key,active)
  values(caller,coalesce(nullif(au.display_name,''),au.email),rr.base_role,rr.role_key,true)
  on conflict(id) do nothing
  returning * into p;

  if p.id is null then select * into p from public.proc_profiles where id=caller and active=true; end if;
  if p.id is null then raise exception 'Procurement access is disabled'; end if;
  return p;
end $function$

CREATE OR REPLACE FUNCTION private.proc_finalize_award_with_variations_v1(p_rfq_id uuid, p_allocations jsonb, p_variations jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$
declare result jsonb; x jsonb; v jsonb; ql public.proc_quote_lines; q public.proc_quotes;
 base public.proc_items; req public.proc_requirements; iid uuid; rid uuid; pid uuid; n numeric; price numeric; size_v text; idx integer; po_rec record; seen text[]:='{}'; key_v text;
begin
 perform private.proc_assert_permission('procurement.orders.create');
 if auth.uid() is null then raise exception 'Not authenticated'; end if;
 if jsonb_typeof(p_variations)<>'array' or jsonb_array_length(p_variations)>1200 then raise exception 'Invalid variations'; end if;
 -- Lock quote notes before award; quantities and prices come from the saved quote, never the client.
 for x in select * from jsonb_array_elements(p_variations) loop
  select l.* into ql from public.proc_quote_lines l join public.proc_quotes quote_rec on quote_rec.id=l.quote_id where l.id=(x->>'quote_line_id')::uuid and quote_rec.rfq_id=p_rfq_id for update of l;
  if ql.id is null or not exists(select 1 from jsonb_array_elements(p_allocations) a where a->>'quote_line_id'=ql.id::text) then raise exception 'Variation must belong to an awarded quotation'; end if;
  idx:=(x->>'variant_index')::integer;
  key_v:=ql.id::text||':'||idx;
  if idx is null or idx<0 or idx>=12 or key_v=any(seen) then raise exception 'Invalid or duplicate variation'; end if;
  seen:=array_append(seen,key_v);
  if left(coalesce(ql.notes,''),18)<>'GH_QUOTE_NOTES_V1:' then raise exception 'Saved size variation required'; end if;
  v:=substring(ql.notes from 19)::jsonb->'variants'->idx;
  n:=(v->>'quantity')::numeric; price:=(v->>'price')::numeric; size_v:=trim(v->>'size');
  if n is null or n<=0 or n::text in ('NaN','Infinity','-Infinity') or price is null or price<0 or price::text in ('NaN','Infinity','-Infinity') or coalesce(length(size_v),0)=0 or length(size_v)>100 then raise exception 'Variation needs size, positive quantity and valid price'; end if;
 end loop;
 result:=public.proc_finalize_award_plan_v2(p_rfq_id,p_allocations);
 for x in select * from jsonb_array_elements(p_variations) loop
  select * into ql from public.proc_quote_lines where id=(x->>'quote_line_id')::uuid;
  select * into q from public.proc_quotes where id=ql.quote_id;
  select r.* into req from public.proc_requirements r join public.proc_rfq_items i on i.requirement_id=r.id where i.id=ql.rfq_item_id;
  select * into base from public.proc_items where id=req.item_id;
  v:=substring(ql.notes from 19)::jsonb->'variants'->((x->>'variant_index')::integer);
  n:=(v->>'quantity')::numeric; price:=(v->>'price')::numeric; size_v:=trim(v->>'size');
  select (a->>'po_id')::uuid into pid from jsonb_array_elements(result) a where a->>'supplier_id'=q.supplier_id::text;
  if pid is null then raise exception 'Supplier PO not found'; end if;
  -- Reuse an exact existing size to preserve stock and receiving identity.
  select id into iid from public.proc_items where active and description=base.description and category=base.category and uom=base.uom and coalesce(brand,'')=coalesce(base.brand,'') and lower(trim(coalesce(size,'')))=lower(size_v) order by id limit 1;
  if iid is null then
   iid:=gen_random_uuid();
   insert into public.proc_items(id,item_code,category,description,size,uom,brand,main_group,subgroup,source)
   values(iid,'VAR-'||iid,base.category,base.description,size_v,base.uom,base.brand,base.main_group,base.subgroup,'Supplier size variation');
  end if;
  rid:=gen_random_uuid();
  insert into public.proc_requirements(id,requirement_no,item_id,location_id,required_qty,adjusted_qty,ordered_qty,status,approval_status,selected_for_order,approved_by,approved_at,created_by,source_type,request_reason,notes)
  values(rid,'VAR-'||rid,iid,req.location_id,n,n,n,'ordered','approved',true,auth.uid(),now(),auth.uid(),'manual','manual_extra','Additional size from RFQ '||p_rfq_id||'; supplier quote '||ql.id||'; '||coalesce(v->>'remarks',''));
  insert into public.proc_po_lines(po_id,requirement_id,item_id,qty,unit_price,landed_unit_cost)
  values(pid,rid,iid,n,price,price);
 end loop;
 for po_rec in select (a->>'po_id')::uuid id from jsonb_array_elements(result) a loop
  update public.proc_purchase_orders p set subtotal=t.subtotal,tax_total=t.tax,total=t.goods+coalesce(p.freight_total,0),updated_at=now()
  from (select sum(round(qty*unit_price*(1-discount_percent/100),2)) subtotal,sum(round(qty*unit_price*(1-discount_percent/100)*tax_percent/100,2)) tax,sum(line_total) goods from public.proc_po_lines where po_id=po_rec.id) t where p.id=po_rec.id;
 end loop;
 return (select jsonb_agg(jsonb_build_object('po_id',p.id,'po_no',p.po_no,'supplier_id',p.supplier_id,'subtotal',p.subtotal,'tax_total',p.tax_total,'freight_total',p.freight_total,'total',p.total)) from public.proc_purchase_orders p where p.id in (select (a->>'po_id')::uuid from jsonb_array_elements(result) a));
end $function$

CREATE OR REPLACE FUNCTION private.proc_invoice_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_role text;
  po_supplier uuid;
  calc_subtotal numeric(16,2);
  calc_tax numeric(16,2);
  calc_total numeric(16,2);
  has_variance boolean;
begin
  if tg_op='INSERT' then
    if new.po_id is not null then
      select supplier_id
      into po_supplier
      from public.proc_purchase_orders
      where id=new.po_id
      for update;

      if po_supplier is null then raise exception 'Purchase order not found'; end if;
      if po_supplier<>new.supplier_id then raise exception 'Invoice supplier must match purchase order supplier'; end if;
    end if;
    return new;
  end if;

  if new.supplier_id is distinct from old.supplier_id or new.po_id is distinct from old.po_id then
    raise exception 'Invoice supplier and purchase order are immutable';
  end if;

  select
    coalesce(sum(round(il.qty*il.unit_price*(1-il.discount_percent/100.0),2)),0),
    coalesce(sum(round((il.qty*il.unit_price*(1-il.discount_percent/100.0))*(il.tax_percent/100.0),2)),0),
    coalesce(sum(round((il.qty*il.unit_price*(1-il.discount_percent/100.0))*(1+il.tax_percent/100.0),2)),0)
  into calc_subtotal,calc_tax,calc_total
  from public.proc_invoice_lines il
  where il.invoice_id=old.id;

  select exists(
    select 1
    from public.proc_invoice_lines il
    join public.proc_po_lines pl on pl.id=il.po_line_id
    where il.invoice_id=old.id
      and (
        il.qty<>pl.qty
        or il.unit_price<>pl.unit_price
        or il.discount_percent<>pl.discount_percent
        or il.tax_percent<>pl.tax_percent
      )
  ) into has_variance;

  new.subtotal:=calc_subtotal;
  new.tax_total:=calc_tax;
  new.total:=calc_total;

  if new.status in ('matched','variance','entered') then
    new.status:=case when has_variance then 'variance' else 'matched' end;
  elsif new.status in ('approved','rejected') and new.status is distinct from old.status then
    select role into caller_role from public.proc_profiles where id=auth.uid() and active=true;
    if caller_role<>'admin' then raise exception 'Only an admin can approve or reject supplier invoices'; end if;
  end if;

  if has_variance and new.variance_resolution_status='not_required' then
    new.variance_resolution_status:='open';
  elsif not has_variance and new.variance_resolution_status='open' then
    new.variance_resolution_status:='not_required';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_invoice_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  inv public.proc_supplier_invoices;
  pl public.proc_po_lines;
  po public.proc_purchase_orders;
begin
  select * into inv from public.proc_supplier_invoices where id=new.invoice_id;
  if inv.id is null then raise exception 'Invoice not found'; end if;

  if new.po_line_id is not null then
    select * into pl from public.proc_po_lines where id=new.po_line_id;
    if pl.id is null then raise exception 'Purchase order line not found'; end if;
    if inv.po_id is null or pl.po_id<>inv.po_id then raise exception 'Invoice line does not belong to the invoice purchase order'; end if;
    if pl.item_id<>new.item_id then raise exception 'Invoice item does not match purchase order line'; end if;

    select * into po from public.proc_purchase_orders where id=pl.po_id;
    if po.supplier_id<>inv.supplier_id then raise exception 'Invoice supplier does not match purchase order supplier'; end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_permission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare perm text;
begin
  if auth.role()='service_role' then return case when tg_op='DELETE' then old else new end; end if;
  perm:=case tg_op when 'INSERT' then tg_argv[0] when 'UPDATE' then tg_argv[1] else tg_argv[2] end;
  if perm is not null and perm<>'' then perform private.proc_assert_permission(perm); end if;
  return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION private.proc_po_approval_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_role text;
begin
  if new.status='approved' and old.status is distinct from 'approved' then
    select role into caller_role from public.proc_profiles where id=auth.uid() and active=true;
    if caller_role is null or caller_role <> 'admin' then raise exception 'Only an admin can approve a purchase order'; end if;
    new.approved_by := auth.uid();
    new.approved_at := now();
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_po_permission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='INSERT' then perform private.proc_assert_permission('procurement.orders.create'); return new; end if;
  if tg_op='DELETE' then perform private.proc_assert_permission('procurement.orders.delete'); return old; end if;
  if new.status is distinct from old.status and new.status='approved' then
    perform private.proc_assert_permission('procurement.orders.approve');
  else
    perform private.proc_assert_permission('procurement.orders.edit');
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_po_status_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller_role text;
  calc_subtotal numeric(16,2);
  calc_tax numeric(16,2);
  calc_total numeric(16,2);
  any_received boolean;
  all_received boolean;
begin
  if tg_op='INSERT' then return new; end if;

  select role into caller_role
  from public.proc_profiles
  where id=auth.uid() and active=true;

  if new.po_no is distinct from old.po_no then raise exception 'PO number is immutable'; end if;
  if new.supplier_id is distinct from old.supplier_id then raise exception 'PO supplier cannot be changed'; end if;
  if new.created_by is distinct from old.created_by then raise exception 'PO creator is immutable'; end if;
  if new.created_at is distinct from old.created_at then raise exception 'PO creation time is immutable'; end if;

  if old.status<>'pending_approval' then
    if new.terms is distinct from old.terms then raise exception 'Commercial terms cannot change after PO approval'; end if;
    if new.po_date is distinct from old.po_date then raise exception 'PO date cannot change after approval'; end if;
    if new.freight_total is distinct from old.freight_total then raise exception 'Freight cannot change after PO approval'; end if;
  end if;

  if new.status is distinct from old.status then
    if new.status='approved' then
      if caller_role<>'admin' then raise exception 'Only an admin can approve a purchase order'; end if;
      if old.status<>'pending_approval' then raise exception 'Only a pending purchase order can be approved'; end if;
      if not exists(select 1 from public.proc_po_lines where po_id=old.id) then raise exception 'Cannot approve an empty purchase order'; end if;
      new.approved_by:=auth.uid();
      new.approved_at:=now();
    elsif new.status='sent' then
      if old.status<>'approved' then raise exception 'Purchase order must be approved before it is sent'; end if;
      if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized to send purchase orders'; end if;
      new.sent_at:=coalesce(new.sent_at,now());
    elsif new.status='cancelled' then
      if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized to cancel purchase orders'; end if;
      if old.status in ('received','closed') then raise exception 'Received or closed purchase orders cannot be cancelled'; end if;
    elsif new.status='closed' then
      if old.status<>'received' then
        if old.status not in ('sent','partially_received')
          or not exists(select 1 from public.proc_po_lines where po_id=old.id and cancelled_qty>0)
          or exists(select 1 from public.proc_po_lines l where l.po_id=old.id
            and l.qty-l.cancelled_qty>(select coalesce(sum(gl.accepted_qty),0) from public.proc_grn_lines gl join public.proc_grns g on g.id=gl.grn_id and g.status='posted' where gl.po_line_id=l.id))
        then raise exception 'Only a received or fully accounted purchase order can be closed'; end if;
      end if;
    elsif new.status in ('partially_received','received') then
      if old.status not in ('sent','partially_received') then raise exception 'Goods can only be received against a sent purchase order'; end if;

      select
        exists(
          select 1
          from public.proc_po_lines pl
          join (
            select gl.po_line_id,sum(gl.accepted_qty) accepted_qty
            from public.proc_grn_lines gl
            join public.proc_grns g on g.id=gl.grn_id and g.status='posted'
            group by gl.po_line_id
          ) rec on rec.po_line_id=pl.id
          where pl.po_id=old.id and rec.accepted_qty>0
        ),
        not exists(
          select 1
          from public.proc_po_lines pl
          left join (
            select gl.po_line_id,sum(gl.accepted_qty) accepted_qty
            from public.proc_grn_lines gl
            join public.proc_grns g on g.id=gl.grn_id and g.status='posted'
            group by gl.po_line_id
          ) rec on rec.po_line_id=pl.id
          where pl.po_id=old.id and coalesce(rec.accepted_qty,0)<pl.qty-pl.cancelled_qty
        )
      into any_received,all_received;

      if new.status='received' and not all_received then
        raise exception 'PO cannot be marked received until posted GRNs cover all ordered quantities';
      end if;
      if new.status='partially_received' and (not any_received or all_received) then
        raise exception 'PO partial-receipt status does not match posted GRNs';
      end if;
    else
      raise exception 'Invalid purchase order status transition: % to %',old.status,new.status;
    end if;
  end if;

  select
    coalesce(sum(round(pl.qty*pl.unit_price*(1-pl.discount_percent/100.0),2)),0),
    coalesce(sum(round((pl.qty*pl.unit_price*(1-pl.discount_percent/100.0))*(pl.tax_percent/100.0),2)),0),
    coalesce(sum(pl.line_total),0)
  into calc_subtotal,calc_tax,calc_total
  from public.proc_po_lines pl
  where pl.po_id=old.id;

  new.subtotal:=calc_subtotal;
  new.tax_total:=calc_tax;
  new.total:=calc_total+coalesce(new.freight_total,0);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_post_grn_impl(p_grn_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  g public.proc_grns;
  po public.proc_purchase_orders;
  l record;
  bal numeric(14,3);
  posted_count integer := 0;
  caller uuid := auth.uid();
  caller_role text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','receiver') then raise exception 'Not authorized'; end if;

  select * into g from public.proc_grns where id=p_grn_id for update;
  if g.id is null then raise exception 'GRN not found'; end if;
  if g.status <> 'draft' then raise exception 'Only draft GRNs can be posted'; end if;

  select * into po from public.proc_purchase_orders where id=g.po_id for update;
  if po.id is null then raise exception 'Purchase order not found'; end if;
  if po.supplier_id<>g.supplier_id then raise exception 'GRN supplier does not match purchase order supplier'; end if;
  if po.status not in ('sent','partially_received') then raise exception 'Only sent purchase orders can be received'; end if;

  for l in
    select gl.*, pl.requirement_id,pl.po_id as line_po_id,pl.item_id as line_item_id
    from public.proc_grn_lines gl
    join public.proc_po_lines pl on pl.id=gl.po_line_id
    where gl.grn_id=p_grn_id
  loop
    if l.line_po_id<>g.po_id then raise exception 'GRN line belongs to a different purchase order'; end if;
    if l.line_item_id<>l.item_id then raise exception 'GRN item does not match purchase order line'; end if;
    if l.accepted_qty+l.rejected_qty>l.received_qty then raise exception 'Accepted plus rejected quantity cannot exceed received quantity'; end if;

    insert into public.proc_stock_balances(item_id,location_id,qty,last_counted_at)
    values(l.item_id,g.location_id,l.accepted_qty,now())
    on conflict(item_id,location_id)
    do update set qty=public.proc_stock_balances.qty+excluded.qty,updated_at=now()
    returning qty into bal;

    insert into public.proc_stock_ledger(item_id,location_id,txn_type,qty_delta,balance_after,source_type,source_id,note,created_by)
    values(l.item_id,g.location_id,'GRN',l.accepted_qty,bal,'GRN',g.id,
      case when l.rejected_qty>0 then 'Rejected: '||l.rejected_qty::text else null end,caller);

    update public.proc_requirements
    set received_qty=received_qty+l.accepted_qty,
        status=case
          when received_qty+l.accepted_qty >= adjusted_qty and adjusted_qty>0 then 'received'
          when received_qty+l.accepted_qty > 0 then 'partially_received'
          when ordered_qty >= adjusted_qty and adjusted_qty>0 then 'ordered'
          when ordered_qty > 0 then 'partially_ordered'
          else status
        end,
        updated_at=now()
    where id=l.requirement_id;
    posted_count := posted_count + 1;
  end loop;

  update public.proc_grns set status='posted',posted_at=now() where id=p_grn_id;

  update public.proc_purchase_orders p
  set status = case
    when not exists (
      select 1 from public.proc_po_lines pl
      left join (
        select gl.po_line_id,sum(gl.accepted_qty) rec
        from public.proc_grn_lines gl
        join public.proc_grns gg on gg.id=gl.grn_id and gg.status='posted'
        group by gl.po_line_id
      ) x on x.po_line_id=pl.id
      where pl.po_id=p.id and coalesce(x.rec,0) < pl.qty-pl.cancelled_qty
    ) then 'received'
    else 'partially_received'
  end,
  updated_at=now()
  where p.id=g.po_id;

  return posted_count;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_price_line_confidentiality_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  t text;
begin
  select list_type into t
  from public.proc_company_price_lists
  where id=new.price_list_id;

  if t is null then raise exception 'Price list not found'; end if;

  if t='mrp' and (
    new.cost is not null
    or coalesce(new.discount_percent,0)<>0
    or coalesce(new.extra_discount_percent,0)<>0
    or coalesce(new.tax_percent,0)<>0
  ) then
    raise exception 'Cost, discount and tax data must be stored in an Admin-only costing list, not an MRP list';
  end if;

  return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_record_delete_plan(p_table text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allowed text[]:=private.proc_record_delete_tables(); roots text[]:=array['proc_rfqs','proc_purchase_orders','proc_requirements','proc_quotes','proc_supplier_invoices','proc_grns','proc_stock_counts','proc_item_requests','proc_company_price_lists','proc_company_list_items','proc_companies','proc_suppliers']; plan jsonb; prior jsonb; target jsonb; fk record; parent record; ids jsonb; tab text; snapshots jsonb:='{}'; counts jsonb:='{}'; label_v text;
begin
 perform private.proc_assert_data_admin();
 if p_table is null or not p_table=any(roots) then raise exception 'Unsupported record type';end if;
 execute format('select to_jsonb(t) from public.%I t where id=$1',p_table) into target using p_id;
 if target is null then raise exception 'Record no longer exists. Refresh the list.';end if;
 label_v:=coalesce(target->>'supplier_code',target->>'name',target->>'title',target->>'rfq_no',target->>'po_no',target->>'requirement_no',target->>'invoice_no',target->>'grn_no',target->>'count_no',nullif(target->>'quote_ref',''),target->>'id');
 plan:=jsonb_build_object(p_table,jsonb_build_array(p_id));
 loop
  prior:=plan;
  -- Remove complete orders, never just a line/receipt from an otherwise live PO.
  for parent in select * from (values('proc_po_lines'),('proc_grns')) v(tab) loop
   if plan ? parent.tab then
    execute format('select coalesce(jsonb_agg(distinct po_id),''[]''::jsonb) from public.%I where id in(select value::uuid from jsonb_array_elements_text($1)) and po_id is not null',parent.tab) into ids using plan->parent.tab;
    select coalesce(jsonb_agg(distinct value order by value),'[]'::jsonb) into ids from jsonb_array_elements(coalesce(plan->'proc_purchase_orders','[]'::jsonb)||ids);
    if jsonb_array_length(ids)>0 then plan:=jsonb_set(plan,'{proc_purchase_orders}',ids);end if;
   end if;
  end loop;
  for fk in select c.relname child,t.relname parent,a.attname col from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace join pg_class t on t.oid=f.confrelid join pg_attribute a on a.attrelid=c.oid and a.attnum=f.conkey[1] where f.contype='f' and ns.nspname='public' and c.relname=any(allowed) and t.relname=any(allowed) and cardinality(f.conkey)=1 and cardinality(f.confkey)=1 and not(c.relname='proc_companies' and t.relname='proc_suppliers') loop
   if plan ? fk.parent then
    execute format('select coalesce(jsonb_agg(id),''[]''::jsonb) from public.%I where %I in(select value::uuid from jsonb_array_elements_text($1))',fk.child,fk.col) into ids using plan->fk.parent;
    select coalesce(jsonb_agg(distinct value order by value),'[]'::jsonb) into ids from jsonb_array_elements(coalesce(plan->fk.child,'[]'::jsonb)||ids);
    if jsonb_array_length(ids)>0 then plan:=jsonb_set(plan,array[fk.child],ids);end if;
   end if;
  end loop;
  -- Release awards used only by the orders selected for deletion.
  if plan ? 'proc_purchase_orders' then
   select coalesce(jsonb_agg(a.id),'[]'::jsonb) into ids from public.proc_awards a where a.quote_line_id in(select source_quote_line_id from public.proc_po_lines where po_id in(select value::uuid from jsonb_array_elements_text(plan->'proc_purchase_orders'))) and not exists(select 1 from public.proc_po_lines l where l.source_quote_line_id=a.quote_line_id and l.po_id not in(select value::uuid from jsonb_array_elements_text(plan->'proc_purchase_orders')));
   select coalesce(jsonb_agg(distinct value order by value),'[]'::jsonb) into ids from jsonb_array_elements(coalesce(plan->'proc_awards','[]'::jsonb)||ids);
   if jsonb_array_length(ids)>0 then plan:=jsonb_set(plan,'{proc_awards}',ids);end if;
  end if;
  -- Automation jobs use polymorphic entity IDs rather than foreign keys.
  select coalesce(jsonb_agg(id),'[]'::jsonb) into ids from public.proc_automation_jobs where entity_id in(select x.value::uuid from jsonb_each(plan) e cross join lateral jsonb_array_elements_text(e.value) x(value));
  if jsonb_array_length(ids)>0 then plan:=jsonb_set(plan,'{proc_automation_jobs}',ids);end if;
  exit when plan=prior;
 end loop;
 foreach tab in array allowed loop
  if plan ? tab then
   execute format('select coalesce(jsonb_agg(to_jsonb(t) order by id),''[]''::jsonb) from public.%I t where id in(select value::uuid from jsonb_array_elements_text($1))',tab) into ids using plan->tab;
   snapshots:=snapshots||jsonb_build_object(tab,ids);counts:=counts||jsonb_build_object(tab,jsonb_array_length(ids));
  end if;
 end loop;
 if plan ? 'proc_suppliers' then
  select coalesce(jsonb_agg(to_jsonb(c) order by id),'[]'::jsonb) into ids from public.proc_companies c where default_supplier_id in(select value::uuid from jsonb_array_elements_text(plan->'proc_suppliers'));
  snapshots:=snapshots||jsonb_build_object('company_defaults',ids);
  if jsonb_array_length(ids)>0 then counts:=counts||jsonb_build_object('company_defaults_cleared',jsonb_array_length(ids));end if;
 end if;
 if exists(select 1 from public.proc_whatsapp_po_dispatches where id in(select value::uuid from jsonb_array_elements_text(coalesce(plan->'proc_whatsapp_po_dispatches','[]'))) and status in ('sending','unknown')) or exists(select 1 from public.proc_whatsapp_rfq_dispatches where id in(select value::uuid from jsonb_array_elements_text(coalesce(plan->'proc_whatsapp_rfq_dispatches','[]'))) and status in ('sending','unknown')) then raise exception 'Resolve pending or unknown WhatsApp sends before deleting these records';end if;
 return jsonb_build_object('table',p_table,'id',p_id,'label',label_v,'counts',counts,'plan',plan,'token',md5(snapshots::text));
end $function$

CREATE OR REPLACE FUNCTION private.proc_release_po_balance_v1(p_po_line_id uuid, p_action text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pl public.proc_po_lines; po public.proc_purchase_orders; accepted numeric; released numeric; rid uuid;
begin
 if auth.uid() is null or not private.proc_has_permission('procurement.orders.edit') or not private.proc_has_permission('procurement.orders.approve') then
  raise exception 'Permission denied: order editing and approval required' using errcode='42501';
 end if;
 if p_action not in ('cancel','buy_elsewhere') or length(trim(coalesce(p_reason,''))) not between 1 and 1000 then raise exception 'Choose an action and enter a reason'; end if;
 select po_id into rid from public.proc_po_lines where id=p_po_line_id;
 select * into po from public.proc_purchase_orders where id=rid for update;
 if po.id is null or po.status not in ('sent','partially_received') then raise exception 'Only sent, outstanding orders can release a balance'; end if;
 select * into pl from public.proc_po_lines where id=p_po_line_id for update;
 if exists(select 1 from public.proc_rejection_cases c join public.proc_grn_lines gl on gl.id=c.grn_line_id where gl.po_line_id=pl.id and c.status<>'resolved') then raise exception 'Resolve rejected goods before releasing this balance'; end if;
 select coalesce(sum(gl.accepted_qty),0) into accepted from public.proc_grn_lines gl join public.proc_grns g on g.id=gl.grn_id and g.status='posted' where gl.po_line_id=pl.id;
 released:=pl.qty-pl.cancelled_qty-accepted;
 if released<=0 then raise exception 'This line has no outstanding delivery balance'; end if;
 update public.proc_po_lines set cancelled_qty=cancelled_qty+released where id=pl.id;
 insert into public.proc_po_balance_actions(po_line_id,released_qty,action,reason,created_by) values(pl.id,released,p_action,trim(p_reason),auth.uid());
 update public.proc_requirements set ordered_qty=greatest(ordered_qty-released,received_qty),
  adjusted_qty=case when p_action='cancel' then greatest(adjusted_qty-released,ordered_qty-released,received_qty) else adjusted_qty end,
  updated_at=now() where id=pl.requirement_id;
 perform public.proc_refresh_requirement_status(pl.requirement_id);
 if not exists(select 1 from public.proc_po_lines l where l.po_id=po.id and l.qty-l.cancelled_qty>(select coalesce(sum(gl.accepted_qty),0) from public.proc_grn_lines gl join public.proc_grns g on g.id=gl.grn_id and g.status='posted' where gl.po_line_id=l.id)) then
  update public.proc_purchase_orders set status='closed',updated_at=now() where id=po.id;
 end if;
 return jsonb_build_object('released_qty',released,'action',p_action);
end $function$

CREATE OR REPLACE FUNCTION private.proc_require_finite_numbers()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare field text; row_data jsonb:=to_jsonb(new);
begin
 foreach field in array tg_argv loop
  if row_data->>field in ('NaN','Infinity','-Infinity') then
   raise exception 'Finite numeric value required for %',field using errcode='22003';
  end if;
 end loop;
 return new;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_requirement_auto_priority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_movement text;
  v_current numeric;
begin
  if new.source_count_line_id is not null then
    select i.movement,scl.current_stock
    into v_movement,v_current
    from public.proc_stock_count_lines scl
    join public.proc_items i on i.id=scl.item_id
    where scl.id=new.source_count_line_id;

    if v_current=0 then
      new.priority:='urgent';
      new.urgency_reason:=coalesce(new.urgency_reason,'zero_stock');
      new.source_type:='stock_count';
    elsif v_movement='FAST' and new.priority in ('low','normal') then
      new.priority:='high';
      new.urgency_reason:=coalesce(new.urgency_reason,'fast_mover');
      new.source_type:='stock_count';
    elsif new.source_type='normal' then
      new.source_type:='stock_count';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_requirement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.required_qty < 0 or new.adjusted_qty < 0 or new.ordered_qty < 0 or new.received_qty < 0 then
    raise exception 'Requirement quantities cannot be negative';
  end if;
  if new.adjusted_qty < greatest(new.ordered_qty,new.received_qty) then
    raise exception 'Adjusted quantity cannot be below already ordered or received quantity';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_requirement_permission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare src text:=coalesce(case when tg_op='DELETE' then old.source_type else new.source_type end,'normal');
begin
  if src='stock_count' and private.proc_has_permission('stock.count.enter') then
    return case when tg_op='DELETE' then old else new end;
  end if;
  if src='urgent_action' and private.proc_has_permission('urgent.manage') then
    return case when tg_op='DELETE' then old else new end;
  end if;
  perform private.proc_assert_permission('procurement.requirements.manage');
  return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION private.proc_requirement_review_reset()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='INSERT' then
    if new.ordered_qty=0 and new.received_qty=0 then
      new.approval_status:='pending_review';
      new.selected_for_order:=false;
      new.approved_by:=null;
      new.approved_at:=null;
    end if;
  elsif new.source_count_line_id is distinct from old.source_count_line_id
        and new.ordered_qty=0 and new.received_qty=0 then
    new.approval_status:='pending_review';
    new.selected_for_order:=false;
    new.approved_by:=null;
    new.approved_at:=null;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_rfq_item_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.proc_requirements;
  review_enabled boolean;
begin
  select enabled into review_enabled
  from public.proc_feature_settings
  where feature_key='requirements.admin_review';

  if coalesce(review_enabled,false) then
    select * into r from public.proc_requirements where id=new.requirement_id;
    if r.id is null then raise exception 'Requirement not found'; end if;
    if r.approval_status<>'approved' or r.selected_for_order<>true then
      raise exception 'Requirement must be approved and selected before requesting supplier prices';
    end if;
  end if;

  if exists(
    select 1
    from public.proc_rfq_items ri
    join public.proc_rfqs q on q.id=ri.rfq_id
    where ri.requirement_id=new.requirement_id
      and ri.rfq_id<>new.rfq_id
      and q.status in ('draft','sent','partially_quoted','quoted')
  ) then
    raise exception 'Requirement is already in an active supplier price request';
  end if;

  return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_save_quote_with_sizes_impl(p_rfq_id uuid, p_supplier_id uuid, p_quote_ref text, p_lines jsonb, p_additional_sizes jsonb, p_valid_until date DEFAULT NULL::date, p_attachment_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_freight_total numeric DEFAULT 0, p_minimum_order_value numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$
declare
 caller uuid:=auth.uid(); caller_role text; rfq_status text; x jsonb;
 parent public.proc_items; req public.proc_requirements; ri public.proc_rfq_items;
 item_uuid uuid; req_uuid uuid; ri_uuid uuid; new_uuid uuid;
 size_v text; qty_v numeric; price_v numeric; key_v text; found_count integer;
 lines_v jsonb:=p_lines; added integer:=0;
begin
 if caller is null then raise exception 'Not authenticated'; end if;
 select role into caller_role from public.proc_profiles where id=caller and active;
 if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;
 perform private.proc_assert_permission('procurement.rfq.manage');
 perform private.proc_assert_permission('procurement.requirements.manage');
 select status into rfq_status from public.proc_rfqs where id=p_rfq_id for update;
 if rfq_status is null or rfq_status not in ('draft','prepared','sent','partially_quoted','quoted') then raise exception 'Cannot add sizes to a missing, awarded or closed RFQ'; end if;
 if not exists(select 1 from public.proc_rfq_suppliers where rfq_id=p_rfq_id and supplier_id=p_supplier_id and status<>'declined') then raise exception 'Supplier is not invited to this RFQ'; end if;
 if p_additional_sizes is null or jsonb_typeof(p_additional_sizes)<>'array' or jsonb_array_length(p_additional_sizes) not between 1 and 120 then raise exception 'Provide 1 to 120 additional size lines'; end if;
 if p_lines is null or jsonb_typeof(p_lines)<>'array' then raise exception 'Quote lines must be an array'; end if;
 for x in select * from jsonb_array_elements(p_additional_sizes) loop
  size_v:=trim(coalesce(x->>'size','')); qty_v:=(x->>'qty')::numeric; price_v:=(x->>'unit_price')::numeric;
  if size_v='' or length(size_v)>100 or length(coalesce(x->>'remarks',''))>300 then raise exception 'Each size needs a valid size and remarks of at most 300 characters'; end if;
  if qty_v is null or qty_v::text in ('NaN','Infinity','-Infinity') or qty_v<=0 or price_v is null or price_v::text in ('NaN','Infinity','-Infinity') or price_v<0 then raise exception 'Size quantity must be positive and price must be zero or positive'; end if;
  select * into ri from public.proc_rfq_items where id=(x->>'source_rfq_item_id')::uuid and rfq_id=p_rfq_id;
  if ri.id is null then raise exception 'Additional size source does not belong to this RFQ'; end if;
  select * into req from public.proc_requirements where id=ri.requirement_id;
  select * into parent from public.proc_items where id=req.item_id and active;
  if parent.id is null then raise exception 'Source item is not active'; end if;
  if lower(trim(coalesce(parent.size,'')))=lower(size_v) then raise exception 'This is the existing size. Edit its quantity in order review instead'; end if;
  -- Serialize catalogue lookups across RFQs. Reuse exact existing identities.
  key_v:=parent.category||'|'||lower(trim(parent.description))||'|'||lower(size_v)||'|'||parent.uom||'|'||lower(trim(coalesce(parent.brand,'')));
  perform pg_advisory_xact_lock(hashtextextended(key_v,0));
  select count(*) into found_count from public.proc_items i where i.active and i.category=parent.category and lower(trim(i.description))=lower(trim(parent.description)) and lower(trim(coalesce(i.size,'')))=lower(size_v) and i.uom=parent.uom and lower(trim(coalesce(i.brand,'')))=lower(trim(coalesce(parent.brand,'')));
  if found_count>1 then raise exception 'More than one existing item matches this size. Resolve duplicate catalogue items first'; end if;
  item_uuid:=null;
  select i.id into item_uuid from public.proc_items i where i.active and i.category=parent.category and lower(trim(i.description))=lower(trim(parent.description)) and lower(trim(coalesce(i.size,'')))=lower(size_v) and i.uom=parent.uom and lower(trim(coalesce(i.brand,'')))=lower(trim(coalesce(parent.brand,'')));
  if item_uuid is null then
   perform private.proc_assert_permission('items.edit');
   new_uuid:=gen_random_uuid();
   insert into public.proc_items(id,item_code,category,description,main_group,subgroup,size,uom,movement,brand,source)
   values(new_uuid,'SIZE-'||replace(new_uuid::text,'-',''),parent.category,parent.description,parent.main_group,parent.subgroup,size_v,parent.uom,parent.movement,parent.brand,'Additional RFQ size');
   item_uuid:=new_uuid;
  end if;
  ri_uuid:=null;
  select i.id into ri_uuid from public.proc_rfq_items i join public.proc_requirements r on r.id=i.requirement_id where i.rfq_id=p_rfq_id and r.item_id=item_uuid;
  if ri_uuid is null then
   req_uuid:=gen_random_uuid();
   insert into public.proc_requirements(id,requirement_no,item_id,location_id,required_qty,adjusted_qty,status,source_type,request_reason,notes,created_by)
   values(req_uuid,'REQ-SIZE-'||replace(req_uuid::text,'-',''),item_uuid,req.location_id,qty_v,qty_v,'quoting','manual','manual_extra',nullif(x->>'remarks',''),caller);
   -- Use the existing permission-checked review operation, preserving audit logs.
   perform public.proc_review_requirements(array[req_uuid],'approve',true,'Additional size selected during supplier price entry');
   insert into public.proc_rfq_items(rfq_id,requirement_id,requested_qty) values(p_rfq_id,req_uuid,qty_v) returning id into ri_uuid;
  elsif not exists(select 1 from public.proc_rfq_items i join public.proc_requirements r on r.id=i.requirement_id where i.id=ri_uuid and i.requested_qty=qty_v and r.ordered_qty=0 and r.received_qty=0) then
   raise exception 'This size already has a different required quantity. Edit the existing line instead of adding it again';
  end if;
  if exists(select 1 from jsonb_array_elements(lines_v) a where (a->>'rfq_item_id')::uuid=ri_uuid) then raise exception 'This size already has a price line. Edit the existing line instead of adding it again'; end if;
  lines_v:=lines_v||jsonb_build_array(jsonb_build_object('rfq_item_id',ri_uuid,'unit_price',price_v,'notes',nullif(x->>'remarks',''),'order_multiple',case when mod(qty_v,1)=0 then 1 else 0.001 end));
  added:=added+1;
 end loop;
 -- The existing save operation remains responsible for quotes, status and guards.
 -- Any failure rolls back all added items/requirements and the quote together.
 return public.proc_save_quote_v3(p_rfq_id,p_supplier_id,p_quote_ref,lines_v,p_valid_until,p_attachment_path,p_notes,p_freight_total,p_minimum_order_value)||jsonb_build_object('additional_size_count',added);
end $function$

CREATE OR REPLACE FUNCTION private.proc_simple_document_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n bigint; j jsonb;
begin
 insert into private.proc_document_counters(kind,value) values(tg_table_name,1)
 on conflict(kind) do update set value=private.proc_document_counters.value+1 returning value into n;
 j:=jsonb_build_object(tg_argv[0],lpad(n::text,greatest(3,length(n::text)),'0'));
 new:=jsonb_populate_record(new,j);return new;
end $function$

CREATE OR REPLACE FUNCTION private.proc_submit_stock_count_impl(p_count_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  c public.proc_stock_counts;
  l record;
  prev_qty numeric(14,3);
  created_count integer:=0;
  req_no text;
  caller uuid:=auth.uid();
  caller_role text;
  existing_req public.proc_requirements;
  new_target numeric(14,3);
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler','stock_checker') then raise exception 'Not authorized'; end if;

  select * into c from public.proc_stock_counts where id=p_count_id for update;
  if c.id is null then raise exception 'Stock count not found'; end if;
  if c.status<>'draft' then raise exception 'Only draft counts can be submitted'; end if;
  if c.counted_by<>caller and caller_role not in ('admin','procurement','stock_handler') then raise exception 'Not authorized'; end if;

  for l in
    select scl.*,i.item_code
    from public.proc_stock_count_lines scl
    join public.proc_items i on i.id=scl.item_id
    where scl.count_id=p_count_id
  loop
    if exists(
      select 1 from public.proc_stock_ledger sl
      where sl.item_id=l.item_id
        and sl.location_id=c.location_id
        and sl.created_at>c.count_started_at
        and sl.source_id is distinct from c.id
    ) then
      raise exception 'Stock changed after counting began for item %. Recount this item before submitting.',l.item_code;
    end if;

    if not l.sufficient_stock then
    select qty into prev_qty
    from public.proc_stock_balances
    where item_id=l.item_id and location_id=c.location_id;

    insert into public.proc_stock_balances(item_id,location_id,qty,last_counted_at)
    values(l.item_id,c.location_id,l.current_stock,now())
    on conflict(item_id,location_id)
    do update set qty=excluded.qty,last_counted_at=excluded.last_counted_at,updated_at=now();

    insert into public.proc_stock_ledger(
      item_id,location_id,txn_type,qty_delta,balance_after,source_type,source_id,note,created_by
    )
    values(
      l.item_id,c.location_id,'COUNT',
      l.current_stock-coalesce(prev_qty,0),l.current_stock,
      'STOCK_COUNT',c.id,'Physical stock count',caller
    );

    end if; -- Visual checks do not write quantities, balances or ledger transactions.
    existing_req:=null;
    select * into existing_req
    from public.proc_requirements
    where item_id=l.item_id
      and location_id=c.location_id
      and status not in ('closed','cancelled','received')
      and (source_type='stock_count' or source_count_line_id is not null)
    order by created_at desc
    limit 1
    for update;

    if existing_req.id is not null then
      new_target:=greatest(existing_req.ordered_qty,existing_req.received_qty+l.required_qty);
      update public.proc_requirements
      set source_count_line_id=l.id,
          source_type='stock_count',
          required_qty=existing_req.received_qty+l.required_qty,
          adjusted_qty=new_target,
          status=case
            when exists(
              select 1
              from public.proc_rfq_items ri
              join public.proc_rfqs q on q.id=ri.rfq_id
              where ri.requirement_id=existing_req.id
                and q.status in ('draft','prepared','sent','partially_quoted','quoted')
            ) then 'quoting'
            when new_target=0 then 'closed'
            when existing_req.received_qty>=new_target then 'received'
            when existing_req.received_qty>0 then 'partially_received'
            when existing_req.ordered_qty>=new_target then 'ordered'
            when existing_req.ordered_qty>0 then 'partially_ordered'
            when l.required_qty>0 then 'open'
            else 'closed'
          end,
          updated_at=now()
      where id=existing_req.id;

      -- A recount may change the current need while an RFQ is already active.
      -- Keep the RFQ history intact, but automatically exclude lines whose
      -- current remaining requirement is now zero. Award Review also caps any
      -- selected line to the latest requirement quantity.
      update public.proc_rfq_items ri
      set selected_for_po=(new_target>existing_req.ordered_qty)
      from public.proc_rfqs q
      where ri.requirement_id=existing_req.id
        and q.id=ri.rfq_id
        and q.status in ('draft','prepared','sent','partially_quoted','quoted');
    elsif l.required_qty>0 then
      req_no:='REQ-'||to_char(clock_timestamp(),'YYMMDDHH24MISSMS')||'-'||right(l.item_code,6);
      insert into public.proc_requirements(
        requirement_no,source_count_line_id,item_id,location_id,
        required_qty,adjusted_qty,status,created_by,source_type
      )
      values(req_no,l.id,l.item_id,c.location_id,l.required_qty,l.required_qty,'open',caller,'stock_count');
      created_count:=created_count+1;
    end if;
  end loop;

  update public.proc_stock_counts
  set status='submitted',submitted_at=now(),updated_at=now()
  where id=p_count_id;

  return created_count;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_supplier_delete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare fk record; used boolean;
begin
 perform private.proc_assert_data_admin();
 for fk in select n.nspname schema_name,c.relname table_name,a.attname column_name from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum=f.conkey[1] where f.contype='f' and f.confrelid='public.proc_suppliers'::regclass loop
  execute format('select exists(select 1 from %I.%I where %I=$1)',fk.schema_name,fk.table_name,fk.column_name) into used using old.id;
  if used then raise exception 'Supplier is used in records, company lists or coverage rules. Deactivate it to retain history.'; end if;
 end loop;
 return old;
end $function$

CREATE OR REPLACE FUNCTION private.proc_sync_reorder_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare f numeric;
begin
  f := case new.movement when 'FAST' then 0.50 when 'SLOW' then 0.25 else 1.0/3.0 end;
  new.reorder_level := ceil(new.max_stock * f);
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.proc_whatsapp_claim_po_dispatch(p_po_id uuid, p_session text, p_image_sha256 text, p_caption text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;v_supplier uuid;
begin
 if auth.uid() is null or not private.proc_is_role(array['admin','procurement']) or not private.proc_has_permission('procurement.orders.edit') then raise exception 'Unauthorized WhatsApp PO dispatch';end if;
 if p_image_sha256 is null or p_image_sha256 !~ '^[a-f0-9]{64}$' or p_session is null or p_session !~ '^[A-Za-z0-9_-]{1,50}$' or p_caption is null or length(trim(p_caption))=0 or length(p_caption)>2000 then raise exception 'Invalid dispatch fields';end if;
 select p.supplier_id into v_supplier from public.proc_purchase_orders p join public.proc_suppliers s on s.id=p.supplier_id where p.id=p_po_id and p.status='approved' and s.active for share of p,s;
 if v_supplier is null then raise exception 'Only approved orders with active suppliers can be dispatched';end if;
 insert into public.proc_whatsapp_po_dispatches(po_id,supplier_id,sent_by,gateway_session,status,image_sha256,caption)values(p_po_id,v_supplier,auth.uid(),p_session,'sending',p_image_sha256,p_caption)returning id into v_id;
 return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.proc_access_status_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.proc_access_rules;reason text;until_at timestamptz;exempt boolean;
begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='42501';end if;
 reason:=private.proc_access_reason();exempt:=private.proc_access_super_admin();r:=private.proc_access_rule();
 if not exempt then
  if r.time_enabled then until_at:=((now() at time zone 'Asia/Colombo')::date+r.end_time) at time zone 'Asia/Colombo';end if;
  if r.location_enabled then
   select least(until_at,l.expires_at) into until_at from private.proc_access_leases l
   where l.user_id=auth.uid() and l.session_id=nullif(auth.jwt()->>'session_id','')::uuid and l.revision=r.revision;
  end if;
 end if;
 return jsonb_build_object('allowed',reason='allowed','reason',reason,'exempt',exempt,
  'policy',to_jsonb(r)-'revision'-'scope_id','server_now',now(),'valid_until',until_at);
end $function$

