CREATE OR REPLACE FUNCTION public.proc_add_rfq_supplier_v1(p_rfq_id uuid, p_supplier_id uuid, p_scope_override_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
 rfq public.proc_rfqs;
 invitation public.proc_rfq_suppliers;
 reason text:=nullif(btrim(p_scope_override_reason),'');
begin
 if auth.uid() is null then raise exception 'Not authenticated' using errcode='42501'; end if;
 if not private.proc_has_permission('procurement.rfq.manage') then
  raise exception 'Permission denied: procurement.rfq.manage' using errcode='42501';
 end if;
 if length(reason)>500 then raise exception 'Coverage override reason must be 500 characters or less'; end if;

 -- Serialize with awards and other additions to this RFQ.
 select * into rfq from public.proc_rfqs where id=p_rfq_id for update;
 if rfq.id is null then raise exception 'RFQ not found'; end if;
 if rfq.status not in ('draft','prepared','sent','partially_quoted','quoted') then
  raise exception 'Cannot add suppliers to an awarded, closed or cancelled RFQ';
 end if;
 perform 1 from public.proc_suppliers where id=p_supplier_id and active=true for share;
 if not found then raise exception 'Invalid or inactive supplier'; end if;

 select * into invitation from public.proc_rfq_suppliers
 where rfq_id=p_rfq_id and supplier_id=p_supplier_id;
 if invitation.id is not null then
  return jsonb_build_object('invitation',to_jsonb(invitation),'rfq_status',rfq.status,'added',false);
 end if;
 if not exists(select 1 from public.proc_rfq_items where rfq_id=p_rfq_id) then
  raise exception 'RFQ has no items';
 end if;
 if exists(select 1 from public.proc_supplier_scopes where supplier_id=p_supplier_id)
 and not exists(
  select 1 from public.proc_rfq_items ri
  join public.proc_requirements rr on rr.id=ri.requirement_id
  join public.proc_items i on i.id=rr.item_id
  join public.proc_supplier_scopes sc on sc.supplier_id=p_supplier_id
  where ri.rfq_id=p_rfq_id and (
   (sc.scope_type='item' and sc.item_id=i.id)
   or (sc.scope_type='category' and sc.scope_value=i.category)
   or (sc.scope_type='main_group' and sc.scope_value=i.main_group)
   or (sc.scope_type='subgroup' and sc.scope_value=i.subgroup)
  )
 ) and reason is null then
  raise exception 'Supplier does not cover any RFQ item. Enter a coverage override reason or choose another supplier.';
 end if;

 insert into public.proc_rfq_suppliers(rfq_id,supplier_id,status,scope_override_reason)
 values(p_rfq_id,p_supplier_id,'pending',reason) returning * into invitation;
 update public.proc_rfqs set status=case when status='quoted' then 'partially_quoted' else status end,
 updated_at=now() where id=p_rfq_id returning * into rfq;
 return jsonb_build_object('invitation',to_jsonb(invitation),'rfq_status',rfq.status,'added',true);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_add_special_purchase_request_v1(p_item_id uuid, p_purchase_qty numeric, p_reason text, p_customer_requested_qty numeric DEFAULT NULL::numeric, p_customer_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_priority text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  it public.proc_items;
  loc uuid;
  stock_now numeric:=0;
  priority_v text;
  urgency_v text;
  req_no text;
  rid uuid;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler') then
    raise exception 'Admin, Procurement or Stock / Item Handler access required';
  end if;

  select * into it from public.proc_items where id=p_item_id and active=true;
  if it.id is null then raise exception 'Active item not found'; end if;
  if p_purchase_qty is null or p_purchase_qty<=0 then raise exception 'Purchase quantity must be greater than zero'; end if;
  if p_customer_requested_qty is not null and p_customer_requested_qty<=0 then
    raise exception 'Customer / special requested quantity must be greater than zero';
  end if;
  if p_reason not in (
    'customer_request','customer_paid','seasonal_stock','low_price_opportunity',
    'bulk_sale','project_order','promotional_stock','manual_extra'
  ) then raise exception 'Invalid special purchase reason'; end if;

  loc:=private.proc_default_location_id();
  if loc is null then raise exception 'Default stock location is not configured'; end if;
  select coalesce(qty,0) into stock_now
  from public.proc_stock_balances
  where item_id=it.id and location_id=loc;

  priority_v:=coalesce(nullif(p_priority,''),
    case
      when p_reason='customer_paid' then 'urgent'
      when p_reason in ('customer_request','bulk_sale','project_order') then 'high'
      else 'normal'
    end
  );
  if priority_v not in ('low','normal','high','urgent') then raise exception 'Invalid priority'; end if;

  urgency_v:=case
    when p_reason='customer_paid' then 'customer_paid'
    when p_reason='bulk_sale' then 'bulk_sale'
    when p_reason='customer_request' and priority_v='urgent' then 'customer_request'
    else null
  end;

  req_no:='REQ-S-'||to_char(clock_timestamp(),'YYMMDDHH24MISSMS');
  insert into public.proc_requirements(
    requirement_no,item_id,location_id,required_qty,adjusted_qty,ordered_qty,received_qty,
    status,priority,notes,created_by,approval_status,selected_for_order,
    urgency_reason,customer_paid,customer_reference,source_type,
    request_reason,special_requested_qty,request_stock_snapshot,
    request_max_stock_snapshot,request_reorder_snapshot
  )
  values(
    req_no,it.id,loc,p_purchase_qty,p_purchase_qty,0,0,
    'open',priority_v,nullif(trim(coalesce(p_notes,'')),''),caller,'pending_review',false,
    urgency_v,p_reason='customer_paid',nullif(trim(coalesce(p_customer_reference,'')),''),
    'special_request',p_reason,p_customer_requested_qty,stock_now,it.max_stock,it.reorder_level
  )
  returning id into rid;

  return jsonb_build_object(
    'requirement_id',rid,
    'requirement_no',req_no,
    'priority',priority_v,
    'stock_snapshot',stock_now,
    'max_stock',it.max_stock,
    'reorder_level',it.reorder_level,
    'purchase_qty',p_purchase_qty
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_admin_assign_role_v1(p_user_id uuid, p_role_key text)
 RETURNS proc_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare r public.proc_roles; p public.proc_profiles;
begin
  perform private.proc_assert_permission('admin.users.manage');
  select * into r from public.proc_roles where role_key=p_role_key and enabled=true;
  if r.role_key is null then raise exception 'Enabled role not found'; end if;
  if p_user_id=auth.uid() and exists(
    select 1 from public.proc_profiles x where x.id=p_user_id and x.role_key='admin'
  ) and p_role_key<>'admin' then
    raise exception 'You cannot remove your own Super Admin role';
  end if;
  update public.proc_profiles
  set role_key=r.role_key,role=r.base_role,updated_at=now()
  where id=p_user_id
  returning * into p;
  if p.id is null then raise exception 'User profile not found'; end if;
  return p;
end;
end;$function$

