AS $function$begin
 perform private.proc_assert_access();

declare r public.proc_roles;
begin
  perform private.proc_assert_permission('admin.roles.manage');
  select * into r from public.proc_roles where role_key=p_role_key for update;
  if r.role_key is null then return true; end if;
  if r.protected then raise exception 'Protected role cannot be deleted'; end if;
  if exists(select 1 from public.proc_profiles where role_key=p_role_key) then raise exception 'Role is assigned to one or more users'; end if;
  delete from public.proc_roles where role_key=p_role_key;
  return true;
end;
