CREATE OR REPLACE FUNCTION public.proc_admin_reset_data_v1(p_scope text, p_token text, p_confirmation text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
 tab text; tables text[]; preview jsonb;
 revision text:=gen_random_uuid()::text;
begin
 perform private.proc_assert_data_admin();
 if p_confirmation is distinct from 'CLEAR '||upper(p_scope) then
  raise exception 'Type the exact confirmation phrase';
 end if;
 if length(trim(coalesce(p_reason,'')))<5 then
  raise exception 'Enter a reason of at least five characters';
 end if;
 tables:=private.proc_data_reset_tables(p_scope);
 if tables is null then raise exception 'Invalid reset option'; end if;
 perform pg_advisory_xact_lock(704411);
 foreach tab in array tables loop
  execute format('lock table public.%I in share row exclusive mode',tab);
 end loop;
 preview:=public.proc_admin_reset_preview_v1(p_scope);
 if p_token is distinct from preview->>'token' then
  raise exception 'Data changed. Preview the reset again.';
 end if;
 foreach tab in array tables loop
  if tab='proc_stock_balances' and p_scope='stock' then
   insert into public.proc_stock_ledger(
    item_id,location_id,txn_type,qty_delta,balance_after,
    source_type,source_id,note,created_by
   )
   select item_id,location_id,'ADJUSTMENT',-qty,0,'admin_reset',
          revision::uuid,trim(p_reason),auth.uid()
   from public.proc_stock_balances where qty<>0;
   -- Update only rows that need resetting; safely satisfy pg-safeupdate.
   update public.proc_stock_balances
   set qty=0,last_counted_at=null
   where qty is distinct from 0 or last_counted_at is not null;
  else
   -- The preview, exact typed confirmation and admin check explicitly authorize
   -- each table-wide deletion. Keep a predicate for pg-safeupdate.
   execute format('delete from public.%I where ctid is not null',tab);
  end if;
 end loop;
 insert into public.proc_settings(key,value,description)
 values('data_reset_revision',
  jsonb_build_object('id',revision,'scope',p_scope,'at',clock_timestamp()),
  'Invalidates operational browser drafts after admin reset')
 on conflict(key) do update set value=excluded.value,updated_at=now();
 if p_scope in ('stock','full') then
  insert into public.proc_settings(key,value)
  values('stock_reset_revision',to_jsonb(revision))
  on conflict(key) do update set value=excluded.value,updated_at=now();
 end if;
 if p_scope in ('procurement','full') then
  insert into public.proc_settings(key,value)
  values('procurement_reset_revision',to_jsonb(revision))
  on conflict(key) do update set value=excluded.value,updated_at=now();
 end if;
 insert into public.proc_audit_logs(table_name,action,old_data,new_data,user_id)
 values('system_reset','RESET',preview,
        jsonb_build_object('scope',p_scope,'reason',trim(p_reason),
                           'revision',revision),auth.uid());
 return jsonb_build_object('ok',true,'scope',p_scope,'revision',revision);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_admin_reset_preview_v1(p_scope text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare tables text[]; tab text; n bigint; counts jsonb:='{}'; revision jsonb; result jsonb;
begin
 perform private.proc_assert_data_admin();
 tables:=private.proc_data_reset_tables(p_scope);
 if tables is null then raise exception 'Invalid reset option';end if;
 foreach tab in array tables loop
  execute format('select count(*) from public.%I',tab) into n;
  counts:=counts||jsonb_build_object(tab,n);
 end loop;
 select value into revision from public.proc_settings where key='data_reset_revision';
 result:=jsonb_build_object('scope',p_scope,'counts',counts,'revision',revision);
 return result||jsonb_build_object('token',md5(result::text));
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_admin_save_access_policy_v1(p_policy jsonb, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare scope uuid:=coalesce(p_user_id,'00000000-0000-0000-0000-000000000000'::uuid);allowed_days integer[];
begin
 if not private.proc_access_super_admin() then raise exception 'Super Admin required' using errcode='42501';end if;
 if p_user_id is not null and not exists(select 1 from public.proc_profiles where id=p_user_id and deleted_at is null) then raise exception 'User not found';end if;
 select array_agg(value::integer order by value::integer) into allowed_days from jsonb_array_elements_text(p_policy->'days');
 insert into private.proc_access_rules(scope_id,time_enabled,location_enabled,days,start_time,end_time,latitude,longitude,radius_m,location_name)
 values(scope,(p_policy->>'time_enabled')::boolean,(p_policy->>'location_enabled')::boolean,allowed_days,
 (p_policy->>'start_time')::time,(p_policy->>'end_time')::time,(p_policy->>'latitude')::double precision,
 (p_policy->>'longitude')::double precision,(p_policy->>'radius_m')::double precision,left(p_policy->>'location_name',200))
 on conflict(scope_id) do update set time_enabled=excluded.time_enabled,location_enabled=excluded.location_enabled,
 days=excluded.days,start_time=excluded.start_time,end_time=excluded.end_time,latitude=excluded.latitude,
 longitude=excluded.longitude,radius_m=excluded.radius_m,location_name=excluded.location_name,revision=gen_random_uuid();
 if p_user_id is null then delete from private.proc_access_leases;else delete from private.proc_access_leases where user_id=p_user_id;end if;
end $function$

CREATE OR REPLACE FUNCTION public.proc_admin_update_role_v1(p_role_key text, p_name text, p_description text, p_enabled boolean, p_permissions text[])
 RETURNS proc_roles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare r public.proc_roles;
begin
  perform private.proc_assert_permission('admin.roles.manage');
  select * into r from public.proc_roles where role_key=p_role_key for update;
  if r.role_key is null then raise exception 'Role not found'; end if;
  if r.protected and (coalesce(p_enabled,true)=false or not ('admin.roles.manage'=any(coalesce(p_permissions,array[]::text[]))) or not ('admin.users.manage'=any(coalesce(p_permissions,array[]::text[])))) then
    raise exception 'Super Admin critical access cannot be removed';
  end if;
  if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Role name is required'; end if;
  if exists(select 1 from unnest(coalesce(p_permissions,array[]::text[])) x where not exists(select 1 from public.proc_permissions p where p.permission_key=x)) then
    raise exception 'Unknown permission supplied';
  end if;
  update public.proc_roles
  set name=trim(p_name),description=nullif(trim(coalesce(p_description,'')),''),enabled=coalesce(p_enabled,true),updated_at=now()
  where role_key=p_role_key returning * into r;
  delete from public.proc_role_permissions where role_key=p_role_key;
  insert into public.proc_role_permissions(role_key,permission_key,allowed)
  select p_role_key,x,true from unnest(coalesce(p_permissions,array[]::text[])) x;
  return r;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_apply_reviewed_company_hierarchy_v1(p_preview boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r record; v_name text; v_id uuid; v_parent uuid; v_count integer;
 v_new integer:=0;v_moved integer:=0;v_expected integer;v_checked integer;
 v_total integer;v_company_count integer;v_baseline_changed integer;
 v_color text;
BEGIN
 PERFORM private.proc_assert_access();
 IF auth.uid() IS NULL OR NOT EXISTS
   (SELECT 1 FROM public.proc_profiles p WHERE p.id=auth.uid() AND p.active AND p.role='admin')
 THEN RAISE EXCEPTION 'A signed-in Super Admin is required'; END IF;
 PERFORM private.proc_assert_permission('company_lists.manage');
 SELECT count(*),count(DISTINCT company_id) INTO v_total,v_company_count
 FROM private.proc_reviewed_section_plan_v1()
 WHERE section_path IS NOT NULL AND cardinality(section_path)>=2;
 IF p_preview THEN
  RETURN jsonb_build_object('ok',true,'preview',true,
   'planned_items',v_total,'company_lists',v_company_count,
   'company_examples',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb)
      FROM (SELECT company_name,count(*) as items,count(distinct section_path) as group_paths
       FROM private.proc_reviewed_section_plan_v1() WHERE section_path IS NOT NULL
       GROUP BY company_name ORDER BY company_name) x),
   'notice','Only existing active item section IDs will change. No stock values, source keys, identities or history are rewritten.');
 END IF;
 -- Protect against unexpected source data drift. The operation is atomic.
 IF v_total<450 OR v_company_count<12 THEN
  RAISE EXCEPTION 'Reviewed hierarchy preflight failed: % items / % companies',v_total,v_company_count;
 END IF;
 CREATE TEMP TABLE _reviewed_hierarchy_original ON COMMIT DROP AS
 SELECT l.id,(to_jsonb(l)-'section_id'-'updated_at') AS before_record
 FROM public.proc_company_list_items l
 JOIN private.proc_reviewed_section_plan_v1() p ON p.list_id=l.id
 WHERE p.section_path IS NOT NULL AND cardinality(p.section_path)>=2;
 SELECT count(*) INTO v_expected FROM pg_temp._reviewed_hierarchy_original;
 IF v_expected<>v_total THEN RAISE EXCEPTION 'Duplicate or missing target rows'; END IF;

 -- Preserve KOBE LED section ID while correcting its old abbreviated label.
 UPDATE public.proc_company_sections s SET name='LED FLOODLIGHTS',updated_at=now()
 WHERE s.company_id=(SELECT id FROM public.proc_companies WHERE name='KOBE')
  AND s.name='LED FLASH' AND s.active
  AND NOT EXISTS(SELECT 1 FROM public.proc_company_sections z
   WHERE z.company_id=s.company_id AND z.parent_id IS NOT DISTINCT FROM s.parent_id
   AND z.active AND z.name='LED FLOODLIGHTS');
 FOR r IN SELECT * FROM private.proc_reviewed_section_plan_v1()
  WHERE section_path IS NOT NULL AND cardinality(section_path)>=2
  ORDER BY company_name,item_order,list_id
 LOOP
  v_parent:=NULL;
  FOREACH v_name IN ARRAY r.section_path LOOP
   SELECT count(*),min(s.id::text)::uuid INTO v_count,v_id
   FROM public.proc_company_sections s
   WHERE s.company_id=r.company_id AND s.active
    AND s.parent_id IS NOT DISTINCT FROM v_parent
    AND upper(s.name)=upper(v_name);
   IF v_count>1 THEN RAISE EXCEPTION 'Duplicate company section: % / %',r.company_name,v_name; END IF;
   IF v_id IS NULL THEN
    IF v_parent IS NULL THEN RAISE EXCEPTION 'Company root section missing: %',r.company_name; END IF;
    v_color:=CASE WHEN cardinality(r.section_path)>=3 AND v_name=r.section_path[3]
      THEN '#0F766E' ELSE '#2563EB' END;
    INSERT INTO public.proc_company_sections(company_id,parent_id,name,sort_order,color,active)
    VALUES(r.company_id,v_parent,v_name,r.item_order,v_color,true)
    RETURNING id INTO v_id;
    v_new:=v_new+1;
   END IF;
   v_parent:=v_id;
  END LOOP;
  IF r.old_section_id IS DISTINCT FROM v_parent THEN
   UPDATE public.proc_company_list_items SET section_id=v_parent
   WHERE id=r.list_id AND company_id=r.company_id AND active
   AND section_id IS NOT DISTINCT FROM r.old_section_id;
   GET DIAGNOSTICS v_checked=ROW_COUNT;
   IF v_checked<>1 THEN RAISE EXCEPTION 'Item section changed concurrently: %',r.list_id; END IF;
   v_moved:=v_moved+1;
  END IF;
 END LOOP;
 SELECT count(*) INTO v_baseline_changed FROM pg_temp._reviewed_hierarchy_original b
 JOIN public.proc_company_list_items l ON l.id=b.id
 WHERE (to_jsonb(l)-'section_id'-'updated_at') IS DISTINCT FROM b.before_record;
 IF v_baseline_changed<>0 THEN
  RAISE EXCEPTION 'Protected stock or item identity changed in % rows; rolling back',v_baseline_changed;
 END IF;
 RETURN jsonb_build_object('ok',true,'preview',false,'items_examined',v_total,
  'company_lists',v_company_count,'items_moved',v_moved,'sections_created',v_new,
  'preserved_identity_and_stock',true);
END $function$

CREATE OR REPLACE FUNCTION public.proc_approve_company_price_list(p_price_list_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  pl public.proc_company_price_lists;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role<>'admin' then raise exception 'Admin approval required'; end if;

  select * into pl
  from public.proc_company_price_lists
  where id=p_price_list_id
  for update;

  if pl.id is null then raise exception 'Price list not found'; end if;

  if pl.list_type='mrp' and not exists(
    select 1
    from public.proc_company_price_documents d
    where d.price_list_id=pl.id
      and d.document_kind='mrp_staff'
      and d.visible_to_staff=true
  ) then
    raise exception 'Create or upload a staff-safe MRP PDF/image before approval';
  end if;

  update public.proc_company_price_lists
  set is_current=false,
      status=case when status='approved' then 'archived' else status end,
      updated_at=now()
  where company_id=pl.company_id
    and list_type=pl.list_type
    and id<>pl.id
    and is_current=true;

  update public.proc_company_price_lists
  set status='approved',
      is_current=true,
      approved_by=caller,
      approved_at=now(),
      extraction_status=case when extraction_status='ready' then 'reviewed' else extraction_status end,
      updated_at=now()
  where id=pl.id;

  return 'approved';
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_approve_po_v2(p_po_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

begin
 if not private.proc_has_permission('procurement.orders.approve') then
  raise exception 'Permission denied: procurement.orders.approve' using errcode='42501';
 end if;
 update public.proc_purchase_orders set status='approved'
 where id=p_po_id and status='pending_approval';
 if not found then raise exception 'Purchase order is not pending approval'; end if;
 return 'approved';
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_begin_stock_count_session_v1()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  started timestamptz;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler','stock_checker') then raise exception 'Not authorized'; end if;

  insert into public.proc_stock_count_drafts(owner_id,count_started_at)
  values(caller,now())
  on conflict(owner_id) do update
    set count_started_at=coalesce(public.proc_stock_count_drafts.count_started_at,now()),
        updated_at=now()
  returning count_started_at into started;

  return started;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_capture_status_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare permitted boolean:=private.proc_access_super_admin();until_at timestamptz;session uuid:=nullif(auth.jwt()->>'session_id','')::uuid;
begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='42501';end if;
 if permitted and session is not null then
  select expires_at into until_at from private.proc_capture_overrides where user_id=auth.uid() and session_id=session and expires_at>now();
 end if;
 return jsonb_build_object('can_override',permitted,'capture_allowed',until_at is not null,
  'expires_at',until_at,'expires_in_seconds',case when until_at is null then 0 else least(20,greatest(0,floor(extract(epoch from until_at-now()))::integer)) end);
end $function$

CREATE OR REPLACE FUNCTION public.proc_company_claim_rfq_send(p_id uuid, p_session text, p_image_sha256 text, p_caption text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q public.proc_company_rfq_queue;s public.proc_suppliers;f public.proc_rfqs;lines_v jsonb;actor uuid:=auth.uid();claims_v text;sub_v text;dispatch_v uuid;
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_has_permission('company_lists.view') OR NOT(private.proc_has_permission('stock.count.enter') OR private.proc_has_permission('company_lists.manage')) THEN RAISE EXCEPTION 'Company dispatch permission required';END IF;
 SELECT * INTO q FROM public.proc_company_rfq_queue WHERE id=p_id AND status IN ('pending','failed') FOR UPDATE;
 IF q.id IS NULL THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM public.proc_whatsapp_rfq_dispatches WHERE rfq_id=q.rfq_id AND supplier_id=q.supplier_id) THEN
  UPDATE public.proc_company_rfq_queue SET status='cancelled',last_error='An existing RFQ dispatch attempt must be reviewed. No duplicate sent.',updated_at=now() WHERE id=q.id;RETURN NULL;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.proc_profiles WHERE id=q.automation_admin_id AND active AND role='admin') THEN RAISE EXCEPTION 'Automation administrator inactive';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.proc_company_section_routes cfg JOIN public.proc_company_section_route_suppliers rs ON rs.route_id=cfg.id WHERE cfg.id=q.route_id AND cfg.auto_send AND cfg.route_mode='rfq' AND rs.supplier_id=q.supplier_id) THEN RAISE EXCEPTION 'Route or supplier changed; review unsent RFQ';END IF;
 IF EXISTS(SELECT 1 FROM public.proc_rfq_items ri JOIN public.proc_requirements r ON r.id=ri.requirement_id WHERE ri.rfq_id=q.rfq_id AND (r.status IN ('closed','cancelled','received') OR ri.requested_qty IS DISTINCT FROM greatest(r.adjusted_qty-r.ordered_qty,0))) THEN RAISE EXCEPTION 'Stock requirements have changed; review RFQ quantities before sending';END IF;
 -- Re-resolve each item to block a newly added child override from using an old queued route.
 IF EXISTS(SELECT 1 FROM public.proc_rfq_items ri JOIN public.proc_requirements r ON r.id=ri.requirement_id WHERE ri.rfq_id=q.rfq_id AND private.proc_company_effective_route(q.company_id,r.item_id)->>'route_id' IS DISTINCT FROM q.route_id::text) THEN RAISE EXCEPTION 'RFQ category scope has changed';END IF;
 SELECT * INTO s FROM public.proc_suppliers WHERE id=q.supplier_id AND active AND supplier_kind='company';
 SELECT * INTO f FROM public.proc_rfqs WHERE id=q.rfq_id AND status NOT IN ('closed','cancelled','awarded');
 IF s.id IS NULL OR f.id IS NULL THEN RAISE EXCEPTION 'Supplier or RFQ no longer available';END IF;
 claims_v:=current_setting('request.jwt.claims',true);sub_v:=current_setting('request.jwt.claim.sub',true);
 BEGIN
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',q.automation_admin_id,'role','authenticated')::text,true);PERFORM set_config('request.jwt.claim.sub',q.automation_admin_id::text,true);
  dispatch_v:=public.proc_whatsapp_claim_dispatch(q.rfq_id,q.supplier_id,p_session,p_image_sha256,p_caption);
  PERFORM set_config('request.jwt.claims',coalesce(claims_v,''),true);PERFORM set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);
 EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('request.jwt.claims',coalesce(claims_v,''),true);PERFORM set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);RAISE;
 END;
 UPDATE public.proc_company_rfq_queue SET status='sending',claimed_by=actor,dispatch_id=dispatch_v,last_error=NULL,updated_at=now() WHERE id=q.id;
 RETURN jsonb_build_object('id',q.id,'phone',coalesce(nullif(s.whatsapp,''),s.phone));
END $function$

CREATE OR REPLACE FUNCTION public.proc_company_edit_item(p_list_id uuid, p_patch jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare row_v public.proc_company_list_items; max_v numeric;
begin
 perform private.proc_assert_access();
 if not private.proc_has_permission('company_lists.manage') then raise exception 'Company management permission required';end if;
 select * into row_v from public.proc_company_list_items where id=p_list_id;
 if row_v.id is null then raise exception 'Company item not found';end if;
 if p_patch ? 'target_stock' then
  max_v:=nullif(p_patch->>'target_stock','')::numeric;
  if max_v<0 or max_v::text in ('NaN','Infinity','-Infinity') then raise exception 'Invalid maximum stock';end if;
  update public.proc_company_list_items set target_stock=coalesce(max_v,0),reorder_level=max_v*.5,max_stock_review=max_v is null,updated_at=now() where id=p_list_id;
 end if;
 update public.proc_items set description=coalesce(nullif(trim(p_patch->>'description'),''),description),
 category=coalesce(nullif(trim(p_patch->>'category'),''),category),
 brand=case when p_patch ? 'brand' then nullif(trim(p_patch->>'brand'),'') else brand end,
 subgroup=case when p_patch ? 'subgroup' then nullif(trim(p_patch->>'subgroup'),'') else subgroup end,
 main_group=case when p_patch ? 'main_group' then nullif(trim(p_patch->>'main_group'),'') else main_group end,
 size=case when p_patch ? 'size' then nullif(trim(p_patch->>'size'),'') else size end,
 colour=case when p_patch ? 'colour' then nullif(trim(p_patch->>'colour'),'') else colour end,
 variation=case when p_patch ? 'variation' then nullif(trim(p_patch->>'variation'),'') else variation end,
 uom=coalesce(nullif(trim(p_patch->>'uom'),''),uom),movement=coalesce(nullif(p_patch->>'movement',''),movement),
 remarks=case when p_patch ? 'remarks' then p_patch->>'remarks' else remarks end,
 max_stock=case when p_patch ? 'target_stock' then coalesce(max_v,0) else max_stock end,
 reorder_level=case when p_patch ? 'target_stock' then coalesce(max_v*.5,0) else reorder_level end,updated_at=now() where id=row_v.item_id;
end $function$

CREATE OR REPLACE FUNCTION public.proc_company_finish_rfq_send(p_id uuid, p_status text, p_message_id text, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q public.proc_company_rfq_queue;claims_v text;sub_v text;
BEGIN
 PERFORM private.proc_assert_access();
 IF p_status NOT IN ('accepted','failed','unknown') THEN RAISE EXCEPTION 'Invalid dispatch status';END IF;
 SELECT * INTO q FROM public.proc_company_rfq_queue WHERE id=p_id AND status='sending' AND claimed_by=auth.uid() FOR UPDATE;
 IF q.id IS NULL THEN RAISE EXCEPTION 'Dispatch is not owned by this operator';END IF;
 UPDATE public.proc_company_rfq_queue SET status=p_status,message_id=left(p_message_id,500),last_error=left(p_error,1000),updated_at=now() WHERE id=q.id;
 UPDATE public.proc_whatsapp_rfq_dispatches SET status=p_status,message_id=left(p_message_id,500),last_error=left(p_error,1000),updated_at=now() WHERE id=q.dispatch_id;
 IF p_status='accepted' THEN
  IF NOT EXISTS(SELECT 1 FROM public.proc_profiles WHERE id=q.automation_admin_id AND active AND role='admin') THEN RAISE EXCEPTION 'Automation administrator inactive; inspect accepted send before updating RFQ';END IF;
  claims_v:=current_setting('request.jwt.claims',true);sub_v:=current_setting('request.jwt.claim.sub',true);
  BEGIN
   PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',q.automation_admin_id,'role','authenticated')::text,true);PERFORM set_config('request.jwt.claim.sub',q.automation_admin_id::text,true);
   IF NOT private.proc_has_permission('procurement.rfq.manage') THEN RAISE EXCEPTION 'Automation RFQ permission has been removed';END IF;
  UPDATE public.proc_rfq_suppliers SET status='sent',sent_at=now(),sent_by=q.automation_admin_id WHERE rfq_id=q.rfq_id AND supplier_id=q.supplier_id AND status IN ('pending','prepared');
  UPDATE public.proc_rfqs SET status='sent',updated_at=now() WHERE id=q.rfq_id AND status IN ('draft','prepared') AND NOT EXISTS(SELECT 1 FROM public.proc_rfq_suppliers WHERE rfq_id=q.rfq_id AND status IN ('pending','prepared'));
   PERFORM set_config('request.jwt.claims',coalesce(claims_v,''),true);PERFORM set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);
  EXCEPTION WHEN OTHERS THEN
   PERFORM set_config('request.jwt.claims',coalesce(claims_v,''),true);PERFORM set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);RAISE;
  END;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.proc_company_import_section_paths(p_company_id uuid, p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE element jsonb; parts text[]; dest uuid; changed integer:=0; key text; updated integer;
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_has_permission('company_lists.manage') THEN RAISE EXCEPTION 'Company management permission required'; END IF;
 IF jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows)>15000 THEN RAISE EXCEPTION 'Invalid sheet paths'; END IF;
 FOR element IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
  key=nullif(btrim(element->>'source_key'),'');
  parts=string_to_array(coalesce(element->>'section_path',''),' / ');
  IF key IS NULL OR cardinality(parts)>50 OR nullif(btrim(coalesce(element->>'section_path','')),'') IS NULL THEN CONTINUE; END IF;
  -- Avoid creating orphaned sections for stale / unrelated spreadsheet rows.
  IF EXISTS(SELECT 1 FROM public.proc_company_list_items
            WHERE company_id=p_company_id AND source_key=key AND active AND section_id IS NULL) THEN
   dest=private.proc_company_ensure_section_path(p_company_id,parts);
   UPDATE public.proc_company_list_items SET section_id=dest
   WHERE company_id=p_company_id AND source_key=key AND active AND section_id IS NULL;
   GET DIAGNOSTICS updated=ROW_COUNT; changed=changed+updated;
  END IF;
 END LOOP;
 RETURN changed;
END $function$

CREATE OR REPLACE FUNCTION public.proc_company_import_sheet(p_title text, p_sheet_id bigint, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.proc_companies;i public.proc_items;line public.proc_company_list_items;x jsonb;max_v numeric;count_v integer:=0;
begin
 perform private.proc_assert_access();
 if not private.proc_has_permission('company_lists.manage') or not private.proc_is_role(array['admin']) then raise exception 'Admin company management required';end if;
 if nullif(trim(p_title),'') is null or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>10000 then raise exception 'Invalid company sheet';end if;
 perform pg_advisory_xact_lock(hashtextextended('company-sheet:'||p_sheet_id::text,0));
 select * into c from public.proc_companies where sheet_id=p_sheet_id;
 if c.id is null then select * into c from public.proc_companies where lower(trim(name))=lower(trim(p_title)) order by created_at limit 1;end if;
 if c.id is null then
  insert into public.proc_companies(company_code,name,sheet_id,created_by) values('SHEET-'||p_sheet_id,trim(p_title),p_sheet_id,auth.uid()) returning * into c;
 else update public.proc_companies set sheet_id=coalesce(sheet_id,p_sheet_id) where id=c.id;end if;
 for x in select value from jsonb_array_elements(p_rows) loop
  if nullif(trim(x->>'description'),'') is null or nullif(x->>'source_key','') is null then raise exception 'Missing item description/source';end if;
  max_v:=nullif(x->>'max_stock','')::numeric;
  if max_v<0 or max_v::text in ('NaN','Infinity','-Infinity') then raise exception 'Invalid maximum';end if;
  select * into line from public.proc_company_list_items where company_id=c.id and source_key=x->>'source_key';
  -- Repeated sync never silently overwrites an admin-edited item. Review existing rows separately.
  if line.id is not null then continue;end if;
  select * into i from public.proc_items where lower(trim(description))=lower(trim(x->>'description'))
   and coalesce(size,'')=coalesce(x->>'size','') and coalesce(brand,'')=coalesce(x->>'brand','')
   and coalesce(colour,'')=coalesce(x->>'colour','') and coalesce(variation,'')=coalesce(x->>'variation','')
   and coalesce(subgroup,'')=coalesce(x->>'subgroup','') and coalesce(main_group,'')=coalesce(x->>'main_group','') and category=coalesce(nullif(x->>'category',''),trim(p_title)) order by active desc limit 1;
  if i.id is null then
   insert into public.proc_items(item_code,description,category,main_group,subgroup,brand,size,colour,variation,uom,movement,max_stock,reorder_level,source,remarks)
   values('CI-'||replace(gen_random_uuid()::text,'-',''),trim(x->>'description'),coalesce(nullif(x->>'category',''),trim(p_title)),x->>'main_group',x->>'subgroup',nullif(x->>'brand',''),nullif(x->>'size',''),nullif(x->>'colour',''),nullif(x->>'variation',''),coalesce(nullif(x->>'uom',''),'PCS'),coalesce(nullif(x->>'movement',''),'NORMAL'),coalesce(max_v,0),coalesce(max_v*.5,0),'COMPANY SHEET',x->>'remarks') returning * into i;
  end if;
  insert into public.proc_company_list_items(company_id,item_id,target_stock,reorder_level,max_stock_review,source_key,source_sheet_id,sort_order,created_by)
  values(c.id,i.id,coalesce(max_v,0),max_v*.5,max_v is null,x->>'source_key',p_sheet_id,count_v,auth.uid())
  on conflict(company_id,item_id) do nothing;
  count_v:=count_v+1;i:=null;line:=null;
 end loop;
 update public.proc_companies set sheet_sync_at=now() where id=c.id;
 return jsonb_build_object('company_id',c.id,'imported',count_v);
end $function$

CREATE OR REPLACE FUNCTION public.proc_company_move_group(p_company_id uuid, p_from_field text, p_from text, p_category text, p_main_group text, p_subgroup text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;
begin
 perform private.proc_assert_access();
 if not private.proc_has_permission('company_lists.manage') then raise exception 'Company management permission required';end if;
 if p_from_field not in ('category','main_group','subgroup','brand') or nullif(trim(p_from),'') is null or nullif(trim(p_category),'') is null then raise exception 'Choose a source group and destination category';end if;
 update public.proc_items i set category=trim(p_category),main_group=nullif(trim(p_main_group),''),subgroup=nullif(trim(p_subgroup),''),updated_at=now()
 where exists(select 1 from public.proc_company_list_items c where c.company_id=p_company_id and c.item_id=i.id and c.active)
 and to_jsonb(i)->>p_from_field=p_from;
 get diagnostics n=row_count;return n;
end $function$

CREATE OR REPLACE FUNCTION public.proc_company_move_list_items(p_company_id uuid, p_section_id uuid, p_item_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE expected_count integer; actual_count integer;
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_has_permission('company_lists.manage') THEN RAISE EXCEPTION 'Company management permission required'; END IF;
 IF p_item_ids IS NULL OR cardinality(p_item_ids)<1 OR cardinality(p_item_ids)>500 THEN RAISE EXCEPTION 'Choose between 1 and 500 items'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.proc_company_sections WHERE id=p_section_id AND company_id=p_company_id AND active) THEN
  RAISE EXCEPTION 'Destination section does not belong to the selected company';
 END IF;
 SELECT count(*) INTO expected_count FROM (SELECT DISTINCT unnest(p_item_ids) AS id) unique_ids;
 SELECT count(*) INTO actual_count FROM public.proc_company_list_items WHERE id=ANY(p_item_ids) AND company_id=p_company_id AND active;
 IF actual_count<>expected_count THEN RAISE EXCEPTION 'Some selected rows are not available in this company'; END IF;
 UPDATE public.proc_company_list_items SET section_id=p_section_id
  WHERE id=ANY(p_item_ids) AND company_id=p_company_id AND active;
 GET DIAGNOSTICS actual_count=ROW_COUNT;
 RETURN actual_count;
END $function$

CREATE OR REPLACE FUNCTION public.proc_company_prepare_group_po(p_company_id uuid, p_section_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ids uuid[];result_v jsonb;
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_is_role(ARRAY['admin']) OR NOT private.proc_has_permission('procurement.orders.approve')
 THEN RAISE EXCEPTION 'Admin purchase-order approval required';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.proc_company_section_routes WHERE company_id=p_company_id AND section_id=p_section_id AND route_mode='direct')
 THEN RAISE EXCEPTION 'This group is not configured for direct POs';END IF;
 SELECT array_agg(r.id) INTO ids FROM public.proc_requirements r WHERE r.company_id=p_company_id
  AND r.approval_status='approved' AND r.adjusted_qty>r.ordered_qty AND r.status NOT IN ('closed','cancelled','received')
