CREATE OR REPLACE FUNCTION public.proc_company_save_group_contacts(p_company_id uuid, p_section_id uuid, p_supplier_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ids uuid[]; sid uuid;
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_is_role(ARRAY['admin']) OR NOT private.proc_has_permission('company_lists.manage') THEN
  RAISE EXCEPTION 'Company administrator required';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.proc_companies WHERE id=p_company_id AND active) OR
    NOT EXISTS (SELECT 1 FROM public.proc_company_sections WHERE id=p_section_id AND company_id=p_company_id AND active) THEN
  RAISE EXCEPTION 'Select an active group belonging to this company';
 END IF;
 SELECT array_agg(id ORDER BY first_pos) INTO ids FROM
  (SELECT id,min(ord) AS first_pos FROM unnest(p_supplier_ids) WITH ORDINALITY AS t(id,ord) GROUP BY id) selected;
 IF coalesce(cardinality(ids),0) NOT BETWEEN 1 AND 15 THEN RAISE EXCEPTION 'Assign 1–15 supplier contacts'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(ids) t(id) WHERE NOT EXISTS(
   SELECT 1 FROM public.proc_suppliers s WHERE s.id=t.id AND s.active AND s.supplier_kind='company'
 )) THEN RAISE EXCEPTION 'Only active company supplier contacts can be assigned'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('company-contact-group:'||p_section_id::text,0));
 DELETE FROM public.proc_company_group_contacts WHERE section_id=p_section_id AND company_id=p_company_id;
 FOREACH sid IN ARRAY ids LOOP
  INSERT INTO public.proc_company_group_contacts(company_id,section_id,supplier_id,sort_order)
  VALUES(p_company_id,p_section_id,sid,array_position(ids,sid));
 END LOOP;
 RETURN jsonb_build_object('company_id',p_company_id,'section_id',p_section_id,'supplier_count',cardinality(ids));
END $function$

CREATE OR REPLACE FUNCTION public.proc_company_save_route_v2(p_company_id uuid, p_section_id uuid, p_mode text, p_auto_send boolean, p_supplier_ids uuid[], p_template jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE route_v uuid;ids uuid[];supplier_v uuid;
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_is_role(ARRAY['admin']) OR NOT private.proc_has_permission('company_lists.manage') THEN RAISE EXCEPTION 'Company administrator required';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.proc_companies WHERE id=p_company_id AND active) THEN RAISE EXCEPTION 'Company unavailable';END IF;
 IF p_section_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.proc_company_sections WHERE id=p_section_id AND company_id=p_company_id AND active) THEN RAISE EXCEPTION 'Category must belong to this company';END IF;
 IF p_mode IS NULL OR p_mode NOT IN ('direct','rfq') THEN RAISE EXCEPTION 'Choose RFQ or PO';END IF;
 IF coalesce(p_auto_send,false) AND NOT private.proc_has_permission(CASE WHEN p_mode='rfq' THEN 'procurement.rfq.manage' ELSE 'procurement.orders.approve' END) THEN RAISE EXCEPTION 'Document approval permission required for automation';END IF;
 SELECT array_agg(id ORDER BY position) INTO ids FROM (SELECT id,min(n) position FROM unnest(p_supplier_ids) WITH ORDINALITY AS t(id,n) GROUP BY id) x;
 IF coalesce(cardinality(ids),0) NOT BETWEEN 1 AND 15 OR (p_mode='direct' AND cardinality(ids)<>1) THEN RAISE EXCEPTION 'Choose one supplier for PO or 1–15 for RFQ';END IF;
 IF EXISTS(SELECT 1 FROM unnest(ids) x(id) WHERE NOT EXISTS(SELECT 1 FROM public.proc_suppliers WHERE proc_suppliers.id=x.id AND active AND supplier_kind='company' AND (NOT coalesce(p_auto_send,false) OR coalesce(nullif(whatsapp,''),phone) ~ '^\+94[0-9]{9}$'))) THEN RAISE EXCEPTION 'Select active company suppliers with valid +94 WhatsApp numbers for automatic sending';END IF;
 IF p_template IS NULL OR jsonb_typeof(p_template)<>'object' OR octet_length(p_template::text)>6000 OR length(coalesce(p_template->>'name',''))>80 OR length(coalesce(p_template->>'title',''))>60 OR length(coalesce(p_template->>'note',''))>300 OR length(coalesce(p_template->>'caption',''))>2000 THEN RAISE EXCEPTION 'Invalid document template';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('company-group-route:'||p_company_id::text||coalesce(p_section_id::text,''),0));
 SELECT id INTO route_v FROM public.proc_company_section_routes WHERE company_id=p_company_id AND section_id IS NOT DISTINCT FROM p_section_id FOR UPDATE;
 IF route_v IS NULL THEN
  INSERT INTO public.proc_company_section_routes(company_id,section_id,route_mode,auto_send,document_template,updated_by) VALUES(p_company_id,p_section_id,p_mode,coalesce(p_auto_send,false),p_template,auth.uid()) RETURNING id INTO route_v;
 ELSE UPDATE public.proc_company_section_routes SET route_mode=p_mode,auto_send=coalesce(p_auto_send,false),document_template=p_template,updated_by=auth.uid(),updated_at=now() WHERE id=route_v;END IF;
 DELETE FROM public.proc_company_section_route_suppliers WHERE route_id=route_v;
 FOREACH supplier_v IN ARRAY ids LOOP INSERT INTO public.proc_company_section_route_suppliers(route_id,supplier_id,sort_order) VALUES(route_v,supplier_v,array_position(ids,supplier_v));END LOOP;
 IF coalesce(p_auto_send,false) THEN UPDATE public.proc_companies SET group_auto_approve=true,automation_admin_id=auth.uid(),updated_at=now() WHERE id=p_company_id;END IF;
 RETURN jsonb_build_object('id',route_v);
END $function$

CREATE OR REPLACE FUNCTION public.proc_company_save_section_route(p_company_id uuid, p_section_id uuid, p_mode text, p_auto_send boolean, p_supplier_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE route_v uuid; supplier_v uuid; sorted_ids uuid[];
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_is_role(ARRAY['admin']) OR NOT private.proc_has_permission('company_lists.manage') THEN
  RAISE EXCEPTION 'Only company administrators may configure supplier routing';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.proc_company_sections WHERE id=p_section_id AND company_id=p_company_id AND active)
  THEN RAISE EXCEPTION 'Group must belong to this company'; END IF;
 IF p_mode NOT IN ('rfq','direct') OR p_mode IS NULL THEN RAISE EXCEPTION 'Choose RFQ or direct purchase order'; END IF;
 SELECT array_agg(id ORDER BY first_position) INTO sorted_ids FROM (SELECT id,min(position) first_position FROM unnest(p_supplier_ids) WITH ORDINALITY AS ids(id,position) GROUP BY id) picked;
 IF coalesce(cardinality(sorted_ids),0)=0 OR cardinality(sorted_ids)>15 THEN RAISE EXCEPTION 'Select 1–15 suppliers for this group';END IF;
 IF p_mode='direct' AND cardinality(sorted_ids)<>1 THEN RAISE EXCEPTION 'Direct PO requires exactly one supplier';END IF;
 IF EXISTS(SELECT 1 FROM unnest(sorted_ids) chosen(id) WHERE NOT EXISTS(
  SELECT 1 FROM public.proc_suppliers s WHERE s.id=chosen.id AND s.active AND s.supplier_kind='company'
 )) THEN RAISE EXCEPTION 'Select active company supplier contacts only';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('company-group-route:'||p_section_id::text,0));
 INSERT INTO public.proc_company_section_routes(company_id,section_id,route_mode,auto_send,updated_by)
 VALUES(p_company_id,p_section_id,p_mode,case when p_mode='direct' then coalesce(p_auto_send,true) else false end,auth.uid())
 ON CONFLICT(company_id,section_id) DO UPDATE SET route_mode=excluded.route_mode,auto_send=excluded.auto_send,updated_by=auth.uid(),updated_at=now()
 RETURNING id INTO route_v;
 DELETE FROM public.proc_company_section_route_suppliers WHERE route_id=route_v;
 FOR supplier_v IN SELECT unnest(sorted_ids) LOOP
  INSERT INTO public.proc_company_section_route_suppliers(route_id,supplier_id,sort_order)
  VALUES(route_v,supplier_v,array_position(sorted_ids,supplier_v));
 END LOOP;
 -- Saving an auto-send direct group is explicit admin authorization for normal
 -- stock submissions to make approved quantity-only orders. Legacy routes stay unchanged.
 IF p_mode='direct' AND coalesce(p_auto_send,true) THEN
  UPDATE public.proc_companies SET group_auto_approve=true,automation_admin_id=auth.uid(),updated_at=now() WHERE id=p_company_id;
 END IF;
 RETURN jsonb_build_object('id',route_v,'mode',p_mode,'suppliers',cardinality(sorted_ids));
END $function$

CREATE OR REPLACE FUNCTION public.proc_company_seed_sections(p_company_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r record; dest uuid; n integer:=0;
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_has_permission('company_lists.manage') THEN RAISE EXCEPTION 'Company management permission required'; END IF;
 FOR r IN SELECT cli.id, i.category,i.main_group,i.subgroup FROM public.proc_company_list_items cli
 JOIN public.proc_items i ON i.id=cli.item_id
 WHERE cli.company_id=p_company_id AND cli.active AND cli.section_id IS NULL LOOP
  dest:=private.proc_company_ensure_section_path(p_company_id,ARRAY[r.category,r.main_group,r.subgroup]);
  UPDATE public.proc_company_list_items SET section_id=dest WHERE id=r.id AND section_id IS NULL;
  n:=n+1;
 END LOOP;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.proc_convert_missing_item_request_v1(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  q public.proc_item_requests;
  item_id_v uuid;
  req jsonb;
  code_v text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Admin or Procurement access required'; end if;

  select * into q from public.proc_item_requests where id=p_request_id for update;
  if q.id is null then raise exception 'Missing-item request not found'; end if;
  if q.status in ('converted','rejected','cancelled') then raise exception 'This request is already closed'; end if;

  select id into item_id_v
  from public.proc_items
  where active=true
    and lower(regexp_replace(trim(description),'\s+',' ','g'))=lower(regexp_replace(trim(q.proposed_name),'\s+',' ','g'))
    and lower(coalesce(trim(size),''))=lower(coalesce(trim(q.size),''))
    and lower(coalesce(trim(brand),''))=lower(coalesce(trim(q.brand),''))
  order by created_at
  limit 1;

  if item_id_v is null then
    code_v:='REQ-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
    insert into public.proc_items(
      item_code,category,description,brand,main_group,subgroup,size,uom,
      max_stock,movement,reorder_level,remarks,source,active
    )
    values(
      code_v,q.category,q.proposed_name,q.brand,q.main_group,q.subgroup,q.size,q.uom,
      greatest(q.suggested_max_stock,q.required_qty),q.movement,0,
      'Created from customer/missing-item request '||q.request_no,
      'MISSING ITEM REQUEST',true
    )
    returning id into item_id_v;
  end if;

  req:=public.proc_mark_item_urgent_v1(
    item_id_v,q.required_qty,q.urgency_reason,0,q.customer_paid,
    q.customer_reference,q.notes,q.image_path
  );

  update public.proc_requirements
  set source_type='missing_item',updated_at=now()
  where id=(req->>'requirement_id')::uuid;

  update public.proc_item_requests
  set status='converted',converted_item_id=item_id_v,
      converted_requirement_id=(req->>'requirement_id')::uuid,
      reviewed_by=caller,reviewed_at=now(),updated_at=now()
  where id=q.id;

  return jsonb_build_object(
    'request_id',q.id,'item_id',item_id_v,
    'requirement_id',(req->>'requirement_id')::uuid,
    'requirement_no',req->>'requirement_no'
  );
end;
end;$function$

