CREATE OR REPLACE FUNCTION public.proc_create_invoice_v2(p_po_id uuid, p_invoice_no text, p_lines jsonb, p_attachment_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  po public.proc_purchase_orders;
  iid uuid;
  x jsonb;
  pl public.proc_po_lines;
  q numeric;
  pr numeric;
  v_subtotal numeric:=0;
  v_variance boolean:=false;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;
  if nullif(trim(p_invoice_no),'') is null then raise exception 'Invoice number is required'; end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'Invoice lines are required'; end if;

  select * into po from public.proc_purchase_orders where id=p_po_id;
  if po.id is null then raise exception 'Purchase order not found'; end if;
  if po.status not in ('approved','sent','partially_received','received') then raise exception 'Invoice cannot be entered for this purchase order status'; end if;

  insert into public.proc_supplier_invoices(supplier_id,po_id,invoice_no,subtotal,total,attachment_path,status,notes,entered_by)
  values(po.supplier_id,po.id,trim(p_invoice_no),0,0,p_attachment_path,'entered',p_notes,caller)
  returning id into iid;

  for x in select * from jsonb_array_elements(p_lines)
  loop
    select * into pl from public.proc_po_lines where id=(x->>'po_line_id')::uuid and po_id=po.id;
    if pl.id is null then raise exception 'Invoice line is not part of the selected PO'; end if;
    q := (x->>'qty')::numeric;
    pr := (x->>'unit_price')::numeric;
    if q is null or q<0 or pr is null or pr<0 then raise exception 'Invoice quantity and price must be zero or positive'; end if;
    if q<>pl.qty or pr<>pl.unit_price then v_variance:=true; end if;
    insert into public.proc_invoice_lines(invoice_id,po_line_id,item_id,qty,unit_price)
    values(iid,pl.id,pl.item_id,q,pr);
    v_subtotal:=v_subtotal+round(q*pr,2);
  end loop;

  update public.proc_supplier_invoices
  set subtotal=v_subtotal,
      total=v_subtotal,
      status=case when v_variance then 'variance' else 'matched' end
  where id=iid;

  return jsonb_build_object(
    'invoice_id',iid,
    'status',case when v_variance then 'variance' else 'matched' end,
    'total',v_subtotal
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_create_invoice_v3(p_po_id uuid, p_invoice_no text, p_lines jsonb, p_attachment_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  po public.proc_purchase_orders;
  iid uuid;
  x jsonb;
  pl public.proc_po_lines;
  q numeric;
  pr numeric;
  disc numeric;
  tax numeric;
  line_net numeric;
  line_tax numeric;
  v_subtotal numeric:=0;
  v_tax_total numeric:=0;
  v_variance boolean:=false;
begin
  if caller is null then raise exception 'Not authenticated'; end if;

  select role into caller_role
  from public.proc_profiles
  where id=caller and active=true;

  if caller_role is null or caller_role not in ('admin','procurement') then
    raise exception 'Not authorized';
  end if;

  if nullif(trim(p_invoice_no),'') is null then
    raise exception 'Invoice number is required';
  end if;

  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then
    raise exception 'Invoice lines are required';
  end if;

  select * into po
  from public.proc_purchase_orders
  where id=p_po_id;

  if po.id is null then raise exception 'Purchase order not found'; end if;
  if po.status not in ('approved','sent','partially_received','received') then
    raise exception 'Invoice cannot be entered for this purchase order status';
  end if;

  insert into public.proc_supplier_invoices(
    supplier_id,po_id,invoice_no,subtotal,tax_total,total,
    attachment_path,status,notes,entered_by
  )
  values(
    po.supplier_id,po.id,trim(p_invoice_no),0,0,0,
    p_attachment_path,'entered',p_notes,caller
  )
  returning id into iid;

  for x in select * from jsonb_array_elements(p_lines)
  loop
    select * into pl
    from public.proc_po_lines
    where id=(x->>'po_line_id')::uuid
      and po_id=po.id;

    if pl.id is null then
      raise exception 'Invoice line is not part of the selected PO';
    end if;

    q:=(x->>'qty')::numeric;
    pr:=(x->>'unit_price')::numeric;
    disc:=coalesce(nullif(x->>'discount_percent','')::numeric,0);
    tax:=coalesce(nullif(x->>'tax_percent','')::numeric,0);

    if q is null or q<0 or pr is null or pr<0 then
      raise exception 'Invoice quantity and price must be zero or positive';
    end if;
    if disc<0 or disc>100 or tax<0 or tax>100 then
      raise exception 'Discount and tax percentages must be between 0 and 100';
    end if;

    if q<>pl.qty
       or pr<>pl.unit_price
       or disc<>pl.discount_percent
       or tax<>pl.tax_percent then
      v_variance:=true;
    end if;

    insert into public.proc_invoice_lines(
      invoice_id,po_line_id,item_id,qty,unit_price,discount_percent,tax_percent
    )
    values(
      iid,pl.id,pl.item_id,q,pr,disc,tax
    );

    line_net:=round(q*pr*(1-disc/100.0),2);
    line_tax:=round(line_net*(tax/100.0),2);
    v_subtotal:=v_subtotal+line_net;
    v_tax_total:=v_tax_total+line_tax;
  end loop;

  update public.proc_supplier_invoices
  set subtotal=v_subtotal,
      tax_total=v_tax_total,
      total=v_subtotal+v_tax_total,
      status=case when v_variance then 'variance' else 'matched' end
  where id=iid;

  return jsonb_build_object(
    'invoice_id',iid,
    'status',case when v_variance then 'variance' else 'matched' end,
    'subtotal',v_subtotal,
    'tax_total',v_tax_total,
    'total',v_subtotal+v_tax_total
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_create_invoice_v4(p_po_id uuid, p_invoice_no text, p_lines jsonb, p_attachment_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid(); caller_role text; po public.proc_purchase_orders; iid uuid; x jsonb; pl public.proc_po_lines;
  q numeric; pr numeric; disc numeric; tax numeric; line_net numeric; line_tax numeric;
  accepted_to_date numeric; previously_invoiced numeric; available_to_invoice numeric;
  v_subtotal numeric:=0; v_tax_total numeric:=0; v_variance boolean:=false; details jsonb:='[]'::jsonb;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;
  if not private.proc_has_permission('invoices.manage') then raise exception 'Permission denied: invoices.manage' using errcode='42501'; end if;
  if nullif(trim(p_invoice_no),'') is null then raise exception 'Invoice number is required'; end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'Invoice lines are required'; end if;

  if (select count(*)<>count(distinct entry.value->>'po_line_id') from jsonb_array_elements(p_lines) as entry(value)) then raise exception 'Each purchase order line may appear only once per invoice'; end if;
  select * into po from public.proc_purchase_orders where id=p_po_id for update;
  if po.id is null then raise exception 'Purchase order not found'; end if;
  if po.status not in ('approved','sent','partially_received','received') then raise exception 'Invoice cannot be entered for this purchase order status'; end if;

  insert into public.proc_supplier_invoices(supplier_id,po_id,invoice_no,subtotal,tax_total,total,attachment_path,status,notes,entered_by)
  values(po.supplier_id,po.id,trim(p_invoice_no),0,0,0,p_attachment_path,'entered',p_notes,caller)
  returning id into iid;

  for x in select * from jsonb_array_elements(p_lines) loop
    select * into pl from public.proc_po_lines where id=(x->>'po_line_id')::uuid and po_id=po.id;
    if pl.id is null then raise exception 'Invoice line is not part of the selected PO'; end if;

    q:=(x->>'qty')::numeric; pr:=(x->>'unit_price')::numeric;
    disc:=coalesce(nullif(x->>'discount_percent','')::numeric,0);
    tax:=coalesce(nullif(x->>'tax_percent','')::numeric,0);
    if q is null or q<=0 or pr is null or pr<0 then raise exception 'Invoice quantity must be greater than zero and price cannot be negative'; end if;
    if disc<0 or disc>100 or tax<0 or tax>100 then raise exception 'Discount and tax percentages must be between 0 and 100'; end if;

    select coalesce(sum(gl.accepted_qty),0) into accepted_to_date
    from public.proc_grn_lines gl join public.proc_grns g on g.id=gl.grn_id
    where gl.po_line_id=pl.id and g.status='posted';

    select coalesce(sum(il.qty),0) into previously_invoiced
    from public.proc_invoice_lines il
    join public.proc_supplier_invoices si on si.id=il.invoice_id
    where il.po_line_id=pl.id and si.id<>iid and si.status<>'rejected';

    available_to_invoice:=greatest(accepted_to_date-previously_invoiced,0);
    if q>available_to_invoice or pr<>pl.unit_price or disc<>pl.discount_percent or tax<>pl.tax_percent then v_variance:=true; end if;

    insert into public.proc_invoice_lines(invoice_id,po_line_id,item_id,qty,unit_price,discount_percent,tax_percent)
    values(iid,pl.id,pl.item_id,q,pr,disc,tax);

    details:=details||jsonb_build_array(jsonb_build_object(
      'po_line_id',pl.id,'invoice_qty',q,'accepted_to_date',accepted_to_date,
      'previously_invoiced',previously_invoiced,'available_to_invoice',available_to_invoice,
      'qty_match',q<=available_to_invoice,'commercial_match',
        (pr=pl.unit_price and disc=pl.discount_percent and tax=pl.tax_percent)
    ));

    line_net:=round(q*pr*(1-disc/100.0),2);
    line_tax:=round(line_net*(tax/100.0),2);
    v_subtotal:=v_subtotal+line_net; v_tax_total:=v_tax_total+line_tax;
  end loop;

  update public.proc_supplier_invoices
  set subtotal=v_subtotal,tax_total=v_tax_total,total=v_subtotal+v_tax_total,
      status=case when v_variance then 'variance' else 'matched' end,
      match_detail=details
  where id=iid;

  return jsonb_build_object(
    'invoice_id',iid,'status',case when v_variance then 'variance' else 'matched' end,
    'subtotal',v_subtotal,'tax_total',v_tax_total,'total',v_subtotal+v_tax_total,
    'match_detail',details
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_create_missing_item_request_v1(p_proposed_name text, p_required_qty numeric, p_movement text DEFAULT 'NORMAL'::text, p_brand text DEFAULT NULL::text, p_category text DEFAULT 'GENERAL'::text, p_main_group text DEFAULT NULL::text, p_subgroup text DEFAULT NULL::text, p_size text DEFAULT NULL::text, p_uom text DEFAULT 'PCS'::text, p_suggested_max_stock numeric DEFAULT 0, p_priority text DEFAULT NULL::text, p_urgency_reason text DEFAULT 'customer_request'::text, p_customer_paid boolean DEFAULT false, p_customer_reference text DEFAULT NULL::text, p_image_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  v_priority text;
  v_no text;
  rid uuid;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler','stock_checker') then raise exception 'Not authorized'; end if;

  if nullif(trim(coalesce(p_proposed_name,'')),'') is null then raise exception 'Item name is required'; end if;
  if p_required_qty is null or p_required_qty<=0 then raise exception 'Required quantity must be greater than zero'; end if;
  if upper(coalesce(p_movement,'NORMAL')) not in ('FAST','NORMAL','SLOW') then raise exception 'Invalid movement'; end if;
  if p_suggested_max_stock is null or p_suggested_max_stock<0 then raise exception 'Suggested max stock cannot be negative'; end if;
  if p_urgency_reason not in ('zero_stock','fast_mover','bulk_sale','customer_paid','customer_request','manual_urgent') then raise exception 'Invalid urgency reason'; end if;

  if exists(
    select 1 from public.proc_items i
    where i.active=true
      and lower(regexp_replace(trim(i.description),'\s+',' ','g'))=
          lower(regexp_replace(trim(p_proposed_name),'\s+',' ','g'))
      and lower(coalesce(trim(i.size),''))=lower(coalesce(trim(p_size),''))
      and lower(coalesce(trim(i.brand),''))=lower(coalesce(trim(p_brand),''))
  ) then
    raise exception 'This item already exists in the Item Master. Use Existing Item · Urgent instead.';
  end if;

  if exists(
    select 1 from public.proc_item_requests q
    where q.status in ('pending_review','approved')
      and lower(regexp_replace(trim(q.proposed_name),'\s+',' ','g'))=
          lower(regexp_replace(trim(p_proposed_name),'\s+',' ','g'))
      and lower(coalesce(trim(q.size),''))=lower(coalesce(trim(p_size),''))
      and lower(coalesce(trim(q.brand),''))=lower(coalesce(trim(p_brand),''))
  ) then
    raise exception 'A pending missing-item request already exists for this item.';
  end if;

  v_priority:=coalesce(nullif(p_priority,''),
    case
      when p_customer_paid or p_urgency_reason in ('zero_stock','bulk_sale','customer_paid','manual_urgent') then 'urgent'
      when upper(coalesce(p_movement,'NORMAL'))='FAST' then 'high'
      else 'high'
    end
  );
  if v_priority not in ('low','normal','high','urgent') then raise exception 'Invalid priority'; end if;

  v_no:='MIR-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');

  insert into public.proc_item_requests(
    request_no,proposed_name,brand,category,main_group,subgroup,size,uom,movement,
    required_qty,suggested_max_stock,priority,urgency_reason,customer_paid,
    customer_reference,image_path,notes,created_by
  )
  values(
    v_no,trim(p_proposed_name),nullif(trim(coalesce(p_brand,'')),''),
    coalesce(nullif(trim(coalesce(p_category,'')),''),'GENERAL'),
    nullif(trim(coalesce(p_main_group,'')),''),nullif(trim(coalesce(p_subgroup,'')),''),
    nullif(trim(coalesce(p_size,'')),''),coalesce(nullif(upper(trim(coalesce(p_uom,''))),''),'PCS'),
    upper(coalesce(p_movement,'NORMAL')),p_required_qty,p_suggested_max_stock,v_priority,
    p_urgency_reason,p_customer_paid,nullif(trim(coalesce(p_customer_reference,'')),''),
    p_image_path,nullif(trim(coalesce(p_notes,'')),''),caller
  )
  returning id into rid;

  return jsonb_build_object('request_id',rid,'request_no',v_no,'priority',v_priority);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_create_rfq_v3(p_requirement_ids uuid[], p_supplier_ids uuid[], p_due_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_scope_overrides jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  rid uuid;
  sid uuid;
  req public.proc_requirements;
  rfq_id uuid;
  rfq_no text;
  scopes_exist boolean;
  matched_count integer;
  override_reason text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;
  if coalesce(array_length(p_requirement_ids,1),0)=0 then raise exception 'Select at least one requirement'; end if;
  if coalesce(array_length(p_supplier_ids,1),0)=0 then raise exception 'Select at least one supplier'; end if;

  foreach rid in array p_requirement_ids loop
    select * into req from public.proc_requirements where id=rid for update;
    if req.id is null or req.status in ('received','closed','cancelled') then raise exception 'Invalid requirement'; end if;
    if req.approval_status<>'approved' or req.selected_for_order<>true then
      raise exception 'Requirement must be approved and selected before requesting supplier prices';
    end if;
    if greatest(req.adjusted_qty-req.ordered_qty,0)<=0 then raise exception 'Requirement has no remaining quantity to order'; end if;
    if exists(
      select 1 from public.proc_rfq_items ri
      join public.proc_rfqs q on q.id=ri.rfq_id
      where ri.requirement_id=req.id
        and q.status in ('draft','prepared','sent','partially_quoted','quoted')
    ) then raise exception 'Requirement is already in an active supplier price request'; end if;
  end loop;

  foreach sid in array p_supplier_ids loop
    if not exists(select 1 from public.proc_suppliers where id=sid and active=true) then raise exception 'Invalid or inactive supplier'; end if;
    select exists(select 1 from public.proc_supplier_scopes sc where sc.supplier_id=sid) into scopes_exist;
    if scopes_exist then
      select count(*) into matched_count
      from public.proc_requirements rr
      join public.proc_items i on i.id=rr.item_id
      where rr.id=any(p_requirement_ids)
        and exists(
          select 1 from public.proc_supplier_scopes sc
          where sc.supplier_id=sid
            and (
              (sc.scope_type='item' and sc.item_id=i.id)
              or (sc.scope_type='category' and sc.scope_value=i.category)
              or (sc.scope_type='main_group' and sc.scope_value=i.main_group)
              or (sc.scope_type='subgroup' and sc.scope_value=i.subgroup)
            )
        );
      if matched_count=0 then
        override_reason:=nullif(trim(coalesce(p_scope_overrides->>sid::text,'')),'');
        if override_reason is null then
          raise exception 'Supplier % does not cover any selected item. Add an override reason or choose another supplier.',
            (select name from public.proc_suppliers where id=sid);
        end if;
      end if;
    end if;
  end loop;

  rfq_no:='RFQ-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');
  insert into public.proc_rfqs(rfq_no,status,due_date,notes,created_by)
  values(rfq_no,'prepared',p_due_date,p_notes,caller)
  returning id into rfq_id; select q.rfq_no into rfq_no from public.proc_rfqs q where q.id=rfq_id;

  foreach rid in array p_requirement_ids loop
    select * into req from public.proc_requirements where id=rid for update;
    insert into public.proc_rfq_items(rfq_id,requirement_id,requested_qty)
    values(rfq_id,req.id,greatest(req.adjusted_qty-req.ordered_qty,0));
    update public.proc_requirements set status='quoting',updated_at=now() where id=req.id;
  end loop;

  foreach sid in array p_supplier_ids loop
    override_reason:=nullif(trim(coalesce(p_scope_overrides->>sid::text,'')),'');
    insert into public.proc_rfq_suppliers(rfq_id,supplier_id,status,sent_at,sent_by,scope_override_reason)
    values(rfq_id,sid,'pending',null,null,override_reason);
  end loop;

  perform private.proc_upsert_automation_job_v1(
    'rfq_send','rfq',rfq_id,'needs_action',
    jsonb_build_object('suppliers',coalesce(array_length(p_supplier_ids,1),0),'due_date',p_due_date),
    'RFQ prepared. Confirm actual supplier transmission.'
  );

  return jsonb_build_object('rfq_id',rfq_id,'rfq_no',rfq_no,'status','prepared');
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_finalize_award_plan_v1(p_rfq_id uuid, p_allocations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  rfq_rec public.proc_rfqs;
  x jsonb;
  ri public.proc_rfq_items;
  ql public.proc_quote_lines;
  q public.proc_quotes;
  r public.proc_requirements;
  qty_v numeric;
  outstanding numeric;
  selected_target numeric;
  allocated_total numeric;
  available_v numeric;
  best_landed numeric;
  landed_v numeric;
  effective_v numeric;
  freight_unit_v numeric;
  method_v text;
  reason_v text;
  supplier_goods numeric;
  po_map jsonb:='{}'::jsonb;
  v_po_id uuid;
  supplier_key text;
  po_number text;
  map_rec record;
  result jsonb:='[]'::jsonb;
  subtotal_v numeric;
  tax_v numeric;
  goods_total_v numeric;
  freight_v numeric;
  preferred_quotes integer;
  received_quotes integer;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;
  if jsonb_typeof(p_allocations)<>'array' or jsonb_array_length(p_allocations)=0 then
    raise exception 'Award allocations are required';
  end if;

  select * into rfq_rec from public.proc_rfqs where id=p_rfq_id for update;
  if rfq_rec.id is null then raise exception 'RFQ not found'; end if;
  if rfq_rec.status in ('awarded','closed','cancelled') then raise exception 'RFQ has already been awarded or closed'; end if;

  -- One valid supplier price is sufficient; validate every allocation below.
  -- Every selected item must be completely allocated.
  for ri in
    select * from public.proc_rfq_items where rfq_id=p_rfq_id and selected_for_po=true
  loop
    select * into r from public.proc_requirements where id=ri.requirement_id for update;
    outstanding:=least(ri.requested_qty,greatest(r.adjusted_qty-r.ordered_qty,0));
    select coalesce(sum((a->>'qty')::numeric),0) into allocated_total
    from jsonb_array_elements(p_allocations) a
    where (a->>'rfq_item_id')::uuid=ri.id;
    if allocated_total<outstanding then
      raise exception 'Award plan must cover the full outstanding quantity for item % (required %, allocated %)',
        ri.id,outstanding,allocated_total;
    end if;
    if allocated_total>outstanding and not exists(
      select 1 from jsonb_array_elements(p_allocations) a
      where (a->>'rfq_item_id')::uuid=ri.id
        and nullif(trim(coalesce(a->>'override_reason','')),'') is not null
    ) then
      raise exception 'Award quantity exceeds the requirement for item %. Add an override reason for MOQ/order-multiple overbuy.',ri.id;
    end if;
  end loop;

  -- Validate each allocation before any PO is written.
  for x in select * from jsonb_array_elements(p_allocations)
  loop
    select * into ri
    from public.proc_rfq_items
    where id=(x->>'rfq_item_id')::uuid and rfq_id=p_rfq_id and selected_for_po=true;
    if ri.id is null then raise exception 'Award item does not belong to the selected RFQ'; end if;

    select * into ql from public.proc_quote_lines where id=(x->>'quote_line_id')::uuid;
    if ql.id is null or ql.rfq_item_id<>ri.id then raise exception 'Award quote line does not match the RFQ item'; end if;
    select * into q from public.proc_quotes where id=ql.quote_id and rfq_id=p_rfq_id;
    if q.id is null or q.status not in ('received','reviewed','selected') then raise exception 'Award quote is not available'; end if;

    qty_v:=(x->>'qty')::numeric;
    if qty_v is null or qty_v<=0 then raise exception 'Award quantity must be greater than zero'; end if;
    available_v:=coalesce(ql.available_qty,qty_v);
    if qty_v>available_v then raise exception 'Award quantity exceeds supplier availability'; end if;
    if ql.moq>0 and qty_v<ql.moq then raise exception 'Award quantity is below supplier MOQ'; end if;
    if ql.order_multiple>0 and mod(qty_v,ql.order_multiple)<>0 then
      raise exception 'Award quantity must respect the supplier order multiple';
    end if;

    select min(v.landed_unit_cost) into best_landed
    from public.proc_v_quote_comparison v
    where v.rfq_item_id=ri.id;

    select v.landed_unit_cost,v.effective_unit_price,v.freight_unit_cost
    into landed_v,effective_v,freight_unit_v
    from public.proc_v_quote_comparison v
    where v.quote_line_id=ql.id;

    if landed_v is null then raise exception 'Award quote is missing landed-cost comparison data'; end if;

    reason_v:=nullif(trim(coalesce(x->>'override_reason','')),'');
    method_v:=case when landed_v<=best_landed then 'recommended' else 'override' end;
    if method_v='override' and reason_v is null then
      raise exception 'Choosing a non-recommended supplier requires an override reason';
    end if;
  end loop;

  -- Supplier minimum-order values are enforced against planned effective goods value.
  for q in
    select distinct qq.*
    from public.proc_quotes qq
    join public.proc_quote_lines qql on qql.quote_id=qq.id
    join jsonb_array_elements(p_allocations) a on (a->>'quote_line_id')::uuid=qql.id
    where qq.rfq_id=p_rfq_id
  loop
    select coalesce(sum(
      (a->>'qty')::numeric
      * ql2.unit_price
      * (1-ql2.discount_percent/100.0)
      * (1+ql2.tax_percent/100.0)
    ),0)
    into supplier_goods
    from jsonb_array_elements(p_allocations) a
    join public.proc_quote_lines ql2 on ql2.id=(a->>'quote_line_id')::uuid
    where ql2.quote_id=q.id;

    if q.minimum_order_value>0 and supplier_goods<q.minimum_order_value then
      if not exists(
        select 1
        from jsonb_array_elements(p_allocations) a
        join public.proc_quote_lines ql3 on ql3.id=(a->>'quote_line_id')::uuid
        where ql3.quote_id=q.id
          and nullif(trim(coalesce(a->>'override_reason','')),'') is not null
      ) then
        raise exception 'Supplier minimum order value is %, but this award plan is only %. Add an override reason or adjust the award.',
          q.minimum_order_value,round(supplier_goods,2);
      end if;
    end if;
  end loop;

  -- Create one pending PO per supplier.
  for x in select * from jsonb_array_elements(p_allocations)
  loop
    select * into ri from public.proc_rfq_items where id=(x->>'rfq_item_id')::uuid;
    select * into ql from public.proc_quote_lines where id=(x->>'quote_line_id')::uuid;
    select * into q from public.proc_quotes where id=ql.quote_id;
    select * into r from public.proc_requirements where id=ri.requirement_id for update;
    qty_v:=(x->>'qty')::numeric;

    select v.landed_unit_cost,v.effective_unit_price,v.freight_unit_cost
    into landed_v,effective_v,freight_unit_v
    from public.proc_v_quote_comparison v where v.quote_line_id=ql.id;

    select min(v.landed_unit_cost) into best_landed
    from public.proc_v_quote_comparison v where v.rfq_item_id=ri.id;

    reason_v:=nullif(trim(coalesce(x->>'override_reason','')),'');
    method_v:=case when landed_v<=best_landed then 'recommended' else 'override' end;

    supplier_key:=q.supplier_id::text;
    if po_map ? supplier_key then
      v_po_id:=(po_map->>supplier_key)::uuid;
    else
      v_po_id:=gen_random_uuid();
      po_number:='PO-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS')||'-'||substr(replace(q.supplier_id::text,'-',''),1,4);
      insert into public.proc_purchase_orders(
        id,po_no,supplier_id,status,po_date,created_by,freight_total
      )
      values(v_po_id,po_number,q.supplier_id,'pending_approval',current_date,caller,q.freight_total);
      po_map:=po_map||jsonb_build_object(supplier_key,v_po_id::text);
    end if;

    insert into public.proc_po_lines(
      po_id,requirement_id,item_id,qty,unit_price,discount_percent,tax_percent,
      source_quote_line_id,landed_unit_cost
    )
    values(
      v_po_id,ri.requirement_id,r.item_id,qty_v,ql.unit_price,ql.discount_percent,ql.tax_percent,
      ql.id,landed_v
    );

    insert into public.proc_awards(
      rfq_item_id,supplier_id,quote_line_id,awarded_qty,unit_price,
      discount_percent,tax_percent,effective_unit_cost,landed_unit_cost,
      award_method,override_reason,awarded_by
    )
    values(
      ri.id,q.supplier_id,ql.id,qty_v,ql.unit_price,ql.discount_percent,ql.tax_percent,
      effective_v,landed_v,method_v,reason_v,caller
    );

    update public.proc_quotes set status='selected' where id=q.id;

    update public.proc_requirements
    set adjusted_qty=greatest(adjusted_qty,ordered_qty+qty_v),
        ordered_qty=ordered_qty+qty_v,
        status=case when ordered_qty+qty_v>=greatest(adjusted_qty,ordered_qty+qty_v) then 'ordered' else 'partially_ordered' end,
        updated_at=now()
    where id=r.id;
  end loop;

  for map_rec in
    select key supplier_id_text,value #>> '{}' po_id_text from jsonb_each(po_map)
  loop
    v_po_id:=map_rec.po_id_text::uuid;
    select
      coalesce(sum(round(pl.qty*pl.unit_price*(1-pl.discount_percent/100.0),2)),0),
      coalesce(sum(round((pl.qty*pl.unit_price*(1-pl.discount_percent/100.0))*(pl.tax_percent/100.0),2)),0),
      coalesce(sum(pl.line_total),0)
    into subtotal_v,tax_v,goods_total_v
    from public.proc_po_lines pl where pl.po_id=v_po_id;

    select freight_total into freight_v from public.proc_purchase_orders where id=v_po_id;

    update public.proc_purchase_orders
    set subtotal=subtotal_v,tax_total=tax_v,total=goods_total_v+coalesce(freight_v,0),updated_at=now()
    where id=v_po_id
    returning po_no into po_number;

    result:=result||jsonb_build_array(jsonb_build_object(
      'po_id',v_po_id,'po_no',po_number,'supplier_id',map_rec.supplier_id_text::uuid,
      'subtotal',subtotal_v,'tax_total',tax_v,'freight_total',coalesce(freight_v,0),
      'total',goods_total_v+coalesce(freight_v,0)
    ));
  end loop;

  update public.proc_rfqs set status='awarded',updated_at=now() where id=p_rfq_id;
  return result;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_finalize_award_plan_v2(p_rfq_id uuid, p_allocations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid(); caller_role text;
  preferred integer; ri record; eligible integer; required_q integer; received integer;
  exception_reason text; x jsonb; qid uuid; q_valid date; result jsonb;
begin
  perform private.proc_assert_permission('procurement.orders.create');
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;

  preferred:=1;
  for ri in
    select i.id rfq_item_id,r.item_id
    from public.proc_rfq_items i join public.proc_requirements r on r.id=i.requirement_id
    where i.rfq_id=p_rfq_id and i.selected_for_po=true
  loop
    select count(*) into eligible
    from public.proc_rfq_suppliers rs
    where rs.rfq_id=p_rfq_id
      and rs.status<>'declined'
      and private.proc_supplier_covers_item_v1(rs.supplier_id,ri.item_id);
    required_q:=least(preferred,greatest(eligible,1));

    select count(distinct q.supplier_id) into received
    from public.proc_quote_lines ql
    join public.proc_quotes q on q.id=ql.quote_id
    where q.rfq_id=p_rfq_id and ql.rfq_item_id=ri.rfq_item_id
      and q.status in ('received','reviewed','selected')
      and (q.valid_until is null or q.valid_until>=current_date);

    if received<1 then
      raise exception 'A valid supplier quotation is required for item %.', ri.rfq_item_id;
    end if;
  end loop;

  for x in select * from jsonb_array_elements(p_allocations) loop
    select q.id,q.valid_until into qid,q_valid
    from public.proc_quote_lines ql join public.proc_quotes q on q.id=ql.quote_id
    where ql.id=(x->>'quote_line_id')::uuid and q.rfq_id=p_rfq_id;
    if qid is null then raise exception 'Award quote line does not belong to this RFQ'; end if;
    if q_valid is not null and q_valid<current_date then raise exception 'Expired quotation cannot be awarded'; end if;
  end loop;

  result:=public.proc_finalize_award_plan_v1(p_rfq_id,p_allocations);
  return result;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_import_company_items_v1(p_rows jsonb, p_company_id uuid DEFAULT NULL::uuid, p_add_to_company_list boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  company_rec public.proc_companies;
  x jsonb;
  idx integer:=0;
  code_v text;
  description_v text;
  brand_v text;
  category_v text;
  main_group_v text;
  subgroup_v text;
  size_v text;
  uom_v text;
  movement_v text;
  max_v numeric;
  reorder_v numeric;
  existing_id uuid;
  created_id uuid;
  created_count integer:=0;
  existing_count integer:=0;
  linked_count integer:=0;
  results jsonb:='[]'::jsonb;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role
  from public.proc_profiles
  where id=caller and active=true;

  if caller_role is null or caller_role not in ('admin','procurement') then
    raise exception 'Admin or Procurement access required';
  end if;

  if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)=0 then
    raise exception 'Select at least one extracted item';
  end if;
  if jsonb_array_length(p_rows)>1000 then
    raise exception 'Import no more than 1000 items at once';
  end if;

  if p_company_id is not null then
    select * into company_rec
    from public.proc_companies
    where id=p_company_id and active=true;
    if company_rec.id is null then raise exception 'Company not found'; end if;
  end if;

  if p_add_to_company_list and caller_role<>'admin' then
    raise exception 'Only Admin can add imported items directly to a Company List';
  end if;

  for x in select value from jsonb_array_elements(p_rows)
  loop
    idx:=idx+1;
    if coalesce((x->>'selected')::boolean,true)=false then
      continue;
    end if;

    description_v:=nullif(trim(coalesce(x->>'description','')),'');
    if description_v is null then
      raise exception 'Item name is required for selected row %',idx;
    end if;

    brand_v:=nullif(trim(coalesce(x->>'brand','')),'');
    category_v:=coalesce(nullif(trim(coalesce(x->>'category','')),''),'GENERAL');
    main_group_v:=nullif(trim(coalesce(x->>'main_group','')),'');
    subgroup_v:=nullif(trim(coalesce(x->>'subgroup','')),'');
    size_v:=nullif(trim(coalesce(x->>'size','')),'');
    uom_v:=coalesce(nullif(upper(trim(coalesce(x->>'uom',''))),''),'PCS');
    movement_v:=coalesce(nullif(upper(trim(coalesce(x->>'movement',''))),''),'NORMAL');
    if movement_v not in ('FAST','NORMAL','SLOW') then
      raise exception 'Invalid movement for row %',idx;
    end if;

    max_v:=coalesce((nullif(x->>'max_stock',''))::numeric,0);
    reorder_v:=coalesce((nullif(x->>'reorder_level',''))::numeric,0);
    if max_v<0 or reorder_v<0 then
      raise exception 'Stock levels cannot be negative for row %',idx;
    end if;

    code_v:=upper(regexp_replace(trim(coalesce(x->>'item_code','')),'[^A-Za-z0-9._/-]+','-','g'));
    code_v:=trim(both '-' from code_v);

    existing_id:=null;

    if code_v<>'' then
      select id into existing_id
      from public.proc_items
      where lower(item_code)=lower(code_v)
      limit 1;
    end if;

    if existing_id is null then
      select id into existing_id
      from public.proc_items
      where active=true
        and lower(regexp_replace(trim(description),'\s+',' ','g'))=
            lower(regexp_replace(description_v,'\s+',' ','g'))
        and lower(coalesce(trim(size),''))=lower(coalesce(size_v,''))
        and lower(coalesce(trim(brand),''))=lower(coalesce(brand_v,''))
      order by created_at
      limit 1;
    end if;

    if existing_id is not null then
      existing_count:=existing_count+1;
      if p_add_to_company_list and company_rec.id is not null then
        insert into public.proc_company_list_items(
          company_id,item_id,target_stock,reorder_level,active,created_by
        )
        values(company_rec.id,existing_id,max_v,nullif(reorder_v,0),true,caller)
        on conflict(company_id,item_id) do update
          set active=true,updated_at=now();
        linked_count:=linked_count+1;
      end if;

      results:=results||jsonb_build_array(jsonb_build_object(
        'row_index',idx,'status','existing','item_id',existing_id
      ));
      continue;
    end if;

    if code_v='' then
      code_v:='CPL-'||
        case when company_rec.id is not null
          then upper(substr(regexp_replace(company_rec.company_code,'[^A-Za-z0-9]+','','g'),1,10))||'-'
          else ''
        end||
        upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
    elsif exists(select 1 from public.proc_items where lower(item_code)=lower(code_v)) then
      code_v:=code_v||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));
    end if;

    insert into public.proc_items(
      item_code,category,description,brand,main_group,subgroup,size,uom,
      max_stock,movement,reorder_level,remarks,source,active
    )
    values(
      code_v,category_v,description_v,brand_v,main_group_v,subgroup_v,size_v,uom_v,
      max_v,movement_v,reorder_v,
      case when company_rec.id is not null
        then 'Imported from '||company_rec.name||' price list'
        else 'Imported from company price list'
      end,
      'COMPANY PRICE LIST IMPORT',
      true
    )
    returning id into created_id;

    created_count:=created_count+1;

    if p_add_to_company_list and company_rec.id is not null then
      insert into public.proc_company_list_items(
        company_id,item_id,target_stock,reorder_level,active,created_by
      )
      values(company_rec.id,created_id,max_v,nullif(reorder_v,0),true,caller)
      on conflict(company_id,item_id) do update
        set active=true,updated_at=now();
      linked_count:=linked_count+1;
    end if;

    results:=results||jsonb_build_array(jsonb_build_object(
      'row_index',idx,'status','created','item_id',created_id,'item_code',code_v
    ));
  end loop;

  return jsonb_build_object(
    'created',created_count,
    'existing',existing_count,
    'company_list_linked',linked_count,
    'results',results
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_mark_item_urgent_v1(p_item_id uuid, p_required_qty numeric DEFAULT NULL::numeric, p_reason text DEFAULT 'manual_urgent'::text, p_current_stock numeric DEFAULT NULL::numeric, p_customer_paid boolean DEFAULT false, p_customer_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_image_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  loc uuid;
  it public.proc_items;
  r public.proc_requirements;
  needed numeric;
  v_priority text;
  additive boolean;
  req_no text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler','stock_checker') then raise exception 'Not authorized'; end if;
  if p_reason not in ('zero_stock','fast_mover','bulk_sale','customer_paid','customer_request','manual_urgent') then raise exception 'Invalid urgency reason'; end if;
  if p_current_stock is not null and p_current_stock<0 then raise exception 'Current stock cannot be negative'; end if;
  if p_required_qty is not null and p_required_qty<=0 then raise exception 'Required quantity must be greater than zero'; end if;

  select * into it from public.proc_items where id=p_item_id and active=true;
  if it.id is null then raise exception 'Item not found'; end if;
  loc:=private.proc_default_location_id();
  if loc is null then raise exception 'Default stock location is not configured'; end if;

  needed:=coalesce(
    p_required_qty,
    greatest(it.max_stock-coalesce(p_current_stock,(select qty from public.proc_stock_balances where item_id=it.id and location_id=loc),0),0)
  );
  if needed<=0 then needed:=greatest(it.reorder_level,1); end if;

  additive:=p_reason in ('customer_paid','customer_request');
  v_priority:=case
    when p_customer_paid or p_reason in ('zero_stock','bulk_sale','customer_paid','manual_urgent') then 'urgent'
    when it.movement='FAST' or p_reason='fast_mover' then 'high'
    else 'high'
  end;

  select * into r
  from public.proc_requirements
  where item_id=it.id and location_id=loc and status not in ('received','closed','cancelled')
  order by created_at desc
  limit 1
  for update;

  if r.id is null then
    req_no:='REQ-U-'||to_char(clock_timestamp(),'YYMMDDHH24MISSMS');
    insert into public.proc_requirements(
      requirement_no,item_id,location_id,required_qty,adjusted_qty,status,priority,notes,
      approval_status,selected_for_order,created_by,urgency_reason,customer_paid,
      customer_reference,request_image_path,source_type
    )
    values(
      req_no,it.id,loc,needed,needed,'open',v_priority,nullif(trim(coalesce(p_notes,'')),''),
      'pending_review',false,caller,p_reason,p_customer_paid,
      nullif(trim(coalesce(p_customer_reference,'')),''),p_image_path,'urgent_action'
    )
    returning * into r;
  else
    update public.proc_requirements
    set
      required_qty=case when additive then required_qty+needed else greatest(required_qty,needed) end,
      adjusted_qty=greatest(
        ordered_qty,
        case when additive then adjusted_qty+needed else greatest(adjusted_qty,needed) end
      ),
      priority=case when priority='urgent' or v_priority='urgent' then 'urgent' else 'high' end,
      urgency_reason=p_reason,
      customer_paid=customer_paid or p_customer_paid,
      customer_reference=coalesce(nullif(trim(coalesce(p_customer_reference,'')),''),customer_reference),
      request_image_path=coalesce(p_image_path,request_image_path),
      notes=coalesce(nullif(trim(coalesce(p_notes,'')),''),notes),
      approval_status=case when ordered_qty=0 then 'pending_review' else approval_status end,
      selected_for_order=case when ordered_qty=0 then false else selected_for_order end,
      source_type='urgent_action',
      updated_at=now()
    where id=r.id
    returning * into r;
  end if;

  return jsonb_build_object(
    'requirement_id',r.id,'requirement_no',r.requirement_no,
    'priority',r.priority,'required_qty',r.adjusted_qty
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_mark_own_invite_accepted()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
begin
  if caller is null then return; end if;

  update public.proc_user_invites
  set status='accepted',accepted_at=coalesce(accepted_at,now()),updated_at=now()
  where invited_user_id=caller and status='pending';
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_mark_po_sent_v2(p_po_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

begin
  update public.proc_purchase_orders set status='sent' where id=p_po_id and status='approved';
  if not found then raise exception 'Purchase order must be approved first'; end if;
  return 'sent';
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_mark_rfq_supplier_sent_v1(p_rfq_id uuid, p_supplier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare caller uuid:=auth.uid(); caller_role text; remaining integer; header_status text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;

  update public.proc_rfq_suppliers
  set status='sent',sent_at=now(),sent_by=caller
  where rfq_id=p_rfq_id and supplier_id=p_supplier_id and status in ('pending','prepared','sent');
  if not found then raise exception 'Supplier request is not pending transmission'; end if;

  select count(*) into remaining from public.proc_rfq_suppliers
  where rfq_id=p_rfq_id and status in ('pending','prepared');

  select case
    when exists(select 1 from public.proc_rfq_suppliers where rfq_id=p_rfq_id and status='quoted') then 'partially_quoted'
    else 'sent'
  end into header_status;
  update public.proc_rfqs set status=header_status,updated_at=now() where id=p_rfq_id and status not in ('awarded','closed','cancelled');

  if remaining=0 then
    perform private.proc_upsert_automation_job_v1('rfq_send','rfq',p_rfq_id,'completed','{}'::jsonb,null);
  end if;
  return jsonb_build_object('status','sent','remaining_unsent',remaining);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_match_company_price_list(p_price_list_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  pl public.proc_company_price_lists;
  line_rec record;
  candidate uuid;
  candidate_count integer;
  matched integer:=0;
  possible integer:=0;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','document_assistant') then raise exception 'Not authorized'; end if;

  select * into pl from public.proc_company_price_lists where id=p_price_list_id;
  if pl.id is null then raise exception 'Price list not found'; end if;
  if pl.list_type<>'mrp' and caller_role<>'admin' then raise exception 'Cost-list matching is Admin only'; end if;

  for line_rec in
    select *
    from public.proc_company_price_list_lines
    where price_list_id=p_price_list_id
      and match_status not in ('ignored','duplicate')
    order by created_at,id
  loop
    candidate:=null;
    candidate_count:=0;

    if nullif(trim(coalesce(line_rec.external_code,'')),'') is not null then
      select count(*)
      into candidate_count
      from public.proc_items
      where active=true
        and lower(trim(item_code))=lower(trim(line_rec.external_code));

      if candidate_count=1 then
        select id into candidate
        from public.proc_items
        where active=true
          and lower(trim(item_code))=lower(trim(line_rec.external_code))
        limit 1;

        update public.proc_company_price_list_lines
        set item_id=candidate,match_status='matched'
        where id=line_rec.id;
        matched:=matched+1;
        continue;
      elsif candidate_count>1 then
        update public.proc_company_price_list_lines
        set item_id=null,match_status='possible_match'
        where id=line_rec.id;
        possible:=possible+1;
        continue;
      end if;
    end if;

    select count(*)
    into candidate_count
    from public.proc_items
    where active=true
      and lower(regexp_replace(trim(description),'\s+',' ','g')) =
          lower(regexp_replace(trim(line_rec.description),'\s+',' ','g'))
      and lower(coalesce(trim(size),''))=lower(coalesce(trim(line_rec.size),''));

    if candidate_count=1 then
      select id into candidate
      from public.proc_items
      where active=true
        and lower(regexp_replace(trim(description),'\s+',' ','g')) =
            lower(regexp_replace(trim(line_rec.description),'\s+',' ','g'))
        and lower(coalesce(trim(size),''))=lower(coalesce(trim(line_rec.size),''))
      limit 1;

      update public.proc_company_price_list_lines
      set item_id=candidate,match_status='matched'
      where id=line_rec.id;
      matched:=matched+1;
    elsif candidate_count>1 then
      update public.proc_company_price_list_lines
      set item_id=null,match_status='possible_match'
      where id=line_rec.id;
      possible:=possible+1;
    else
      update public.proc_company_price_list_lines
      set item_id=null,match_status='new_item'
      where id=line_rec.id;
    end if;
  end loop;

  return jsonb_build_object('matched',matched,'possible_matches',possible);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_populate_company_list_from_price_list(p_price_list_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  pl public.proc_company_price_lists;
  co public.proc_companies;
  line_rec record;
  matched integer:=0;
  added integer:=0;
  skipped_missing integer:=0;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role
  from public.proc_profiles
  where id=caller and active=true;
  if caller_role<>'admin' then raise exception 'Admin access required'; end if;

  select * into pl
  from public.proc_company_price_lists
  where id=p_price_list_id;

  if pl.id is null then raise exception 'Price list not found'; end if;
  if pl.list_type<>'mrp' then raise exception 'Only MRP price lists can populate Company Lists'; end if;
  if pl.status<>'approved' then raise exception 'Approve the MRP price list before populating the Company List'; end if;

  select * into co
  from public.proc_companies
  where id=pl.company_id;

  if co.id is null then raise exception 'Company not found'; end if;

  perform public.proc_match_company_price_list(p_price_list_id);

  for line_rec in
    select *
    from public.proc_company_price_list_lines
    where price_list_id=p_price_list_id
      and match_status not in ('ignored','duplicate')
      and nullif(trim(description),'') is not null
    order by created_at,id
  loop
    if line_rec.item_id is null
       or not exists(select 1 from public.proc_items where id=line_rec.item_id and active=true) then
      skipped_missing:=skipped_missing+1;
      continue;
    end if;

    matched:=matched+1;

    insert into public.proc_company_list_items(
      company_id,item_id,target_stock,reorder_level,active,created_by
    )
    values(co.id,line_rec.item_id,0,null,true,caller)
    on conflict(company_id,item_id) do update
      set active=true,updated_at=now();

    added:=added+1;
  end loop;

  return jsonb_build_object(
    'matched_existing',matched,
    'company_list_rows_processed',added,
    'skipped_missing_items',skipped_missing
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_quick_add_item_v1(p_item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare i public.proc_items; description_v text; category_v text; size_v text; brand_v text; uom_v text; movement_v text; max_v numeric; identity_v text;colour_v text;variation_v text;
begin
 if auth.uid() is null or not private.proc_has_permission('items.edit') then raise exception 'Item editing permission required' using errcode='42501'; end if;
 description_v:=trim(coalesce(p_item->>'description',''));
 category_v:=trim(coalesce(p_item->>'category',''));
 uom_v:=upper(trim(coalesce(p_item->>'uom','PCS')));
 size_v:=trim(coalesce(p_item->>'size',''));brand_v:=trim(coalesce(p_item->>'brand',''));
 colour_v:=trim(coalesce(p_item->>'colour',''));variation_v:=trim(coalesce(p_item->>'variation',''));
 movement_v:=upper(coalesce(nullif(p_item->>'movement',''),'NORMAL'));
 max_v:=coalesce(nullif(p_item->>'max_stock','')::numeric,0);
 if description_v='' or category_v='' or uom_v='' then raise exception 'Item name, category and UOM are required'; end if;
 if movement_v not in ('FAST','NORMAL','SLOW') or max_v<0 or max_v::text in ('NaN','Infinity','-Infinity') then raise exception 'Invalid movement or maximum stock'; end if;
 identity_v:=lower(concat_ws('|',description_v,size_v,brand_v,category_v,uom_v,colour_v,variation_v));
 perform pg_advisory_xact_lock(hashtextextended(identity_v,0));
 select * into i from public.proc_items where lower(trim(description))=lower(description_v) and lower(trim(coalesce(size,'')))=lower(size_v) and lower(trim(coalesce(brand,'')))=lower(brand_v) and lower(trim(category))=lower(category_v) and upper(trim(uom))=uom_v and coalesce(colour,'')=colour_v and coalesce(variation,'')=variation_v order by active desc,created_at limit 1;
 if i.id is not null then
  if not i.active then raise exception 'This item already exists but is disabled. Enable it in Item Master.'; end if;
  return jsonb_build_object('existing',true,'item',to_jsonb(i));
 end if;
 insert into public.proc_items(item_code,description,category,size,brand,uom,main_group,subgroup,movement,max_stock,source,colour,variation)
 values('QA-'||upper(replace(gen_random_uuid()::text,'-','')),description_v,category_v,nullif(size_v,''),nullif(brand_v,''),uom_v,nullif(trim(p_item->>'main_group'),''),nullif(trim(p_item->>'subgroup'),''),movement_v,max_v,'QUICK ADD',nullif(colour_v,''),nullif(variation_v,'')) returning * into i;
 return jsonb_build_object('existing',false,'item',to_jsonb(i));
end $function$

CREATE OR REPLACE FUNCTION public.proc_quote_snapshot_v1(p_rfq_id uuid, p_supplier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare payload jsonb;
begin
 if auth.uid() is null or not (private.proc_has_permission('procurement.rfq.view') or private.proc_has_permission('procurement.rfq.manage')) then
  raise exception 'Quotation access denied' using errcode='42501';
 end if;
 select jsonb_build_object('quote',to_jsonb(q),'lines',coalesce((select jsonb_agg(to_jsonb(l) order by l.id) from public.proc_quote_lines l where l.quote_id=q.id),'[]'::jsonb)) into payload
 from public.proc_quotes q where q.rfq_id=p_rfq_id and q.supplier_id=p_supplier_id;
 payload:=coalesce(payload,jsonb_build_object('quote',null,'lines','[]'::jsonb));
 return payload||jsonb_build_object('revision',md5(payload::text));
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_receive_po_v2(p_po_id uuid, p_lines jsonb, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  po public.proc_purchase_orders;
  gid uuid;
  gno text;
  loc uuid;
  x jsonb;
  pl public.proc_po_lines;
  rec numeric;
  acc numeric;
  rej numeric;
  previously_accepted numeric;
  posted integer;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','receiver') then raise exception 'Not authorized'; end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'Receiving lines are required'; end if;

  select * into po from public.proc_purchase_orders where id=p_po_id for update;
  if po.id is null then raise exception 'Purchase order not found'; end if;
  if po.status not in ('sent','partially_received') then raise exception 'Only sent purchase orders can be received'; end if;

  loc:=private.proc_default_location_id();
  if loc is null then raise exception 'Default stock location is not configured'; end if;

  gno:='GRN-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');

  insert into public.proc_grns(grn_no,po_id,supplier_id,location_id,status,received_by,notes)
  values(gno,po.id,po.supplier_id,loc,'draft',caller,p_notes)
  returning id into gid; select g.grn_no into gno from public.proc_grns g where g.id=gid;

  for x in select * from jsonb_array_elements(p_lines)
  loop
    select * into pl
    from public.proc_po_lines
    where id=(x->>'po_line_id')::uuid and po_id=po.id;

    if pl.id is null then raise exception 'Receiving line is not part of the selected PO'; end if;

    rec:=coalesce((x->>'received_qty')::numeric,0);
    acc:=coalesce((x->>'accepted_qty')::numeric,0);
    rej:=coalesce((x->>'rejected_qty')::numeric,0);

    if rec<0 or acc<0 or rej<0 then raise exception 'Receiving quantities cannot be negative'; end if;
    if acc+rej>rec then raise exception 'Accepted plus rejected quantity cannot exceed received quantity'; end if;

    select coalesce(sum(gl.accepted_qty),0)
    into previously_accepted
    from public.proc_grn_lines gl
    join public.proc_grns g on g.id=gl.grn_id
    where gl.po_line_id=pl.id
      and g.status='posted';

    if previously_accepted+acc>pl.qty then
      raise exception 'Accepted quantity would exceed the outstanding ordered quantity';
    end if;

    insert into public.proc_grn_lines(
      grn_id,po_line_id,item_id,ordered_qty,received_qty,
      accepted_qty,rejected_qty,rejection_reason
    )
    values(
      gid,pl.id,pl.item_id,pl.qty,rec,acc,rej,
      nullif(x->>'rejection_reason','')
    );
  end loop;

  posted:=private.proc_post_grn_impl(gid);
  return jsonb_build_object('grn_id',gid,'grn_no',gno,'lines_posted',posted);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_receive_po_v3(p_po_id uuid, p_receipt_key uuid, p_lines jsonb, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid(); caller_role text; po public.proc_purchase_orders; existing public.proc_grns;
  gid uuid; gno text; loc uuid; x jsonb; pl public.proc_po_lines;
  rec numeric; acc numeric; rej numeric; previously_accepted numeric; posted integer; reject_reason text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','receiver') then raise exception 'Not authorized'; end if;
  if not private.proc_has_permission('receiving.manage') then raise exception 'Permission denied: receiving.manage' using errcode='42501'; end if;
  if p_receipt_key is null then raise exception 'Receipt key is required'; end if;

  -- Lock before checking the key so concurrent identical requests can replay safely.
  select * into po from public.proc_purchase_orders where id=p_po_id for update;
  if po.id is null then raise exception 'Purchase order not found'; end if;
  select * into existing from public.proc_grns where receipt_key=p_receipt_key;
  if existing.id is not null then
    if existing.po_id<>p_po_id then raise exception 'Receipt key already belongs to another PO'; end if;
    return jsonb_build_object('grn_id',existing.id,'grn_no',existing.grn_no,'replayed',true);
  end if;

  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'Receiving lines are required'; end if;
  if (select count(*)<>count(distinct entry.value->>'po_line_id') from jsonb_array_elements(p_lines) as entry(value)) then raise exception 'Each purchase order line may appear only once per receipt'; end if;
  if po.status not in ('sent','partially_received') then raise exception 'Only sent purchase orders can be received'; end if;

  loc:=private.proc_default_location_id();
  if loc is null then raise exception 'Default stock location is not configured'; end if;
  gno:='GRN-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');
  insert into public.proc_grns(grn_no,po_id,supplier_id,location_id,status,received_by,notes,receipt_key)
  values(gno,po.id,po.supplier_id,loc,'draft',caller,p_notes,p_receipt_key) returning id into gid; select g.grn_no into gno from public.proc_grns g where g.id=gid;

  for x in select * from jsonb_array_elements(p_lines) loop
    select * into pl from public.proc_po_lines where id=(x->>'po_line_id')::uuid and po_id=po.id;
    if pl.id is null then raise exception 'Receiving line is not part of the selected PO'; end if;

    rec:=coalesce((x->>'received_qty')::numeric,0);
    acc:=coalesce((x->>'accepted_qty')::numeric,0);
    rej:=coalesce((x->>'rejected_qty')::numeric,0);
    reject_reason:=nullif(trim(coalesce(x->>'rejection_reason','')),'');
    if rec<0 or acc<0 or rej<0 then raise exception 'Receiving quantities cannot be negative'; end if;
    if acc+rej>rec then raise exception 'Accepted plus rejected quantity cannot exceed received quantity'; end if;
    if rej>0 and reject_reason is null then raise exception 'A rejection reason is required when rejected quantity is greater than zero'; end if;

    select coalesce(sum(gl.accepted_qty),0) into previously_accepted
    from public.proc_grn_lines gl join public.proc_grns g on g.id=gl.grn_id
    where gl.po_line_id=pl.id and g.status='posted';
    if previously_accepted+acc>pl.qty-pl.cancelled_qty then raise exception 'Accepted quantity would exceed the outstanding ordered quantity'; end if;

    insert into public.proc_grn_lines(grn_id,po_line_id,item_id,ordered_qty,received_qty,accepted_qty,rejected_qty,rejection_reason)
    values(gid,pl.id,pl.item_id,pl.qty,rec,acc,rej,reject_reason);
  end loop;

  posted:=private.proc_post_grn_impl(gid);
  return jsonb_build_object('grn_id',gid,'grn_no',gno,'lines_posted',posted,'replayed',false);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_resolve_invoice_variance_v1(p_invoice_id uuid, p_action text, p_notes text DEFAULT NULL::text, p_credit_note_no text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  inv public.proc_supplier_invoices;
  next_status text;
  next_resolution text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;

  select * into inv from public.proc_supplier_invoices where id=p_invoice_id for update;
  if inv.id is null then raise exception 'Supplier invoice not found'; end if;
  if inv.status not in ('variance','approved','rejected') then
    raise exception 'Only variance invoices can use the exception workflow';
  end if;

  if p_action not in (
    'approve_difference','request_revised_invoice','request_credit_note',
    'credit_note_received','dispute','reject','resolve'
  ) then raise exception 'Invalid invoice variance action'; end if;

  if p_action in ('approve_difference','reject','resolve') and caller_role<>'admin' then
    raise exception 'Only an Admin can approve, reject or close an invoice variance';
  end if;

  if p_action='credit_note_received' and nullif(trim(coalesce(p_credit_note_no,'')),'') is null then
    raise exception 'Credit note number is required';
  end if;

  next_status:=case
    when p_action in ('approve_difference','credit_note_received','resolve') then 'approved'
    when p_action='reject' then 'rejected'
    else 'variance'
  end;

  next_resolution:=case p_action
    when 'request_revised_invoice' then 'pending_supplier'
    when 'request_credit_note' then 'pending_credit'
    when 'dispute' then 'disputed'
    when 'reject' then 'rejected'
    else 'resolved'
  end;

  update public.proc_supplier_invoices
  set status=next_status,
      variance_resolution_status=next_resolution,
      variance_resolution_action=p_action,
      variance_resolution_notes=nullif(trim(coalesce(p_notes,'')),''),
      variance_credit_note_no=case
        when p_action='credit_note_received' then nullif(trim(coalesce(p_credit_note_no,'')),'')
        else variance_credit_note_no
      end,
      variance_resolved_by=case when next_resolution in ('resolved','rejected') then caller else null end,
      variance_resolved_at=case when next_resolution in ('resolved','rejected') then now() else null end
  where id=inv.id;

  return jsonb_build_object(
    'invoice_id',inv.id,
    'status',next_status,
    'resolution_status',next_resolution,
    'action',p_action
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_resolve_rejection_case_v1(p_case_id uuid, p_action text, p_notes text DEFAULT NULL::text, p_reference_no text DEFAULT NULL::text, p_due_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  c public.proc_rejection_cases;
  g public.proc_grns;
  new_balance numeric;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','receiver') then raise exception 'Not authorized'; end if;

  if not private.proc_has_permission('receiving.manage') then raise exception 'Permission denied: receiving.manage' using errcode='42501'; end if;

  select * into c from public.proc_rejection_cases where id=p_case_id for update;
  if c.id is null then raise exception 'Rejected-goods case not found'; end if;
  if c.status='resolved' then raise exception 'Rejected-goods case is already resolved'; end if;

  if p_action not in (
    'returned_to_supplier','replacement_requested','credit_note_requested',
    'replacement_received','credit_note_received','accept_loss','close_other'
  ) then raise exception 'Invalid rejected-goods action'; end if;

  if p_action='returned_to_supplier' then
    update public.proc_rejection_cases
    set status='returned',notes=coalesce(nullif(trim(coalesce(p_notes,'')),''),notes),
        reference_no=coalesce(nullif(trim(coalesce(p_reference_no,'')),''),reference_no),
        due_date=p_due_date,updated_at=now()
    where id=c.id;
  elsif p_action='replacement_requested' then
    update public.proc_rejection_cases
    set status='replacement_due',notes=coalesce(nullif(trim(coalesce(p_notes,'')),''),notes),
        reference_no=coalesce(nullif(trim(coalesce(p_reference_no,'')),''),reference_no),
        due_date=p_due_date,updated_at=now()
    where id=c.id;
  elsif p_action='credit_note_requested' then
    update public.proc_rejection_cases
    set status='credit_note_due',notes=coalesce(nullif(trim(coalesce(p_notes,'')),''),notes),
        reference_no=coalesce(nullif(trim(coalesce(p_reference_no,'')),''),reference_no),
        due_date=p_due_date,updated_at=now()
    where id=c.id;
  else
    if p_action in ('credit_note_received') and nullif(trim(coalesce(p_reference_no,'')),'') is null then
      raise exception 'Credit note/reference number is required';
    end if;

    if p_action='replacement_received' then
      -- Normal receipt posting updates stock, requirement and PO balances together.
      perform public.proc_receive_po_v3(c.po_id,c.id,
        jsonb_build_array(jsonb_build_object(
          'po_line_id',(select po_line_id from public.proc_grn_lines where id=c.grn_line_id),
          'received_qty',c.rejected_qty,'accepted_qty',c.rejected_qty,'rejected_qty',0)),
        'Replacement for rejection case '||c.id::text||coalesce(' / '||p_reference_no,''));

    end if;

    update public.proc_rejection_cases
    set status='resolved',
        resolution_type=case p_action
          when 'replacement_received' then 'replacement'
          when 'credit_note_received' then 'credit_note'
          when 'accept_loss' then 'accepted_loss'
          else 'other'
        end,
        reference_no=coalesce(nullif(trim(coalesce(p_reference_no,'')),''),reference_no),
        notes=coalesce(nullif(trim(coalesce(p_notes,'')),''),notes),
        resolved_by=caller,resolved_at=now(),updated_at=now()
    where id=c.id;
  end if;

  return (
    select jsonb_build_object(
      'case_id',rc.id,'status',rc.status,'resolution_type',rc.resolution_type,
      'reference_no',rc.reference_no
    )
    from public.proc_rejection_cases rc where rc.id=c.id
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_retry_automation_job_v1(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare caller uuid:=auth.uid(); caller_role text; j public.proc_automation_jobs; result jsonb;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;

  select * into j from public.proc_automation_jobs where id=p_job_id for update;
  if j.id is null then raise exception 'Automation job not found'; end if;

  update public.proc_automation_jobs set attempts=attempts+1,status='pending',last_error=null,updated_at=now() where id=j.id;
  begin
    if j.job_type='stock_continue' then
      result:=public.proc_straight_through_stock_count_v2(j.entity_id);
    elsif j.job_type='award_retry' then
      result:=public.proc_try_auto_award_v2(j.entity_id);
    else
      update public.proc_automation_jobs set status='needs_action',last_error='Confirm supplier transmission manually.',updated_at=now() where id=j.id;
      return jsonb_build_object('status','needs_action','reason','manual_send_confirmation');
    end if;
    return result;
  exception when others then
    update public.proc_automation_jobs set status='failed',last_error=sqlerrm,next_attempt_at=now()+interval '15 minutes',updated_at=now() where id=j.id;
    return jsonb_build_object('status','failed','error',sqlerrm);
  end;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_review_requirements(p_requirement_ids uuid[], p_action text, p_selected boolean DEFAULT true, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  n integer;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;
  if coalesce(array_length(p_requirement_ids,1),0)=0 then raise exception 'Select at least one requirement'; end if;
  if p_action not in ('approve','hold','reject') then raise exception 'Invalid review action'; end if;

  update public.proc_requirements
  set approval_status=case p_action when 'approve' then 'approved' when 'hold' then 'held' else 'rejected' end,
      selected_for_order=case when p_action='approve' then coalesce(p_selected,true) else false end,
      approved_by=case when p_action='approve' then caller else null end,
      approved_at=case when p_action='approve' then now() else null end,
      hold_reason=case when p_action in ('hold','reject') then nullif(trim(coalesce(p_reason,'')),'') else null end,
      status=case when p_action='reject' and ordered_qty=0 and received_qty=0 then 'cancelled' else status end,
      updated_at=now()
  where id=any(p_requirement_ids)
    and status not in ('closed','cancelled','received');

  get diagnostics n=row_count;
  return n;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_save_quote_guarded_v1(p_rfq_id uuid, p_supplier_id uuid, p_expected_revision text, p_quote_ref text, p_lines jsonb, p_additional_sizes jsonb DEFAULT '[]'::jsonb, p_valid_until date DEFAULT NULL::date, p_attachment_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_freight_total numeric DEFAULT 0, p_minimum_order_value numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare snapshot jsonb;
begin
 if auth.uid() is null or not private.proc_has_permission('procurement.rfq.manage') then
  raise exception 'Quotation edit denied' using errcode='42501';
 end if;
 -- Serializes with v3, additional-size saves and award creation, including first saves.
 perform 1 from public.proc_rfqs where id=p_rfq_id for update;
 if not found then raise exception 'RFQ not found'; end if;
 snapshot:=public.proc_quote_snapshot_v1(p_rfq_id,p_supplier_id);
 if p_expected_revision is null or p_expected_revision is distinct from snapshot->>'revision' then
  raise exception 'Saved supplier quotation changed. Your draft is preserved; reload and review before saving.' using errcode='40001';
 end if;
 if jsonb_typeof(p_additional_sizes)<>'array' then raise exception 'Additional sizes must be an array'; end if;
 if jsonb_array_length(p_additional_sizes)>0 then
  return public.proc_save_quote_with_sizes_v1(p_rfq_id,p_supplier_id,p_quote_ref,p_lines,p_additional_sizes,p_valid_until,p_attachment_path,p_notes,p_freight_total,p_minimum_order_value);
 end if;
 return public.proc_save_quote_v3(p_rfq_id,p_supplier_id,p_quote_ref,p_lines,p_valid_until,p_attachment_path,p_notes,p_freight_total,p_minimum_order_value);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_save_quote_v3(p_rfq_id uuid, p_supplier_id uuid, p_quote_ref text, p_lines jsonb, p_valid_until date DEFAULT NULL::date, p_attachment_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_freight_total numeric DEFAULT 0, p_minimum_order_value numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  qid uuid;
  x jsonb;
  ri uuid;
  price numeric;
  avail numeric;
  lead integer;
  disc numeric;
  tax numeric;
  moq_v numeric;
  multiple_v numeric;
  all_quoted boolean;
  rfq_status text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;
  if not private.proc_has_permission('procurement.rfq.manage') then raise exception 'Permission denied: procurement.rfq.manage' using errcode='42501'; end if;
  select status into rfq_status from public.proc_rfqs where id=p_rfq_id for update;
  if rfq_status is null then raise exception 'RFQ not found'; end if;
  if rfq_status not in ('draft','prepared','sent','partially_quoted','quoted') then raise exception 'Cannot edit quotations on an awarded, closed or cancelled RFQ'; end if;
  if not exists(select 1 from public.proc_rfq_suppliers where rfq_id=p_rfq_id and supplier_id=p_supplier_id) then
    raise exception 'Supplier is not invited to this RFQ';
  end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then
    raise exception 'At least one quote line is required';
  end if;
  if coalesce(p_freight_total,0)<0 or coalesce(p_minimum_order_value,0)<0 then
    raise exception 'Freight and minimum order value cannot be negative';
  end if;

  insert into public.proc_quotes(
    rfq_id,supplier_id,quote_ref,valid_until,attachment_path,status,notes,created_by,
    freight_total,minimum_order_value
  )
  values(
    p_rfq_id,p_supplier_id,nullif(trim(p_quote_ref),''),p_valid_until,p_attachment_path,
    'received',p_notes,caller,coalesce(p_freight_total,0),coalesce(p_minimum_order_value,0)
  )
  on conflict(rfq_id,supplier_id) do update
    set quote_ref=excluded.quote_ref,
        valid_until=excluded.valid_until,
        attachment_path=coalesce(excluded.attachment_path,public.proc_quotes.attachment_path),
        status='received',
        notes=excluded.notes,
        freight_total=excluded.freight_total,
        minimum_order_value=excluded.minimum_order_value
  returning id into qid;

  delete from public.proc_quote_lines where quote_id=qid;

  for x in select * from jsonb_array_elements(p_lines)
  loop
    ri:=(x->>'rfq_item_id')::uuid;
    if not exists(select 1 from public.proc_rfq_items where id=ri and rfq_id=p_rfq_id) then
      raise exception 'Quote line does not belong to this RFQ';
    end if;

    price:=(x->>'unit_price')::numeric;
    avail:=nullif(x->>'available_qty','')::numeric;
    lead:=nullif(x->>'lead_days','')::integer;
    disc:=coalesce(nullif(x->>'discount_percent','')::numeric,0);
    tax:=coalesce(nullif(x->>'tax_percent','')::numeric,0);
    moq_v:=coalesce(nullif(x->>'moq','')::numeric,0);
    multiple_v:=coalesce(nullif(x->>'order_multiple','')::numeric,1);

    if price is null or price<0 then raise exception 'Unit price must be zero or positive'; end if;
    if avail is not null and avail<0 then raise exception 'Available quantity cannot be negative'; end if;
    if lead is not null and lead<0 then raise exception 'Lead days cannot be negative'; end if;
    if disc<0 or disc>100 or tax<0 or tax>100 then raise exception 'Discount and tax must be 0 to 100'; end if;
    if moq_v<0 or multiple_v<=0 then raise exception 'MOQ must be zero or positive and order multiple must be greater than zero'; end if;

    insert into public.proc_quote_lines(
      quote_id,rfq_item_id,unit_price,available_qty,lead_days,
      discount_percent,tax_percent,moq,order_multiple,notes
    )
    values(
      qid,ri,price,avail,lead,disc,tax,moq_v,multiple_v,nullif(x->>'notes','')
    );
  end loop;

  update public.proc_rfq_suppliers
  set status='quoted',replied_at=now()
  where rfq_id=p_rfq_id and supplier_id=p_supplier_id;

  select not exists(
    select 1 from public.proc_rfq_suppliers where rfq_id=p_rfq_id and status not in ('quoted','declined')
  ) into all_quoted;

  update public.proc_rfqs
  set status=case when all_quoted then 'quoted' else 'partially_quoted' end,updated_at=now()
  where id=p_rfq_id;

  return jsonb_build_object(
    'quote_id',qid,
    'status',case when all_quoted then 'quoted' else 'partially_quoted' end
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_set_capture_override_v1(p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare session uuid:=nullif(auth.jwt()->>'session_id','')::uuid;
begin
 if not private.proc_access_super_admin() then raise exception 'Only Super Admin can allow screenshots' using errcode='42501';end if;
 if session is null then raise exception 'Signed-in session required' using errcode='42501';end if;
 if p_enabled is null then raise exception 'Choose whether to enable screenshots';end if;
 if p_enabled then
  insert into private.proc_capture_overrides(user_id,session_id,expires_at) values(auth.uid(),session,now()+interval '5 minutes')
  on conflict(user_id,session_id) do update set expires_at=excluded.expires_at;
 else delete from private.proc_capture_overrides where user_id=auth.uid() and session_id=session;end if;
 return public.proc_capture_status_v1();
end $function$

CREATE OR REPLACE FUNCTION public.proc_set_my_language_v1(p_language text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare v text:=lower(trim(coalesce(p_language,'')));
begin
  if auth.uid() is null then raise exception 'Not authenticated'; end if;
  if v not in ('en','ta','si') then raise exception 'Unsupported language'; end if;
  update public.proc_profiles set language=v,updated_at=now() where id=auth.uid() and active=true;
  if not found then raise exception 'Active profile not found'; end if;
  return v;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_set_rfq_supplier_items_v1(p_rfq_id uuid, p_supplier_id uuid, p_item_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare rfq public.proc_rfqs; invitation public.proc_rfq_suppliers;
begin
 if auth.uid() is null or not private.proc_has_permission('procurement.rfq.manage') then
  raise exception 'Permission denied: procurement.rfq.manage' using errcode='42501';
 end if;
 select * into rfq from public.proc_rfqs where id=p_rfq_id for update;
 if rfq.id is null then raise exception 'RFQ not found'; end if;
 if rfq.status not in ('draft','prepared','sent','partially_quoted','quoted') then raise exception 'Cannot change request items on a closed RFQ'; end if;
 select * into invitation from public.proc_rfq_suppliers where rfq_id=p_rfq_id and supplier_id=p_supplier_id for update;
 if invitation.id is null then raise exception 'Supplier is not invited to this RFQ'; end if;
 if invitation.status not in ('pending','prepared') then raise exception 'Request already sent: create a follow-up RFQ to change its items'; end if;
 if p_item_ids is null or cardinality(p_item_ids)=0 then raise exception 'Select at least one request item'; end if;
 if exists(select 1 from unnest(p_item_ids) requested(id) where requested.id is null or not exists(select 1 from public.proc_rfq_items ri where ri.id=requested.id and ri.rfq_id=p_rfq_id)) then raise exception 'Request item does not belong to this RFQ'; end if;
 update public.proc_rfq_suppliers set requested_item_ids=array(select distinct x from unnest(p_item_ids) x order by x)
 where id=invitation.id returning * into invitation;
 return to_jsonb(invitation);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_straight_through_stock_count_v1(p_count_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  cfg jsonb;
  enabled_v boolean;
  req_ids uuid[];
  supplier_ids uuid[];
  supplier_limit_v integer;
  min_quotes_v integer;
  due_days_v integer;
  rfq_id uuid;
  rfq_no text;
  rid uuid;
  sid uuid;
  r public.proc_requirements;
  item_rec public.proc_items;
  coverage_ok boolean;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler','stock_checker') then raise exception 'Not authorized'; end if;

  select enabled,coalesce(config,'{}'::jsonb)
  into enabled_v,cfg
  from public.proc_feature_settings
  where feature_key='procurement.straight_through';

  if not coalesce(enabled_v,false) then
    return jsonb_build_object('status','disabled');
  end if;

  if not exists(
    select 1 from public.proc_stock_counts
    where id=p_count_id and status='submitted'
  ) then
    raise exception 'Submitted stock count not found';
  end if;

  select array_agg(r.id order by r.created_at)
  into req_ids
  from public.proc_requirements r
  join public.proc_stock_count_lines scl on scl.id=r.source_count_line_id
  where scl.count_id=p_count_id
    and r.status not in ('received','closed','cancelled')
    and greatest(r.adjusted_qty-r.ordered_qty,0)>0
    and not exists(
      select 1
      from public.proc_rfq_items ri
      join public.proc_rfqs q on q.id=ri.rfq_id
      where ri.requirement_id=r.id
        and q.status in ('draft','sent','partially_quoted','quoted')
    );

  if coalesce(array_length(req_ids,1),0)=0 then
    return jsonb_build_object('status','no_requirements');
  end if;

  -- Routine stock-count shortages are trusted inputs. They bypass the ordinary
  -- approval click while manual/special purchases continue to use review.
  update public.proc_requirements
  set approval_status='approved',
      selected_for_order=true,
      approved_by=caller,
      approved_at=now(),
      updated_at=now()
  where id=any(req_ids);

  select greatest(coalesce(nullif(config->>'minimum_quotes','')::integer,2),1)
  into min_quotes_v
  from public.proc_feature_settings
  where feature_key='quotes.minimum_quotes';
  min_quotes_v:=greatest(coalesce(min_quotes_v,2),1);

  supplier_limit_v:=greatest(
    min_quotes_v,
    least(coalesce(nullif(cfg->>'supplier_limit','')::integer,3),10)
  );
  due_days_v:=greatest(coalesce(nullif(cfg->>'rfq_due_days','')::integer,2),0);

  select array_agg(supplier_id)
  into supplier_ids
  from (
    select supplier_id
    from public.proc_suggest_suppliers(req_ids)
    order by matched_items desc,unrestricted asc,supplier_name asc
    limit supplier_limit_v
  ) s;

  if coalesce(array_length(supplier_ids,1),0)=0 then
    return jsonb_build_object(
      'status','needs_supplier_setup',
      'requirements',array_length(req_ids,1)
    );
  end if;

  -- Make sure every item is covered by at least one selected supplier. If the
  -- configured supplier limit is too narrow, expand automatically before
  -- sending the batch to human review.
  foreach rid in array req_ids loop
    select i.* into item_rec
    from public.proc_requirements rr
    join public.proc_items i on i.id=rr.item_id
    where rr.id=rid;

    select exists(
      select 1
      from unnest(supplier_ids) chosen(supplier_id)
      where
        not exists(
          select 1 from public.proc_supplier_scopes sc
          where sc.supplier_id=chosen.supplier_id
        )
        or exists(
          select 1
          from public.proc_supplier_scopes sc
          where sc.supplier_id=chosen.supplier_id
            and (
              (sc.scope_type='item' and sc.item_id=item_rec.id)
              or (sc.scope_type='category' and sc.scope_value=item_rec.category)
              or (sc.scope_type='main_group' and sc.scope_value=item_rec.main_group)
              or (sc.scope_type='subgroup' and sc.scope_value=item_rec.subgroup)
            )
        )
    ) into coverage_ok;

    if not coverage_ok then
      select array_agg(supplier_id)
      into supplier_ids
      from (
        select supplier_id
        from public.proc_suggest_suppliers(req_ids)
        order by matched_items desc,unrestricted asc,supplier_name asc
        limit 10
      ) expanded;
      exit;
    end if;
  end loop;

  foreach rid in array req_ids loop
    select i.* into item_rec
    from public.proc_requirements rr
    join public.proc_items i on i.id=rr.item_id
    where rr.id=rid;

    select exists(
      select 1
      from unnest(supplier_ids) chosen(supplier_id)
      where
        not exists(
          select 1 from public.proc_supplier_scopes sc
          where sc.supplier_id=chosen.supplier_id
        )
        or exists(
          select 1
          from public.proc_supplier_scopes sc
          where sc.supplier_id=chosen.supplier_id
            and (
              (sc.scope_type='item' and sc.item_id=item_rec.id)
              or (sc.scope_type='category' and sc.scope_value=item_rec.category)
              or (sc.scope_type='main_group' and sc.scope_value=item_rec.main_group)
              or (sc.scope_type='subgroup' and sc.scope_value=item_rec.subgroup)
            )
        )
    ) into coverage_ok;

    if not coverage_ok then
      return jsonb_build_object(
        'status','needs_supplier_setup',
        'requirements',array_length(req_ids,1),
        'requirement_id',rid
      );
    end if;
  end loop;

  rfq_id:=gen_random_uuid();
  rfq_no:='RFQ-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');
  insert into public.proc_rfqs(id,rfq_no,status,due_date,notes,created_by)
  values(
    rfq_id,rfq_no,'sent',current_date+due_days_v,
    'Automatically prepared from physical stock count '||p_count_id::text,
    caller
  ); select q.rfq_no into rfq_no from public.proc_rfqs q where q.id=rfq_id;

  foreach rid in array req_ids loop
    select * into r from public.proc_requirements where id=rid for update;
    insert into public.proc_rfq_items(rfq_id,requirement_id,requested_qty)
    values(rfq_id,r.id,greatest(r.adjusted_qty-r.ordered_qty,0));
    update public.proc_requirements
    set status='quoting',updated_at=now()
    where id=r.id;
  end loop;

  foreach sid in array supplier_ids loop
    insert into public.proc_rfq_suppliers(rfq_id,supplier_id,status,sent_at)
    values(rfq_id,sid,'sent',now());
  end loop;

  return jsonb_build_object(
    'status','rfq_created',
    'rfq_id',rfq_id,
    'rfq_no',rfq_no,
    'requirements',array_length(req_ids,1),
    'suppliers',array_length(supplier_ids,1),
    'due_date',(current_date+due_days_v)
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_straight_through_stock_count_v2(p_count_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  cfg jsonb;
  enabled_v boolean;
  req_ids uuid[];
  supplier_ids uuid[];
  supplier_limit_v integer;
  min_quotes_v integer;
  due_days_v integer;
  rfq_id uuid;
  rfq_no text;
  rid uuid;
  sid uuid;
  r public.proc_requirements;
  item_rec public.proc_items;
  coverage_ok boolean;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler','stock_checker') then raise exception 'Not authorized'; end if;

  select enabled,coalesce(config,'{}'::jsonb) into enabled_v,cfg
  from public.proc_feature_settings where feature_key='procurement.straight_through';
  if not coalesce(enabled_v,false) then return jsonb_build_object('status','disabled'); end if;

  if not exists(select 1 from public.proc_stock_counts where id=p_count_id and status='submitted') then
    raise exception 'Submitted stock count not found';
  end if;

  select array_agg(req.id order by req.created_at) into req_ids
  from public.proc_requirements req
  join public.proc_stock_count_lines scl on scl.id=req.source_count_line_id
  where scl.count_id=p_count_id
    and req.status not in ('received','closed','cancelled')
    and greatest(req.adjusted_qty-req.ordered_qty,0)>0
    and not exists(
      select 1 from public.proc_rfq_items ri
      join public.proc_rfqs q on q.id=ri.rfq_id
      where ri.requirement_id=req.id
        and q.status in ('draft','prepared','sent','partially_quoted','quoted')
    );

  if coalesce(array_length(req_ids,1),0)=0 then
    perform private.proc_upsert_automation_job_v1('stock_continue','stock_count',p_count_id,'completed','{"result":"no_requirements"}'::jsonb,null);
    return jsonb_build_object('status','no_requirements');
  end if;

  update public.proc_requirements
  set approval_status='approved',selected_for_order=true,approved_by=caller,approved_at=now(),updated_at=now()
  where id=any(req_ids);

  select greatest(coalesce(nullif(config->>'minimum_quotes','')::integer,2),1)
  into min_quotes_v from public.proc_feature_settings where feature_key='quotes.minimum_quotes';
  min_quotes_v:=greatest(coalesce(min_quotes_v,2),1);
  supplier_limit_v:=least(greatest(coalesce(nullif(cfg->>'supplier_limit','')::integer,3),min_quotes_v),10);
  due_days_v:=greatest(coalesce(nullif(cfg->>'rfq_due_days','')::integer,2),0);

  select array_agg(supplier_id) into supplier_ids
  from (
    select supplier_id
    from public.proc_suggest_suppliers(req_ids)
    order by matched_items desc,unrestricted asc,supplier_name asc
    limit supplier_limit_v
  ) s;

  if coalesce(array_length(supplier_ids,1),0)=0 then
    perform private.proc_upsert_automation_job_v1(
      'stock_continue','stock_count',p_count_id,'needs_action',
      jsonb_build_object('reason','no_eligible_supplier','requirements',array_length(req_ids,1)),
      'No active eligible supplier covers the shortage.'
    );
    return jsonb_build_object('status','needs_supplier_setup','requirements',array_length(req_ids,1));
  end if;

  -- Expand up to 10 suppliers if needed so every item is covered.
  foreach rid in array req_ids loop
    select i.* into item_rec from public.proc_requirements rr join public.proc_items i on i.id=rr.item_id where rr.id=rid;
    select exists(select 1 from unnest(supplier_ids) x(supplier_id)
      where private.proc_supplier_covers_item_v1(x.supplier_id,item_rec.id)) into coverage_ok;
    if not coverage_ok then
      select array_agg(supplier_id) into supplier_ids
      from (
        select supplier_id from public.proc_suggest_suppliers(req_ids)
        order by matched_items desc,unrestricted asc,supplier_name asc
        limit 10
      ) expanded;
      exit;
    end if;
  end loop;

  foreach rid in array req_ids loop
    select i.* into item_rec from public.proc_requirements rr join public.proc_items i on i.id=rr.item_id where rr.id=rid;
    select exists(select 1 from unnest(supplier_ids) x(supplier_id)
      where private.proc_supplier_covers_item_v1(x.supplier_id,item_rec.id)) into coverage_ok;
    if not coverage_ok then
      perform private.proc_upsert_automation_job_v1(
        'stock_continue','stock_count',p_count_id,'needs_action',
        jsonb_build_object('reason','supplier_coverage_gap','requirement_id',rid),
        'At least one shortage has no eligible supplier.'
      );
      return jsonb_build_object('status','needs_supplier_setup','requirements',array_length(req_ids,1),'requirement_id',rid);
    end if;
  end loop;

  rfq_id:=gen_random_uuid();
  rfq_no:='RFQ-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');
  insert into public.proc_rfqs(id,rfq_no,status,due_date,notes,created_by)
  values(rfq_id,rfq_no,'prepared',current_date+due_days_v,'Automatically prepared from physical stock count '||p_count_id::text,caller); select q.rfq_no into rfq_no from public.proc_rfqs q where q.id=rfq_id;

  foreach rid in array req_ids loop
    select * into r from public.proc_requirements where id=rid for update;
    insert into public.proc_rfq_items(rfq_id,requirement_id,requested_qty)
    values(rfq_id,r.id,greatest(r.adjusted_qty-r.ordered_qty,0));
    update public.proc_requirements set status='quoting',updated_at=now() where id=r.id;
  end loop;

  foreach sid in array supplier_ids loop
    insert into public.proc_rfq_suppliers(rfq_id,supplier_id,status,sent_at,sent_by)
    values(rfq_id,sid,'pending',null,null);
  end loop;

  perform private.proc_upsert_automation_job_v1(
    'stock_continue','stock_count',p_count_id,'completed',
    jsonb_build_object('rfq_id',rfq_id,'rfq_no',rfq_no),null
  );
  perform private.proc_upsert_automation_job_v1(
    'rfq_send','rfq',rfq_id,'needs_action',
    jsonb_build_object('suppliers',array_length(supplier_ids,1),'due_date',current_date+due_days_v),
    'RFQ prepared. Confirm actual supplier transmission.'
  );

  return jsonb_build_object(
    'status','rfq_prepared','rfq_id',rfq_id,'rfq_no',rfq_no,
    'requirements',array_length(req_ids,1),'suppliers',array_length(supplier_ids,1),
    'configured_minimum_quotes',min_quotes_v,'due_date',current_date+due_days_v
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_submit_company_list_check_v1(p_company_id uuid, p_lines jsonb, p_notes text DEFAULT NULL::text, p_count_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  loc uuid;
  c public.proc_companies;
  count_id uuid;
  count_no text;
  x jsonb;
  cli public.proc_company_list_items;
  it public.proc_items;
  current_qty numeric;
  trigger_qty numeric;
  suggested numeric;
  req_count integer;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','stock_handler','stock_checker') then raise exception 'Not authorized'; end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'At least one counted item is required'; end if;

  select * into c from public.proc_companies where id=p_company_id and active=true and company_list_enabled=true;
  if c.id is null then raise exception 'Company list not found'; end if;

  loc:=private.proc_default_location_id();
  count_no:='CC-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');

  insert into public.proc_stock_counts(
    count_no,location_id,category,status,counted_by,notes,count_started_at
  )
  values(count_no,loc,'COMPANY: '||c.name,'draft',caller,p_notes,coalesce(p_count_started_at,now()))
  returning id into count_id;

  for x in select value from jsonb_array_elements(p_lines)
  loop
    select * into cli
    from public.proc_company_list_items
    where id=(x->>'company_list_item_id')::uuid
      and company_id=p_company_id and active=true;

    if cli.id is null then raise exception 'Invalid company-list item'; end if;
    select * into it from public.proc_items where id=cli.item_id and active=true;
    if it.id is null then raise exception 'Inactive item in company list'; end if;

    current_qty:=(x->>'current_stock')::numeric;
    if current_qty is null or current_qty<0 then raise exception 'Current stock must be zero or positive'; end if;

    trigger_qty:=coalesce(cli.reorder_level,cli.target_stock);
    suggested:=case when current_qty<=trigger_qty then greatest(cli.target_stock-current_qty,0) else 0 end;

    insert into public.proc_stock_count_lines(
      count_id,item_id,current_stock,max_stock_snapshot,reorder_level_snapshot,
      movement_snapshot,suggested_qty,required_qty,note
    )
    values(
      count_id,it.id,current_qty,cli.target_stock,trigger_qty,it.movement,
      suggested,suggested,nullif(x->>'note','')
    );
  end loop;

  req_count:=private.proc_submit_stock_count_impl(count_id);
  return jsonb_build_object(
    'count_id',count_id,'count_no',count_no,
    'requirements_created',req_count,'company_id',c.id,'company_name',c.name
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_submit_company_list_check_v2(p_company_id uuid, p_lines jsonb, p_notes text DEFAULT NULL::text, p_count_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare caller uuid:=auth.uid();c public.proc_companies;loc uuid;count_id_v uuid;count_no_v text;x jsonb;cli public.proc_company_list_items;it public.proc_items;current_v numeric;trigger_v numeric;suggested numeric;enough boolean;req_count integer;ids uuid[];orders jsonb:='[]';errors_v jsonb:='[]';
begin
 perform private.proc_assert_access();
 if not private.proc_has_permission('stock.count.enter') then raise exception 'Stock entry permission required';end if;
 if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 or jsonb_array_length(p_lines)>1000 then raise exception 'Choose 1–1000 counted items';end if;
 select * into c from public.proc_companies where id=p_company_id and active and company_list_enabled;
 if c.id is null then raise exception 'Company list not found';end if;
 if (select count(distinct value->>'company_list_item_id') from jsonb_array_elements(p_lines))<>jsonb_array_length(p_lines) then raise exception 'Duplicate company stock item';end if;
 loc:=private.proc_default_location_id();count_no_v:='COMPANY-'||gen_random_uuid();
 insert into public.proc_stock_counts(count_no,location_id,category,status,counted_by,notes,count_started_at)
 values(count_no_v,loc,'COMPANY: '||c.name,'draft',caller,p_notes,coalesce(p_count_started_at,now())) returning id,count_no into count_id_v,count_no_v;
 for x in select value from jsonb_array_elements(p_lines) loop
  select * into cli from public.proc_company_list_items where id=(x->>'company_list_item_id')::uuid and company_id=c.id and active;
  if cli.id is null then raise exception 'Invalid company-list item';end if;
  select * into it from public.proc_items where id=cli.item_id and active;
  if it.id is null then raise exception 'Inactive company item';end if;
  enough:=coalesce((x->>'sufficient_stock')::boolean,false);
  if cli.max_stock_review and not enough then raise exception 'Admin must enter maximum stock before ordering this item';end if;
  current_v:=case when enough then null else (x->>'current_stock')::numeric end;
  if not enough and (current_v is null or current_v<0 or current_v::text in ('NaN','Infinity','-Infinity')) then raise exception 'Invalid current stock';end if;
  trigger_v:=coalesce(cli.reorder_level,cli.target_stock*.5);
  suggested:=case when enough then 0 when current_v<=trigger_v then greatest(cli.target_stock-current_v,0) else 0 end;
  insert into public.proc_stock_count_lines(count_id,item_id,current_stock,max_stock_snapshot,reorder_level_snapshot,movement_snapshot,suggested_qty,required_qty,sufficient_stock,note)
  values(count_id_v,it.id,current_v,cli.target_stock,trigger_v,it.movement,suggested,suggested,enough,nullif(x->>'note',''));
 end loop;
 req_count:=private.proc_submit_stock_count_impl(count_id_v);
 ids:=private.proc_company_link_count(c.id,count_id_v);
 if coalesce(cardinality(ids),0)>0 and (c.auto_approve or c.group_auto_approve or exists (
   select 1 from public.proc_requirements req
   cross join lateral private.proc_company_effective_route(c.id,req.item_id) rt(route)
   where req.id=any(ids) and req.company_id=c.id
   and rt.route->>'mode'='direct' and coalesce((rt.route->>'explicit')::boolean,false)
   and coalesce((rt.route->>'auto_send')::boolean,false)
  )) then
  begin
   orders:=private.proc_company_auto_from_count(c.id,count_id_v,ids);
  exception when others then
   -- Document/approval failures must not discard a valid physical stock count.
   errors_v:=jsonb_build_array(jsonb_build_object('stage','direct_po','error',SQLERRM));
  end;
 end if;
 return jsonb_build_object('count_id',count_id_v,'count_no',count_no_v,'requirements_created',req_count,'purchase_orders',orders,'company_id',c.id,'automation_errors',errors_v);
end $function$

CREATE OR REPLACE FUNCTION public.proc_submit_company_list_check_v3(p_company_id uuid, p_lines jsonb, p_submission_id uuid, p_notes text DEFAULT NULL::text, p_count_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result_v jsonb;cached record;c public.proc_companies;rr record;route_v jsonb;ids uuid[];suppliers uuid[];override_v jsonb;rfq_v jsonb;
 caller uuid:=auth.uid();claims_v text;sub_v text;requests jsonb:='[]';errors_v jsonb:='[]';
BEGIN
 PERFORM private.proc_assert_access();
 IF NOT private.proc_has_permission('stock.count.enter') OR p_submission_id IS NULL THEN RAISE EXCEPTION 'Stock submission permission and submission ID required';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('company-submit:'||p_submission_id::text,0));
 -- Serialize separate submissions for this company, not just retries of one token.
 PERFORM 1 FROM public.proc_companies WHERE id=p_company_id FOR UPDATE;
 SELECT * INTO cached FROM private.proc_company_submission_receipts WHERE id=p_submission_id;
 IF FOUND THEN
  IF cached.company_id<>p_company_id OR cached.submitted_by<>caller OR cached.lines IS DISTINCT FROM p_lines THEN RAISE EXCEPTION 'Submission was already saved with different quantities; review stock history before submitting another count';END IF;
  RETURN cached.result;
 END IF;
 result_v:=public.proc_submit_company_list_check_v2(p_company_id,p_lines,p_notes,p_count_started_at);
 errors_v:=coalesce(result_v->'automation_errors','[]'::jsonb);
 SELECT * INTO c FROM public.proc_companies WHERE id=p_company_id FOR UPDATE;
 -- A worker's submitted count, rather than arbitrary older requirements, is the only automation scope.
 FOR rr IN SELECT DISTINCT (private.proc_company_effective_route(c.id,r.item_id)->>'route_id')::uuid route_id
  FROM public.proc_requirements r JOIN public.proc_stock_count_lines l ON l.id=r.source_count_line_id
  WHERE l.count_id=(result_v->>'count_id')::uuid AND r.company_id=c.id
 LOOP
  IF rr.route_id IS NULL THEN CONTINUE;END IF;
  BEGIN
   SELECT jsonb_build_object('mode',route_mode,'auto_send',auto_send,'template',document_template) INTO route_v FROM public.proc_company_section_routes WHERE id=rr.route_id;
   IF route_v->>'mode'<>'rfq' OR NOT coalesce((route_v->>'auto_send')::boolean,false) THEN CONTINUE;END IF;
   IF NOT EXISTS(SELECT 1 FROM public.proc_profiles WHERE id=c.automation_admin_id AND active AND role='admin') THEN RAISE EXCEPTION 'Automation administrator is inactive';END IF;
   SELECT array_agg(r.id ORDER BY r.id) INTO ids FROM public.proc_requirements r JOIN public.proc_stock_count_lines l ON l.id=r.source_count_line_id
    WHERE l.count_id=(result_v->>'count_id')::uuid AND r.company_id=c.id AND r.adjusted_qty>r.ordered_qty AND r.status NOT IN ('closed','cancelled','received')
    AND NOT EXISTS(SELECT 1 FROM private.proc_company_open_orders(r.item_id,r.location_id))
    AND private.proc_company_effective_route(c.id,r.item_id)->>'route_id'=rr.route_id::text
    AND NOT EXISTS(SELECT 1 FROM public.proc_rfq_items ri JOIN public.proc_rfqs q ON q.id=ri.rfq_id JOIN public.proc_requirements other ON other.id=ri.requirement_id WHERE other.item_id=r.item_id AND other.location_id=r.location_id AND q.status IN ('draft','prepared','sent','partially_quoted','quoted'));
   IF coalesce(cardinality(ids),0)=0 THEN CONTINUE;END IF;
   SELECT array_agg(s.supplier_id ORDER BY s.sort_order) INTO suppliers FROM public.proc_company_section_route_suppliers s JOIN public.proc_suppliers p ON p.id=s.supplier_id AND p.active AND p.supplier_kind='company' WHERE s.route_id=rr.route_id;
   IF coalesce(cardinality(suppliers),0)=0 THEN RAISE EXCEPTION 'No active suppliers are configured';END IF;
   claims_v:=current_setting('request.jwt.claims',true);sub_v:=current_setting('request.jwt.claim.sub',true);
   BEGIN
    PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',c.automation_admin_id,'role','authenticated')::text,true);PERFORM set_config('request.jwt.claim.sub',c.automation_admin_id::text,true);
    IF NOT private.proc_has_permission('procurement.rfq.manage') THEN RAISE EXCEPTION 'Automation administrator no longer has RFQ permission';END IF;
    UPDATE public.proc_requirements SET approval_status='approved',selected_for_order=true,approved_by=c.automation_admin_id,approved_at=now(),updated_at=now() WHERE id=ANY(ids);
    SELECT jsonb_object_agg(id::text,'Administrator opted in to automatic company/category RFQs') INTO override_v FROM unnest(suppliers) t(id);
    rfq_v:=public.proc_create_rfq_v4(ids,suppliers,NULL,'Automatic company stock RFQ',override_v);
    INSERT INTO public.proc_company_rfq_queue(company_id,route_id,count_id,rfq_id,supplier_id,automation_admin_id,document_template)
     SELECT c.id,rr.route_id,(result_v->>'count_id')::uuid,(rfq_v->>'rfq_id')::uuid,id,c.automation_admin_id,coalesce(route_v->'template','{}') FROM unnest(suppliers) t(id) ON CONFLICT(rfq_id,supplier_id) DO NOTHING;
    PERFORM set_config('request.jwt.claims',coalesce(claims_v,''),true);PERFORM set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);
   EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('request.jwt.claims',coalesce(claims_v,''),true);PERFORM set_config('request.jwt.claim.sub',coalesce(sub_v,''),true);RAISE;
   END;
   requests:=requests||jsonb_build_array(rfq_v);
  EXCEPTION WHEN OTHERS THEN errors_v:=errors_v||jsonb_build_array(jsonb_build_object('route_id',rr.route_id,'error',SQLERRM));END;
 END LOOP;
 result_v:=result_v||jsonb_build_object('rfqs',requests,'automation_errors',errors_v,'stock_outcomes',private.proc_company_count_outcomes((result_v->>'count_id')::uuid));
 INSERT INTO private.proc_company_submission_receipts(id,company_id,submitted_by,lines,result) VALUES(p_submission_id,c.id,caller,p_lines,result_v);
 RETURN result_v;
END $function$

CREATE OR REPLACE FUNCTION public.proc_submit_stock_and_continue_v1(p_category text, p_lines jsonb, p_notes text DEFAULT NULL::text, p_attachment_path text DEFAULT NULL::text, p_count_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare base jsonb; auto jsonb; cid uuid;
begin
  base:=public.proc_submit_stock_check_v4(p_category,p_lines,p_notes,p_attachment_path,p_count_started_at);
  cid:=(base->>'count_id')::uuid;
  begin
    auto:=public.proc_straight_through_stock_count_v2(cid);
  exception when others then
    perform private.proc_upsert_automation_job_v1(
      'stock_continue','stock_count',cid,'failed','{}'::jsonb,sqlerrm
    );
    auto:=jsonb_build_object('status','automation_failed','error',sqlerrm);
  end;
  return base||jsonb_build_object('automation',auto);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_submit_stock_and_continue_v2(p_category text, p_lines jsonb, p_notes text DEFAULT NULL::text, p_attachment_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  trusted_started timestamptz;
  base jsonb;
  auto jsonb;
  cid uuid;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select count_started_at into trusted_started
  from public.proc_stock_count_drafts
  where owner_id=caller;

  if trusted_started is null then
    trusted_started:=public.proc_begin_stock_count_session_v1();
  end if;

  base:=public.proc_submit_stock_check_v4(p_category,p_lines,p_notes,p_attachment_path,trusted_started);
  cid:=(base->>'count_id')::uuid;

  begin
    auto:=public.proc_straight_through_stock_count_v2(cid);
  exception when others then
    perform private.proc_upsert_automation_job_v1(
      'stock_continue','stock_count',cid,'failed','{}'::jsonb,sqlerrm
    );
    auto:=jsonb_build_object('status','automation_failed','error',sqlerrm);
  end;

  delete from public.proc_stock_count_drafts where owner_id=caller;
  return base||jsonb_build_object('automation',auto);
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_submit_stock_and_continue_v3(p_category text, p_lines jsonb, p_notes text DEFAULT NULL::text, p_attachment_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
 caller uuid:=auth.uid();
 trusted_started timestamptz;
 base jsonb;
 cid uuid;
 item_total integer:=0;
 shortage_total integer:=0;
begin
 if caller is null then raise exception 'Not authenticated'; end if;
 if not private.proc_has_permission('stock.count.enter') then
   raise exception 'Permission denied: stock.count.enter' using errcode='42501';
 end if;

 select count_started_at into trusted_started
 from public.proc_stock_count_drafts
 where owner_id=caller;

 if trusted_started is null then
   trusted_started:=public.proc_begin_stock_count_session_v1();
 end if;

 base:=public.proc_submit_stock_check_v4(
   p_category,p_lines,p_notes,p_attachment_path,trusted_started
 );
 cid:=(base->>'count_id')::uuid;

 select count(*),
        count(*) filter (where coalesce(required_qty,0)>0)
 into item_total,shortage_total
 from public.proc_stock_count_lines
 where count_id=cid;

 delete from public.proc_stock_count_drafts where owner_id=caller;

 return base || jsonb_build_object(
   'automation',
   jsonb_build_object(
     'status',case when shortage_total>0 then 'review_required' else 'no_requirements' end,
     'submitted_items',item_total,
     'requirements',shortage_total
   )
 );
end;
end;$function$

