CREATE OR REPLACE FUNCTION public.proc_submit_stock_check_v3(p_category text, p_lines jsonb, p_notes text DEFAULT NULL::text, p_attachment_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
