  )
  returning id into count_id;

  for line_json in select value from jsonb_array_elements(p_lines)
  loop
    select * into it
    from public.proc_items
    where id=(line_json->>'item_id')::uuid
      and active=true;

    if it.id is null then raise exception 'Invalid or inactive item in stock count'; end if;

    current_qty:=(line_json->>'current_stock')::numeric;
