      count_id,it.id,current_qty,it.max_stock,it.reorder_level,it.movement,
      suggested,suggested,nullif(line_json->>'note','')
    );
  end loop;

  req_count:=private.proc_submit_stock_count_impl(count_id);

  return jsonb_build_object(
    'count_id',count_id,
    'count_no',count_no,
    'requirements_created',req_count,
    'category',count_category
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_submit_stock_check_v4(p_category text, p_lines jsonb, p_notes text DEFAULT NULL::text, p_attachment_path text DEFAULT NULL::text, p_count_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
