  it public.proc_items;
  current_qty numeric;
  suggested numeric;
  req_count integer;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler','stock_checker') then raise exception 'Not authorized'; end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'At least one counted item is required'; end if;
  if jsonb_array_length(p_lines)>1000 then raise exception 'Submit no more than 1000 counted items at once'; end if;

  loc:=private.proc_default_location_id();
  if loc is null then raise exception 'Default stock location is not configured'; end if;

  select count(distinct i.category),min(i.category)
  into category_count,count_category
  from jsonb_array_elements(p_lines) as j(line_data)
  join public.proc_items i on i.id=(j.line_data->>'item_id')::uuid;

  if category_count>1 then count_category:='MIXED'; end if;
  if count_category is null then count_category:=nullif(trim(p_category),''); end if;

  count_no:='SC-'||to_char(clock_timestamp(),'YYMMDD-HH24MISSMS');

  insert into public.proc_stock_counts(
    count_no,location_id,category,status,counted_by,notes,attachment_path,count_started_at
  )
  values(
    count_no,loc,count_category,'draft',caller,p_notes,p_attachment_path,
    coalesce(p_count_started_at,now())
  )
  returning id into count_id;

  for line_json in select value from jsonb_array_elements(p_lines)
  loop
    select * into it
    from public.proc_items
    where id=(line_json->>'item_id')::uuid and active=true;

    if it.id is null then raise exception 'Invalid or inactive item in stock count'; end if;

    if line_json ? 'sufficient_stock' and jsonb_typeof(line_json->'sufficient_stock')<>'boolean' then raise exception 'Sufficient stock must be a boolean'; end if;
    if coalesce((line_json->>'sufficient_stock')::boolean,false) then
      if line_json->>'current_stock' is not null then raise exception 'Sufficient stock cannot include an exact quantity'; end if;
      insert into public.proc_stock_count_lines(count_id,item_id,current_stock,max_stock_snapshot,reorder_level_snapshot,movement_snapshot,suggested_qty,required_qty,note,sufficient_stock)
      values(count_id,it.id,null,it.max_stock,it.reorder_level,it.movement,0,0,'Visually checked: sufficient stock above reorder level',true);
      continue;
    end if;
    current_qty:=(line_json->>'current_stock')::numeric;
    if current_qty is null or current_qty<0 then raise exception 'Current stock must be zero or positive'; end if;

    suggested:=case
      when current_qty<=it.reorder_level then greatest(it.max_stock-current_qty,0)
      else 0
    end;

    insert into public.proc_stock_count_lines(
      count_id,item_id,current_stock,max_stock_snapshot,reorder_level_snapshot,
      movement_snapshot,suggested_qty,required_qty,note
    )
    values(
      count_id,it.id,current_qty,it.max_stock,it.reorder_level,it.movement,
      suggested,suggested,nullif(line_json->>'note','')
    );
  end loop;

  req_count:=private.proc_submit_stock_count_impl(count_id);

  return jsonb_build_object(
    'count_id',count_id,'count_no',count_no,
    'requirements_created',req_count,'category',count_category
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_try_auto_award_v2(p_rfq_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'Asia/Colombo'
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid(); caller_role text; cfg jsonb; enabled_v boolean;
  auto_award_v boolean; auto_approve_v boolean; approval_limit_v numeric; daily_limit_v numeric;
  preferred integer; ri record; r public.proc_requirements; cand record; supplier_rec record; perf record;
  eligible integer; required_q integer; received integer; target_qty numeric;
  min_history_v integer; min_fill_v numeric; max_variance_v numeric; urgent_lead_v integer; is_urgent boolean;
  allocations jsonb:='[]'::jsonb; po_result jsonb; po jsonb; approved_count integer:=0;
  daily_used numeric:=0; skip_reason text:=null;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;

  select enabled,coalesce(config,'{}'::jsonb) into enabled_v,cfg
  from public.proc_feature_settings where feature_key='procurement.straight_through';
  auto_award_v:=coalesce((cfg->>'auto_award')::boolean,true);
  auto_approve_v:=coalesce((cfg->>'auto_approve_po')::boolean,true);
  approval_limit_v:=greatest(coalesce(nullif(cfg->>'po_auto_approval_limit','')::numeric,0),0);
  daily_limit_v:=greatest(coalesce(nullif(cfg->>'daily_auto_approval_limit','')::numeric,approval_limit_v),0);
  min_history_v:=greatest(coalesce(nullif(cfg->>'supplier_history_min_pos','')::integer,3),1);
  min_fill_v:=greatest(least(coalesce(nullif(cfg->>'supplier_min_fill_rate_pct','')::numeric,90),100),0);
  max_variance_v:=greatest(least(coalesce(nullif(cfg->>'supplier_max_invoice_variance_pct','')::numeric,25),100),0);
  urgent_lead_v:=greatest(coalesce(nullif(cfg->>'urgent_max_lead_days','')::integer,7),0);

  if not coalesce(enabled_v,false) or not auto_award_v then return jsonb_build_object('status','disabled'); end if;
  if not exists(select 1 from public.proc_rfqs where id=p_rfq_id) then raise exception 'RFQ not found'; end if;
  if exists(select 1 from public.proc_rfqs where id=p_rfq_id and status in ('awarded','closed','cancelled')) then
    return jsonb_build_object('status','already_finalized');
  end if;

  preferred:=1;

  for ri in
    select i.*,req.item_id
    from public.proc_rfq_items i join public.proc_requirements req on req.id=i.requirement_id
    where i.rfq_id=p_rfq_id and i.selected_for_po=true order by i.id
  loop
    select count(*) into eligible
    from public.proc_rfq_suppliers rs
    where rs.rfq_id=p_rfq_id and rs.status<>'declined'
      and private.proc_supplier_covers_item_v1(rs.supplier_id,ri.item_id);
    required_q:=least(preferred,greatest(eligible,1));

    select count(distinct q.supplier_id) into received
    from public.proc_quote_lines ql join public.proc_quotes q on q.id=ql.quote_id
    where q.rfq_id=p_rfq_id and ql.rfq_item_id=ri.id
      and q.status in ('received','reviewed','selected')
      and (q.valid_until is null or q.valid_until>=current_date);

    if received<required_q then
      return jsonb_build_object('status','waiting_quotes','rfq_item_id',ri.id,'received',received,'required',required_q,'eligible_suppliers',eligible);
    end if;

    select * into r from public.proc_requirements where id=ri.requirement_id for update;
    target_qty:=least(ri.requested_qty,greatest(r.adjusted_qty-r.ordered_qty,0));
    if target_qty<=0 then continue; end if;

    select v.* into cand from public.proc_v_quote_comparison v
    where v.rfq_item_id=ri.id and v.landed_rank=1
      and (v.available_qty is null or v.available_qty>=target_qty)
      and coalesce(v.moq,0)<=target_qty
      and mod(target_qty,coalesce(nullif(v.order_multiple,0),1))=0
    order by v.landed_unit_cost,v.supplier_name limit 1;

    if not found then
      perform private.proc_upsert_automation_job_v1(
        'award_retry','rfq',p_rfq_id,'needs_action',
        jsonb_build_object('reason','best_quote_requires_split_moq_or_override','rfq_item_id',ri.id),
        'Best quotation needs split/MOQ/override review.'
      );
      return jsonb_build_object('status','needs_review','reason','best_quote_requires_split_moq_or_override','rfq_item_id',ri.id);
    end if;

    select * into perf from public.proc_v_supplier_performance where supplier_id=cand.supplier_id;

    if coalesce(perf.po_count,0)>=min_history_v
       and perf.completed_fill_rate_pct is not null
       and perf.completed_fill_rate_pct<min_fill_v then
      perform private.proc_upsert_automation_job_v1(
        'award_retry','rfq',p_rfq_id,'needs_action',
        jsonb_build_object('reason','supplier_fill_rate','supplier_id',cand.supplier_id,'fill_rate_pct',perf.completed_fill_rate_pct),
        'Lowest landed-cost supplier is below the configured historical fill-rate threshold.'
      );
      return jsonb_build_object('status','needs_review','reason','supplier_fill_rate','rfq_item_id',ri.id,
        'supplier_id',cand.supplier_id,'fill_rate_pct',perf.completed_fill_rate_pct,'minimum_fill_rate_pct',min_fill_v);
    end if;

    if coalesce(perf.invoice_count,0)>=min_history_v
       and (100.0*coalesce(perf.invoice_variance_count,0)/greatest(perf.invoice_count,1))>max_variance_v then
      perform private.proc_upsert_automation_job_v1(
        'award_retry','rfq',p_rfq_id,'needs_action',
        jsonb_build_object('reason','supplier_invoice_variance','supplier_id',cand.supplier_id),
        'Lowest landed-cost supplier has excessive historical invoice variance.'
      );
      return jsonb_build_object('status','needs_review','reason','supplier_invoice_variance','rfq_item_id',ri.id,
        'supplier_id',cand.supplier_id,'variance_pct',
        round(100.0*coalesce(perf.invoice_variance_count,0)/greatest(perf.invoice_count,1),1));
    end if;

    is_urgent:=coalesce(r.customer_paid,false)
      or coalesce(r.priority,'normal') in ('urgent','high')
      or (r.needed_by is not null and r.needed_by<=current_date+urgent_lead_v);
    if is_urgent and (cand.lead_days is null or cand.lead_days>urgent_lead_v) then
      perform private.proc_upsert_automation_job_v1(
        'award_retry','rfq',p_rfq_id,'needs_action',
        jsonb_build_object('reason','urgent_lead_time','supplier_id',cand.supplier_id,'lead_days',cand.lead_days),
        'Urgent requirement needs lead-time review.'
      );
      return jsonb_build_object('status','needs_review','reason','urgent_lead_time','rfq_item_id',ri.id,
        'supplier_id',cand.supplier_id,'lead_days',cand.lead_days,'maximum_auto_lead_days',urgent_lead_v);
    end if;

    allocations:=allocations||jsonb_build_array(jsonb_build_object(
      'rfq_item_id',ri.id,'quote_line_id',cand.quote_line_id,'qty',target_qty,'override_reason',null
    ));
  end loop;

  if jsonb_array_length(allocations)=0 then return jsonb_build_object('status','nothing_to_award'); end if;

  for supplier_rec in
    select v.supplier_id,max(q.minimum_order_value) minimum_order_value,
           sum((a->>'qty')::numeric*v.effective_unit_price) planned_goods_value
    from jsonb_array_elements(allocations) a
    join public.proc_v_quote_comparison v on v.quote_line_id=(a->>'quote_line_id')::uuid
    join public.proc_quotes q on q.id=v.quote_id
    group by v.supplier_id
  loop
    if coalesce(supplier_rec.minimum_order_value,0)>coalesce(supplier_rec.planned_goods_value,0) then
      return jsonb_build_object('status','needs_review','reason','supplier_minimum_order',
        'supplier_id',supplier_rec.supplier_id,'minimum_order_value',supplier_rec.minimum_order_value,
        'planned_goods_value',supplier_rec.planned_goods_value);
    end if;
  end loop;

  po_result:=public.proc_finalize_award_plan_v2(p_rfq_id,allocations);

  if auto_approve_v and approval_limit_v>0 and caller_role='admin' then
    select coalesce(sum(total),0) into daily_used
    from public.proc_purchase_orders
    where auto_approved=true and approved_at::date=current_date;

    for po in select value from jsonb_array_elements(po_result) loop
      if coalesce((po->>'total')::numeric,0)<=approval_limit_v
         and (daily_limit_v=0 or daily_used+coalesce((po->>'total')::numeric,0)<=daily_limit_v) then
        perform public.proc_approve_po_v2((po->>'po_id')::uuid);
        update public.proc_purchase_orders
        set auto_approved=true,auto_approval_reason='Straight-through safe landed-cost award within configured limits'
        where id=(po->>'po_id')::uuid;
        daily_used:=daily_used+coalesce((po->>'total')::numeric,0);
        approved_count:=approved_count+1;
      end if;
    end loop;
  elsif auto_approve_v and caller_role<>'admin' then
    skip_reason:='Admin approval required by PO control policy';
  end if;

  perform private.proc_upsert_automation_job_v1('award_retry','rfq',p_rfq_id,'completed','{}'::jsonb,null);

  return jsonb_build_object(
    'status','awarded','purchase_orders',po_result,'auto_approved',approved_count,
    'approval_limit',approval_limit_v,'daily_auto_approval_limit',daily_limit_v,
    'approval_note',skip_reason
  );
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_update_item_master_v1(p_item_id uuid, p_patch jsonb)
 RETURNS proc_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare
  caller uuid:=auth.uid();
  caller_role text;
  current_item public.proc_items;
  updated_item public.proc_items;
  movement_v text;
  max_v numeric;
  description_v text;
begin
  if caller is null then raise exception 'Not authenticated'; end if;
  select role into caller_role from public.proc_profiles where id=caller and active=true;
  if caller_role is null or caller_role not in ('admin','procurement','stock_handler') then
    raise exception 'Admin, Procurement or Stock / Item Handler access required';
  end if;

  select * into current_item from public.proc_items where id=p_item_id for update;
  if current_item.id is null then raise exception 'Item not found'; end if;

  if p_patch ? 'movement' then
    movement_v:=upper(trim(coalesce(p_patch->>'movement','')));
    if movement_v not in ('FAST','NORMAL','SLOW') then raise exception 'Invalid movement'; end if;
  else movement_v:=current_item.movement;
  end if;

  if p_patch ? 'max_stock' then
    max_v:=(p_patch->>'max_stock')::numeric;
    if max_v<0 then raise exception 'Max Stock cannot be negative'; end if;
  else max_v:=current_item.max_stock;
  end if;

  if p_patch ? 'description' then
    description_v:=trim(coalesce(p_patch->>'description',''));
    if description_v='' then raise exception 'Description cannot be blank'; end if;
  else description_v:=current_item.description;
  end if;

  update public.proc_items
  set
    active=case when p_patch ? 'active' then coalesce((p_patch->>'active')::boolean,active) else active end,
    category=case when p_patch ? 'category' then coalesce(nullif(trim(p_patch->>'category'),''),category) else category end,
    brand=case when p_patch ? 'brand' then nullif(trim(p_patch->>'brand'),'') else brand end,
    description=description_v,
    main_group=case when p_patch ? 'main_group' then nullif(trim(p_patch->>'main_group'),'') else main_group end,
    subgroup=case when p_patch ? 'subgroup' then nullif(trim(p_patch->>'subgroup'),'') else subgroup end,
    size=case when p_patch ? 'size' then nullif(trim(p_patch->>'size'),'') else size end,
    uom=case when p_patch ? 'uom' then coalesce(nullif(upper(trim(p_patch->>'uom')),''),uom) else uom end,
    movement=movement_v,
    max_stock=max_v,
    remarks=case when p_patch ? 'remarks' then nullif(trim(p_patch->>'remarks'),'') else remarks end,
    updated_at=now()
  where id=p_item_id
  returning * into updated_item;

  return updated_item;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_update_requirement_qty_v2(p_requirement_id uuid, p_adjusted_qty numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare caller_role text; r public.proc_requirements;
begin
  select role into caller_role from public.proc_profiles where id=auth.uid() and active=true;
  if caller_role is null or caller_role not in ('admin','procurement') then raise exception 'Not authorized'; end if;
  if p_adjusted_qty < 0 then raise exception 'Adjusted quantity cannot be negative'; end if;
  select * into r from public.proc_requirements where id=p_requirement_id for update;
  if r.id is null then raise exception 'Requirement not found'; end if;
  if p_adjusted_qty < greatest(r.ordered_qty,r.received_qty) then raise exception 'Adjusted quantity cannot be below committed quantity'; end if;
  update public.proc_requirements set adjusted_qty=p_adjusted_qty,updated_at=now() where id=r.id;
  return p_adjusted_qty;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_verify_location_v1(p_latitude double precision, p_longitude double precision, p_accuracy double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.proc_access_rules;distance_m double precision;s uuid;reason text;answer jsonb;
begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='42501';end if;
 answer:=public.proc_access_status_v1();
 if (answer->>'exempt')::boolean or answer->>'reason' in ('disabled','outside_hours') then return answer;end if;
 r:=private.proc_access_rule();if not r.location_enabled then return answer;end if;
 s:=nullif(auth.jwt()->>'session_id','')::uuid;
 if s is null then raise exception 'A signed-in session is required' using errcode='42501';end if;
 delete from private.proc_access_leases where user_id=auth.uid() and session_id=s;
 if p_latitude is null or not (p_latitude between -90 and 90) or p_longitude is null or not (p_longitude between -180 and 180)
 or p_accuracy is null or not (p_accuracy between 0 and 50) then reason:='inaccurate_location';
 else
  distance_m:=6371000*2*asin(sqrt(least(1.0,
   power(sin(radians(p_latitude-r.latitude)/2),2)+cos(radians(r.latitude))*cos(radians(p_latitude))*power(sin(radians(p_longitude-r.longitude)/2),2))));
  -- The reported uncertainty must also fit inside the permitted area.
  if distance_m+p_accuracy>r.radius_m then reason:='outside_location';
  else
   insert into private.proc_access_leases(user_id,session_id,revision,expires_at)
   values(auth.uid(),s,r.revision,now()+interval '90 seconds');reason:='allowed';
  end if;
 end if;
 answer:=public.proc_access_status_v1();
 return answer||jsonb_build_object('allowed',reason='allowed','reason',reason);
end $function$

CREATE OR REPLACE FUNCTION public.proc_whatsapp_claim_dispatch(p_rfq_id uuid, p_supplier_id uuid, p_session text, p_image_sha256 text, p_caption text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

declare v_id uuid;
begin
 if auth.uid() is null or not private.proc_is_role(array['admin','procurement']) or not private.proc_has_permission('procurement.rfq.manage') then raise exception 'Unauthorized WhatsApp dispatch'; end if;
 if length(p_image_sha256)<>64 or length(p_caption)>2000 or length(p_session)>50 then raise exception 'Invalid dispatch fields'; end if;
 if not exists (select 1 from public.proc_rfqs r join public.proc_rfq_suppliers i on i.rfq_id=r.id join public.proc_suppliers s on s.id=i.supplier_id where r.id=p_rfq_id and s.id=p_supplier_id and s.active and i.status in ('pending','prepared') and r.status not in ('awarded','closed','cancelled')) then raise exception 'Supplier not eligible for RFQ'; end if;
 insert into public.proc_whatsapp_rfq_dispatches(rfq_id,supplier_id,sent_by,gateway_session,status,image_sha256,caption) values(p_rfq_id,p_supplier_id,auth.uid(),p_session,'sending',p_image_sha256,p_caption) returning id into v_id;
 return v_id;
end;
end;$function$

CREATE OR REPLACE FUNCTION public.proc_whatsapp_finish_dispatch(p_id uuid, p_status text, p_message_id text, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform private.proc_assert_access();

begin
 if auth.uid() is null or not private.proc_is_role(array['admin','procurement']) then raise exception 'Unauthorized WhatsApp dispatch'; end if;
 if p_status not in ('accepted','failed','unknown') then raise exception 'Invalid dispatch status'; end if;
 update public.proc_whatsapp_rfq_dispatches set status=p_status,message_id=left(p_message_id,500),last_error=left(p_error,1000),updated_at=now() where id=p_id and sent_by=auth.uid() and status='sending';
 return found;
end;
end;$function$
